export default "ls import provider_registry\\n    from lfx.base.models.unified_models import get_live_only_providers, get_model_providers\\n    from lfx.extension import load_extension\\n\\n    provider_registry.clear()\\n    try:\\n        root = Path(__file__).resolve().parents[1] / \\\"src\\\" / \\\"lfx_openai_compatible\\\"\\n        result = load_extension(root)\\n        assert result.ok, (result.errors, result.warnings)\\n        assert result.components == []  # provider-only bundle: no components\\n        assert provider_registry.is_registered(\\\"OpenAI Compatible\\\")\\n        assert \\\"OpenAI Compatible\\\" in get_model_providers()\\n        # No static catalog + live discovery => must surface through the\\n        # /api/v1/models live-only union so the unconfigured provider is\\n        # offered for configuration in the Model Providers dialog.\\n        assert \\\"OpenAI Compatible\\\" in get_live_only_providers()\\n        assert provider_registry.is_api_key_optional(\\\"OpenAI Compatible\\\")\\n        assert provider_registry.live_discovery_for(\\\"OpenAI Compatible\\\") is not None\\n        assert provider_registry.validator_for(\\\"OpenAI Compatible\\\") is not None\\n    finally:\\n        provider_registry.clear()\\n\\n\\n@contextmanager\\ndef _openai_compatible_embeddings(monkeypatch, handler, base_url=\\\"https://compatible.example/v1\\\"):\\n    \\\"\\\"\\\"Yield real OpenAI-compatible embeddings backed by a mock HTTP transport.\\\"\\\"\\\"\\n    from lfx.base.models import provider_registry, unified_models\\n    from lfx.base.models.unified_models import instantiation\\n    from lfx.base.models.unified_models.instantiation import get_embeddings\\n    from lfx.extension import load_extension\\n\\n    provider_registry.clear()\\n    try:\\n        root = Path(__file__).resolve().parents[1] / \\\"src\\\" / \\\"lfx_openai_compatible\\\"\\n        result = load_extension(root)\\n        assert result.ok, (result.errors, result.warnings)\\n\\n        monkeypatch.setattr(unified_models, \\\"get_api_key_for_provider\\\", lambda *_args, **_kwargs: None)\\n        monkeypatch.setattr(\\n            unified_models,\\n            \\\"get_all_variables_for_provider\\\",\\n            lambda *_args, **_kwargs: {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": base_url},\\n        )\\n\\n        with httpx.Client(transport=httpx.MockTransport(handler)) as client:\\n            monkeypatch.setattr(\\n                instantiation,\\n                \\\"ssrf_protected_openai_clients_for_url\\\",\\n                lambda _url: {\\\"http_client\\\": client},\\n            )\\n            yield get_embeddings([{\\\"name\\\": \\\"nomic-embed-text\\\", \\\"provider\\\": \\\"OpenAI Compatible\\\", \\\"metadata\\\": {}}])\\n    finally:\\n        provider_registry.clear()\\n\\n\\n@contextmanager\\ndef _openai_compatible_chat(monkeypatch, handler, base_url):\\n    \\\"\\\"\\\"Yield a real OpenAI-compatible chat model backed by a mock HTTP transport.\\\"\\\"\\\"\\n    from lfx.base.models import provider_registry, unified_models\\n    from lfx.base.models.unified_models import instantiation\\n    from lfx.base.models.unified_models.instantiation import get_llm\\n    from lfx.extension import load_extension\\n\\n    provider_registry.clear()\\n    try:\\n        root = Path(__file__).resolve().parents[1] / \\\"src\\\" / \\\"lfx_openai_compatible\\\"\\n        result = load_extension(root)\\n        assert result.ok, (result.errors, result.warnings)\\n\\n        monkeypatch.setattr(unified_models, \\\"get_api_key_for_provider\\\", lambda *_args, **_kwargs: None)\\n        monkeypatch.setattr(\\n            unified_models,\\n            \\\"get_all_variables_for_provider\\\",\\n            lambda *_args, **_kwargs: {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": base_url},\\n        )\\n\\n        with httpx.Client(transport=httpx.MockTransport(handler)) as client:\\n            monkeypatch.setattr(\\n                instantiation,\\n                \\\"ssrf_protected_openai_clients_for_url\\\",\\n                lambda _url: {\\\"http_client\\\": client},\\n            )\\n            yield get_llm(\\n                [{\\\"name\\\": \\\"qwen2.5\\\", \\\"provider\\\": \\\"OpenAI Compatible\\\", \\\"metadata\\\": {}}],\\n                user_id=None,\\n            )\\n    finally:\\n        provider_registry.clear()\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"base_url\\\",\\n    [\\n        \\\"https://compatible.example\\\",\\n        \\\"https://compatible.example/\\\",\\n        \\\"https://compatible.example/v1\\\",\\n        \\\"https://compatible.example/v1/\\\",\\n    ],\\n)\\ndef test_chat_runtime_normalizes_openai_compatible_base_url(monkeypatch, base_url):\\n    \\\"\\\"\\\"A URL accepted by validation must use the same /v1 API root at runtime.\\\"\\\"\\\"\\n    captured_urls = []\\n\\n    def handle_request(request: httpx.Request) -> httpx.Response:\\n        \\\"\\\"\\\"Capture one successful chat completion request.\\\"\\\"\\\"\\n        captured_urls.append(str(request.url))\\n        return httpx.Response(\\n            200,\\n            json={\\n                \\\"id\\\": \\\"chatcmpl-test\\\",\\n                \\\"object\\\": \\\"chat.completion\\\",\\n                \\\"created\\\": 0,\\n                \\\"model\\\": \\\"qwen2.5\\\",\\n                \\\"choices\\\": [\\n                    {\\n                        \\\"index\\\": 0,\\n                        \\\"message\\\": {\\\"role\\\": \\\"assistant\\\", \\\"content\\\": \\\"ok\\\"},\\n                        \\\"finish_reason\\\": \\\"stop\\\",\\n                    }\\n                ],\\n                \\\"usage\\\": {\\\"prompt_tokens\\\": 1, \\\"completion_tokens\\\": 1, \\\"total_tokens\\\": 2},\\n            },\\n            request=request,\\n        )\\n\\n    with _openai_compatible_chat(monkeypatch, handle_request, base_url) as chat_model:\\n        chat_model.invoke(\\\"hello world\\\")\\n\\n    assert captured_urls == [\\\"https://compatible.example/v1/chat/completions\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"base_url\\\",\\n    [\\n        \\\"https://compatible.example\\\",\\n        \\\"https://compatible.example/\\\",\\n        \\\"https://compatible.example/v1\\\",\\n        \\\"https://compatible.example/v1/\\\",\\n    ],\\n)\\ndef test_embeddings_runtime_normalizes_openai_compatible_base_url(monkeypatch, base_url):\\n    \\\"\\\"\\\"Embedding requests use the same normalized /v1 API root as chat requests.\\\"\\\"\\\"\\n    captured_urls = []\\n\\n    def handle_request(request: httpx.Request) -> httpx.Response:\\n        \\\"\\\"\\\"Capture one successful embedding request.\\\"\\\"\\\"\\n        captured_urls.append(str(request.url))\\n        return httpx.Response(\\n            200,\\n            json={\\n                \\\"data\\\": [{\\\"embedding\\\": [0.1], \\\"index\\\": 0}],\\n                \\\"model\\\": \\\"nomic-embed-text\\\",\\n                \\\"usage\\\": {\\\"prompt_tokens\\\": 2, \\\"total_tokens\\\": 2},\\n            },\\n            request=request,\\n        )\\n\\n    with _openai_compatible_embeddings(monkeypatch, handle_request, base_url) as embeddings:\\n        embeddings.embed_query(\\\"hello world\\\")\\n\\n    assert captured_urls == [\\\"https://compatible.example/v1/embeddings\\\"]\\n\\n\\ndef test_embeddings_send_string_input_to_compatible_endpoint(monkeypatch):\\n    \\\"\\\"\\\"OpenAI-compatible servers receive text, not OpenAI-only token arrays.\\\"\\\"\\\"\\n    captured_inputs = []\\n\\n    def handle_request(request: httpx.Request) -> httpx.Response:\\n        \\\"\\\"\\\"Capture one successful query request.\\\"\\\"\\\"\\n        captured_inputs.append(json.loads(request.content)[\\\"input\\\"])\\n        return httpx.Response(\\n            200,\\n            json={\\n                \\\"data\\\": [{\\\"embedding\\\": [0.1], \\\"index\\\": 0}],\\n                \\\"model\\\": \\\"nomic-embed-text\\\",\\n                \\\"usage\\\": {\\\"prompt_tokens\\\": 2, \\\"total_tokens\\\": 2},\\n            },\\n            request=request,\\n        )\\n\\n    with _openai_compatible_embeddings(monkeypatch, handle_request) as embeddings:\\n        embeddings.embed_query(\\\"hello world\\\")\\n\\n    assert captured_inputs == [[\\\"hello world\\\"]]\\n\\n\\ndef test_embeddings_preserve_batch_strings_and_empty_input(monkeypatch):\\n    \\\"\\\"\\\"Batch embedding preserves string shape, including an empty boundary value.\\\"\\\"\\\"\\n    captured_inputs = []\\n    texts = [\\\"\\\", \\\"first document\\\", \\\"second document\\\"]\\n\\n    def handle_request(request: httpx.Request) -> httpx.Response:\\n        \\\"\\\"\\\"Return one embedding for every captured batch item.\\\"\\\"\\\"\\n        request_inputs = json.loads(request.content)[\\\"input\\\"]\\n        captured_inputs.append(request_inputs)\\n        return httpx.Response(\\n            200,\\n            json={\\n                \\\"data\\\": [{\\\"embedding\\\": [0.1, float(index)], \\\"index\\\": index} for index in range(len(request_inputs))],\\n                \\\"model\\\": \\\"nomic-embed-text\\\",\\n                \\\"usage\\\": {\\\"prompt_tokens\\\": 4, \\\"total_tokens\\\": 4},\\n            },\\n            request=request,\\n        )\\n\\n    with _openai_compatible_embeddings(monkeypatch, handle_request) as embeddings:\\n        result = embeddings.embed_documents(texts)\\n\\n    assert captured_inputs == [texts]\\n    assert len(result) == len(texts)\\n\\n\\ndef test_embeddings_propagate_compatible_endpoint_errors(monkeypatch):\\n    \\\"\\\"\\\"A compatible endpoint error remains visible to the flow execution path.\\\"\\\"\\\"\\n    from openai import BadRequestError\\n\\n    captured_inputs = []\\n\\n    def handle_request(request: httpx.Request) -> httpx.Response:\\n        \\\"\\\"\\\"Reject the request with the endpoint's invalid-input response.\\\"\\\"\\\"\\n        captured_inputs.append(json.loads(request.content)[\\\"input\\\"])\\n        return httpx.Response(\\n            400,\\n            json={\\\"error\\\": {\\\"message\\\": \\\"invalid input type\\\", \\\"type\\\": \\\"invalid_request_error\\\"}},\\n            request=request,\\n        )\\n\\n    with (\\n        _openai_compatible_embeddings(monkeypatch, handle_request) as embeddings,\\n        pytest.raises(BadRequestError, match=\\\"invalid input type\\\") as exc_info,\\n    ):\\n        embeddings.embed_query(\\\"rejected input\\\")\\n\\n    assert exc_info.value.status_code == 400\\n    assert captured_inputs == [[\\\"rejected input\\\"]]\\n\\n\\ndef _ok_response(payload: dict | list) -> MagicMock:\\n    resp = MagicMock()\\n    resp.json.return_value = payload\\n    resp.status_code = 200\\n    resp.raise_for_status.return_value = None\\n    return resp\\n\\n\\ndef _set_loopback_policy(monkeypatch, *, allowed: bool) -> None:\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", str(allowed).lower())\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n\\n# ---------------------------------------------------------------------------\\n# fetch_live_openai_compatible_models\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_fetch_returns_empty_when_no_base_url():\\n    with patch.object(discovery, \\\"get_provider_variable_value\\\", return_value=None):\\n        assert discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_allows_literal_loopback_by_default(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=True)\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"local-model\\\"}]})\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://127.0.0.1:1234/v1\\\", None]),\\n        patch(\\\"httpx.Client.get\\\", return_value=response) as mock_get,\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    assert [model[\\\"name\\\"] for model in result] == [\\\"local-model\\\"]\\n    mock_get.assert_called_once()\\n    assert mock_get.call_args.kwargs[\\\"follow_redirects\\\"] is False\\n\\n\\ndef test_fetch_blocks_literal_loopback_when_connector_policy_opts_out(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=False)\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://127.0.0.1:1234/v1\\\", None]),\\n        patch(\\\"httpx.Client.get\\\") as mock_get,\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    assert result == []\\n    mock_get.assert_not_called()\\n\\n\\ndef test_fetch_does_not_follow_redirects(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=True)\\n    request = httpx.Request(\\\"GET\\\", \\\"http://127.0.0.1:1234/v1/models\\\")\\n    redirect = httpx.Response(302, headers={\\\"location\\\": \\\"http://169.254.169.254/latest/meta-data/\\\"}, request=request)\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://127.0.0.1:1234/v1\\\", None]),\\n        patch(\\\"httpx.Client.get\\\", return_value=redirect) as mock_get,\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n\\n    assert result == []\\n    mock_get.assert_called_once()\\n    assert mock_get.call_args.kwargs[\\\"follow_redirects\\\"] is False\\n\\n\\ndef test_fetch_openai_dict_format():\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"meta-llama/llama-3.1-8b\\\"}, {\\\"id\\\": \\\"mistral-7b\\\"}]})\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"https://openrouter.ai/api/v1\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert {m[\\\"name\\\"] for m in result} == {\\\"meta-llama/llama-3.1-8b\\\", \\\"mistral-7b\\\"}\\n    assert all(m[\\\"provider\\\"] == \\\"OpenAI Compatible\\\" and m[\\\"icon\\\"] == \\\"Plug\\\" for m in result)\\n    assert all(m[\\\"tool_calling\\\"] for m in result)  # llm context -> tool calling on\\n\\n\\ndef test_fetch_plain_list_format():\\n    response = _ok_response([\\\"qwen2-7b\\\", \\\"deepseek-r1\\\"])\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert {m[\\\"name\\\"] for m in result} == {\\\"qwen2-7b\\\", \\\"deepseek-r1\\\"}\\n\\n\\ndef test_fetch_sorts_alphabetically():\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"zzz\\\"}, {\\\"id\\\": \\\"aaa\\\"}, {\\\"id\\\": \\\"mmm\\\"}]})\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert [m[\\\"name\\\"] for m in result] == [\\\"aaa\\\", \\\"mmm\\\", \\\"zzz\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"base_url\\\", \\\"expected\\\"),\\n    [\\n        (\\\"http://localhost:8000\\\", \\\"http://localhost:8000/v1/models\\\"),\\n        (\\\"http://localhost:8000/v1\\\", \\\"http://localhost:8000/v1/models\\\"),\\n        (\\\"http://localhost:8000/\\\", \\\"http://localhost:8000/v1/models\\\"),\\n        (\\\"https://api.groq.com/openai/v1\\\", \\\"https://api.groq.com/openai/v1/models\\\"),\\n    ],\\n)\\ndef test_fetch_models_url_normalization(base_url, expected):\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"llama-3\\\"}]})\\n    captured: list[str] = []\\n\\n    def fake_get(url, **_kwargs):\\n        captured.append(url)\\n        return response\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[base_url, None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=fake_get),\\n    ):\\n        discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert captured[0] == expected\\n\\n\\ndef test_fetch_forwards_api_key_as_bearer():\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"llama-3\\\"}]})\\n    captured: list[dict] = []\\n\\n    def fake_get(_url, headers=None, **_kwargs):\\n        captured.append(headers or {})\\n        return response\\n\\n    with (\\n        patch.object(\\n            discovery,\\n            \\\"get_provider_variable_value\\\",\\n            side_effect=[\\\"http://localhost:8000\\\", \\\"secret-key\\\"],  # pragma: allowlist secret\\n        ),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=fake_get),\\n    ):\\n        discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert captured[0].get(\\\"Authorization\\\") == \\\"Bearer secret-key\\\"  # pragma: allowlist secret\\n\\n\\ndef test_fetch_no_auth_header_when_no_key():\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"llama-3\\\"}]})\\n    captured: list[dict] = []\\n\\n    def fake_get(_url, headers=None, **_kwargs):\\n        captured.append(headers or {})\\n        return response\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=fake_get),\\n    ):\\n        discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert \\\"Authorization\\\" not in captured[0]\\n\\n\\ndef test_fetch_swallows_connection_error():\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=httpx.ConnectError(\\\"refused\\\")),\\n    ):\\n        assert discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_swallows_bad_payload():\\n    response = _ok_response({\\\"unexpected\\\": \\\"shape\\\"})\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        assert discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\") == []\\n\\n\\ndef test_fetch_swallows_api_key_lookup_error():\\n    \\\"\\\"\\\"A failing API-key lookup falls back to anonymous discovery instead of blocking it.\\\"\\\"\\\"\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"llama-3\\\"}]})\\n\\n    def fake_get_var(_user_id, key):\\n        if key == \\\"OPENAI_COMPATIBLE_BASE_URL\\\":\\n            return \\\"http://localhost:8000\\\"\\n        msg = \\\"variable not found\\\"\\n        raise RuntimeError(msg)\\n\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=fake_get_var),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"llm\\\")\\n    assert {m[\\\"name\\\"] for m in result} == {\\\"llama-3\\\"}\\n\\n\\ndef test_fetch_embeddings_tagged_embeddings():\\n    response = _ok_response({\\\"data\\\": [{\\\"id\\\": \\\"bge-m3\\\"}]})\\n    with (\\n        patch.object(discovery, \\\"get_provider_variable_value\\\", side_effect=[\\\"http://localhost:8000\\\", None]),\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n    ):\\n        result = discovery.fetch_live_openai_compatible_models(\\\"user-id\\\", \\\"embeddings\\\")\\n    assert result[0][\\\"model_type\\\"] == \\\"embeddings\\\"\\n    assert result[0][\\\"tool_calling\\\"] is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# validate_openai_compatible_credentials\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_validate_raises_when_no_base_url():\\n    with pytest.raises(ValueError, match=\\\"Invalid OpenAI-compatible base URL\\\"):\\n        discovery.validate_openai_compatible_credentials(\\\"OpenAI Compatible\\\", {})\\n\\n\\ndef test_validate_happy_path_uses_v1_models():\\n    response = _ok_response({\\\"data\\\": []})\\n    captured: list[str] = []\\n\\n    def fake_get(url, **_kwargs):\\n        captured.append(url)\\n        return response\\n\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=fake_get),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000/v1\\\"}\\n        )\\n    assert captured[0] == \\\"http://localhost:8000/v1/models\\\"\\n\\n\\ndef test_validate_allows_literal_loopback_by_default(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=True)\\n    response = _ok_response({\\\"data\\\": []})\\n\\n    with patch(\\\"httpx.Client.get\\\", return_value=response) as mock_get:\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://127.0.0.1:1234/v1\\\"}\\n        )\\n\\n    mock_get.assert_called_once()\\n    assert mock_get.call_args.kwargs[\\\"url\\\"] == \\\"http://127.0.0.1:1234/v1/models\\\"\\n    assert mock_get.call_args.kwargs[\\\"follow_redirects\\\"] is False\\n\\n\\ndef test_validate_blocks_literal_loopback_when_connector_policy_opts_out(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=False)\\n\\n    with (\\n        patch(\\\"httpx.Client.get\\\") as mock_get,\\n        pytest.raises(ValueError, match=r\\\"127\\\\.0\\\\.0\\\\.1.*blocked\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://127.0.0.1:1234/v1\\\"}\\n        )\\n\\n    mock_get.assert_not_called()\\n\\n\\ndef test_validate_does_not_follow_redirects(monkeypatch):\\n    _set_loopback_policy(monkeypatch, allowed=True)\\n    request = httpx.Request(\\\"GET\\\", \\\"http://127.0.0.1:1234/v1/models\\\")\\n    redirect = httpx.Response(302, headers={\\\"location\\\": \\\"http://169.254.169.254/latest/meta-data/\\\"}, request=request)\\n\\n    with (\\n        patch(\\\"httpx.Client.get\\\", return_value=redirect) as mock_get,\\n        pytest.raises(ValueError, match=\\\"returned HTTP 302\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://127.0.0.1:1234/v1\\\"}\\n        )\\n\\n    mock_get.assert_called_once()\\n    assert mock_get.call_args.kwargs[\\\"follow_redirects\\\"] is False\\n\\n\\ndef test_validate_forwards_api_key():\\n    response = _ok_response({\\\"data\\\": []})\\n    captured: dict = {}\\n\\n    def fake_get(_url, **kwargs):\\n        captured.update(kwargs)\\n        return response\\n\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=fake_get),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\",\\n            {\\n                \\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000\\\",\\n                \\\"OPENAI_COMPATIBLE_API_KEY\\\": \\\"k\\\",  # pragma: allowlist secret\\n            },\\n        )\\n    assert captured[\\\"headers\\\"][\\\"Authorization\\\"] == \\\"Bearer k\\\"  # pragma: allowlist secret\\n\\n\\n@pytest.mark.parametrize(\\\"status\\\", [401, 403])\\ndef test_validate_raises_on_auth_failure(status):\\n    response = MagicMock()\\n    response.status_code = status\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n        pytest.raises(ValueError, match=\\\"Authentication failed\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000\\\"}\\n        )\\n\\n\\ndef test_validate_raises_value_error_on_server_error():\\n    \\\"\\\"\\\"Non-auth HTTP failures (e.g. 500) surface as the same user-facing ValueError shape.\\\"\\\"\\\"\\n    response = MagicMock()\\n    response.status_code = 500\\n    request = httpx.Request(\\\"GET\\\", \\\"http://localhost:8000/v1/models\\\")\\n    error_response = httpx.Response(500, request=request)\\n    http_error = httpx.HTTPStatusError(\\\"server error\\\", request=request, response=error_response)\\n    response.raise_for_status.side_effect = http_error\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", return_value=response),\\n        pytest.raises(ValueError, match=\\\"returned HTTP 500\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000\\\"}\\n        )\\n\\n\\ndef test_validate_raises_on_connection_error():\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=httpx.ConnectError(\\\"refused\\\")),\\n        pytest.raises(ValueError, match=\\\"Could not connect to the OpenAI-compatible endpoint\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000\\\"}\\n        )\\n\\n\\ndef test_validate_raises_on_timeout():\\n    with (\\n        patch.object(discovery, \\\"ssrf_safe_httpx_get\\\", side_effect=httpx.ReadTimeout(\\\"slow\\\")),\\n        pytest.raises(ValueError, match=\\\"timed out\\\"),\\n    ):\\n        discovery.validate_openai_compatible_credentials(\\n            \\\"OpenAI Compatible\\\", {\\\"OPENAI_COMPATIBLE_BASE_URL\\\": \\\"http://localhost:8000\\\"}\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f69153fc8da0a794014703afa07a3db4641ed6a88c1b4968db3a86c9fa6a8f6c\",\"content\":\"# lfx-openai\\n\\nOpenAI component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-openai\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `openai` group with\\nthe namespaced IDs `ext:openai:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/openai\\npip install -e .\\nlfx extension validate src/lfx_openai\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.openai.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"759e3539e154a847b33c109de9721a13dba92da88f363310707746c3aaa8d521\",\"content\":\"[project]\\nname = \\\"lfx-openai\\\"\\nversion = \\\"0.1.4\\\"\\ndescription = \\\"OpenAI component(s) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"openai\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.11.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-openai>=1.1.6\\\",\\n    \\\"openai>=1.68.2,<3.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-openai = \\\"lfx_openai\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_openai package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_openai\\\"]\\ninclude = [\\n    \\\"src/lfx_openai/extension.json\\\",\\n    \\\"src/lfx_openai/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_openai\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac40f2f41e15af49184fe5cea19f2df31cf6f358183c590952e3d38f80d24c54\",\"content\":\"\\\"\\\"\\\"lfx-openai: OpenAI bundle.\\n\\nDistribution unit ``lfx-openai``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:openai:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_openai.components.openai.openai import OpenAIEmbeddingsComponent\\nfrom lfx_openai.components.openai.openai_chat_model import OpenAIModelComponent\\n\\n__all__ = [\\n    \\\"OpenAIEmbeddingsComponent\\\",\\n    \\\"OpenAIModelComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/components/openai/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa77a56aa0fa5b5c0860da53238dba27a3a6b116319d44df9a912ed6afd5cd0f\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``openai`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.openai`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.openai.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_openai.components.openai.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .openai import OpenAIEmbeddingsComponent\\n    from .openai_chat_model import OpenAIModelComponent\\n\\n_dynamic_imports = {\\n    \\\"OpenAIEmbeddingsComponent\\\": \\\"openai\\\",\\n    \\\"OpenAIModelComponent\\\": \\\"openai_chat_model\\\",\\n}\\n\\n__all__ = [\\n    \\\"OpenAIEmbeddingsComponent\\\",\\n    \\\"OpenAIModelComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/components/openai/openai.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1ad4754ff1778174f4671b3f6d13329a07fe52aa96c9ec5e95095d39d7ff59e3\",\"content\":\"from langchain_openai import OpenAIEmbeddings\\nfrom lfx.base.embeddings.model import LCEmbeddingsModel\\nfrom lfx.base.models.openai_constants import OPENAI_EMBEDDING_MODEL_NAMES\\nfrom lfx.base.models.provider_ssrf import openai_compatible_client_kwargs\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import BoolInput, DictInput, DropdownInput, FloatInput, IntInput, MessageTextInput, SecretStrInput\\n\\nfrom lfx_openai.components.openai.openai_chat_model import DEFAULT_OPENAI_API_BASE\\n\\n\\nclass OpenAIEmbeddingsComponent(LCEmbeddingsModel):\\n    display_name = \\\"OpenAI Embeddings\\\"\\n    description = \\\"Generate embeddings using OpenAI models.\\\"\\n    icon = \\\"OpenAI\\\"\\n    name = \\\"OpenAIEmbeddings\\\"\\n\\n    inputs = [\\n        DictInput(\\n            name=\\\"default_headers\\\",\\n            display_name=\\\"Default Headers\\\",\\n            advanced=True,\\n            info=\\\"Default headers to use for the API request.\\\",\\n        ),\\n        DictInput(\\n            name=\\\"default_query\\\",\\n            display_name=\\\"Default Query\\\",\\n            advanced=True,\\n            info=\\\"Default query parameters to use for the API request.\\\",\\n        ),\\n        IntInput(name=\\\"chunk_size\\\", display_name=\\\"Chunk Size\\\", advanced=True, value=1000),\\n        MessageTextInput(name=\\\"client\\\", display_name=\\\"Client\\\", advanced=True),\\n        MessageTextInput(name=\\\"deployment\\\", display_name=\\\"Deployment\\\", advanced=True),\\n        IntInput(name=\\\"embedding_ctx_length\\\", display_name=\\\"Embedding Context Length\\\", advanced=True, value=1536),\\n        IntInput(name=\\\"max_retries\\\", display_name=\\\"Max Retries\\\", value=3, advanced=True),\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            advanced=False,\\n            options=OPENAI_EMBEDDING_MODEL_NAMES,\\n            value=\\\"text-embedding-3-small\\\",\\n        ),\\n        DictInput(name=\\\"model_kwargs\\\", display_name=\\\"Model Kwargs\\\", advanced=True),\\n        SecretStrInput(name=\\\"openai_api_key\\\", display_name=\\\"OpenAI API Key\\\", value=\\\"OPENAI_API_KEY\\\", required=True),\\n        MessageTextInput(name=\\\"openai_api_base\\\", display_name=\\\"OpenAI API Base\\\", advanced=True),\\n        MessageTextInput(name=\\\"openai_api_type\\\", display_name=\\\"OpenAI API Type\\\", advanced=True),\\n        MessageTextInput(name=\\\"openai_api_version\\\", display_name=\\\"OpenAI API Version\\\", advanced=True),\\n        MessageTextInput(\\n            name=\\\"openai_organization\\\",\\n            display_name=\\\"OpenAI Organization\\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(name=\\\"openai_proxy\\\", display_name=\\\"OpenAI Proxy\\\", advanced=True),\\n        FloatInput(name=\\\"request_timeout\\\", display_name=\\\"Request Timeout\\\", advanced=True),\\n        BoolInput(name=\\\"show_progress_bar\\\", display_name=\\\"Show Progress Bar\\\", advanced=True),\\n        BoolInput(name=\\\"skip_empty\\\", display_name=\\\"Skip Empty\\\", advanced=True),\\n        MessageTextInput(\\n            name=\\\"tiktoken_model_name\\\",\\n            display_name=\\\"TikToken Model Name\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"tiktoken_enable\\\",\\n            display_name=\\\"TikToken Enable\\\",\\n            advanced=True,\\n            value=True,\\n            info=\\\"If False, you must have transformers installed.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"dimensions\\\",\\n            display_name=\\\"Dimensions\\\",\\n            info=\\\"The number of dimensions the resulting output embeddings should have. \\\"\\n            \\\"Only supported by certain models.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        # openai_api_base is tenant-editable and the SDK sends the operator's stored API key to\\n        # whatever host it names. Apply the connector SSRF policy and route a custom endpoint\\n        # through DNS-pinned, redirect-free clients. No-op for the default OpenAI endpoint.\\n        ssrf_client_kwargs = openai_compatible_client_kwargs(self.openai_api_base, default_url=DEFAULT_OPENAI_API_BASE)\\n\\n        return OpenAIEmbeddings(\\n            client=self.client or None,\\n            model=self.model,\\n            dimensions=self.dimensions or None,\\n            deployment=self.deployment or None,\\n            api_version=self.openai_api_version or None,\\n            base_url=self.openai_api_base or None,\\n            openai_api_type=self.openai_api_type or None,\\n            openai_proxy=self.openai_proxy or None,\\n            embedding_ctx_length=self.embedding_ctx_length,\\n            api_key=self.openai_api_key or None,\\n            organization=self.openai_organization or None,\\n            allowed_special=\\\"all\\\",\\n            disallowed_special=\\\"all\\\",\\n            chunk_size=self.chunk_size,\\n            max_retries=self.max_retries,\\n            timeout=self.request_timeout or None,\\n            tiktoken_enabled=self.tiktoken_enable,\\n            tiktoken_model_name=self.tiktoken_model_name or None,\\n            show_progress_bar=self.show_progress_bar,\\n            model_kwargs=self.model_kwargs,\\n            skip_empty=self.skip_empty,\\n            default_headers=self.default_headers or None,\\n            default_query=self.default_query or None,\\n            **ssrf_client_kwargs,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/components/openai/openai_chat_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0690d6c6417d83b0299ded23705358efb9c17f8e28fa693dc997e8f558c7e6a\",\"content\":\"from typing import Any\\n\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES, OPENAI_REASONING_MODEL_NAMES\\nfrom lfx.base.models.provider_ssrf import openai_compatible_client_kwargs\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import BoolInput, DictInput, DropdownInput, IntInput, SecretStrInput, SliderInput, StrInput\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.secrets import secret_value_to_str\\n\\nDEFAULT_OPENAI_API_BASE = \\\"https://api.openai.com/v1\\\"\\n\\n\\nclass OpenAIModelComponent(LCModelComponent):\\n    display_name = \\\"OpenAI\\\"\\n    description = \\\"Generates text using OpenAI LLMs.\\\"\\n    icon = \\\"OpenAI\\\"\\n    name = \\\"OpenAIModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n            range_spec=RangeSpec(min=0, max=128000),\\n        ),\\n        DictInput(\\n            name=\\\"model_kwargs\\\",\\n            display_name=\\\"Model Kwargs\\\",\\n            advanced=True,\\n            info=\\\"Additional keyword arguments to pass to the model.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"json_mode\\\",\\n            display_name=\\\"JSON Mode\\\",\\n            advanced=True,\\n            info=\\\"If True, it will output JSON regardless of passing a schema.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            options=OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n            combobox=True,\\n            real_time_refresh=True,\\n        ),\\n        StrInput(\\n            name=\\\"openai_api_base\\\",\\n            display_name=\\\"OpenAI API Base\\\",\\n            advanced=True,\\n            info=\\\"The base URL of the OpenAI API. \\\"\\n            \\\"Defaults to https://api.openai.com/v1. \\\"\\n            \\\"You can change this to use other APIs like JinaChat, LocalAI and Prem.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"OpenAI API Key\\\",\\n            info=\\\"The OpenAI API Key to use for the OpenAI model.\\\",\\n            advanced=False,\\n            value=\\\"OPENAI_API_KEY\\\",\\n            required=True,\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            show=True,\\n        ),\\n        IntInput(\\n            name=\\\"seed\\\",\\n            display_name=\\\"Seed\\\",\\n            info=\\\"The seed controls the reproducibility of the job.\\\",\\n            advanced=True,\\n            value=1,\\n        ),\\n        IntInput(\\n            name=\\\"max_retries\\\",\\n            display_name=\\\"Max Retries\\\",\\n            info=\\\"The maximum number of retries to make when generating.\\\",\\n            advanced=True,\\n            value=5,\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            info=\\\"The timeout for requests to OpenAI completion API.\\\",\\n            advanced=True,\\n            value=700,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        logger.debug(f\\\"Executing request with model: {self.model_name}\\\")\\n        logger.debug(f\\\"API key type: {type(self.api_key)}, value: {'***' if self.api_key else None}\\\")\\n        api_key_value = secret_value_to_str(self.api_key) if self.api_key else None\\n        logger.debug(f\\\"Final api_key_value type: {type(api_key_value)}, value: {'***' if api_key_value else None}\\\")\\n\\n        # Handle model_kwargs and ensure api_key doesn't conflict\\n        model_kwargs = self.model_kwargs or {}\\n        # Remove api_key from model_kwargs if it exists to prevent conflicts\\n        if \\\"api_key\\\" in model_kwargs:\\n            logger.warning(\\\"api_key found in model_kwargs, removing to prevent conflicts\\\")\\n            model_kwargs = dict(model_kwargs)  # Make a copy\\n            del model_kwargs[\\\"api_key\\\"]\\n\\n        parameters = {\\n            \\\"api_key\\\": api_key_value,\\n            \\\"model_name\\\": self.model_name,\\n            \\\"max_tokens\\\": self.max_tokens or None,\\n            \\\"model_kwargs\\\": model_kwargs,\\n            \\\"base_url\\\": self.openai_api_base or DEFAULT_OPENAI_API_BASE,\\n            \\\"max_retries\\\": self.max_retries,\\n            \\\"timeout\\\": self.timeout,\\n        }\\n\\n        # openai_api_base is tenant-editable and the SDK sends the operator's stored API key to\\n        # whatever host it names. Apply the connector SSRF policy and route a custom endpoint\\n        # through DNS-pinned, redirect-free clients. No-op for the default OpenAI endpoint.\\n        parameters.update(openai_compatible_client_kwargs(self.openai_api_base, default_url=DEFAULT_OPENAI_API_BASE))\\n\\n        # TODO: Revisit if/once parameters are supported for reasoning models\\n        unsupported_params_for_reasoning_models = [\\\"temperature\\\", \\\"seed\\\"]\\n\\n        if self.model_name not in OPENAI_REASONING_MODEL_NAMES:\\n            parameters[\\\"temperature\\\"] = self.temperature if self.temperature is not None else 0.1\\n            parameters[\\\"seed\\\"] = self.seed\\n        else:\\n            params_str = \\\", \\\".join(unsupported_params_for_reasoning_models)\\n            logger.debug(f\\\"{self.model_name} is a reasoning model, {params_str} are not configurable. Ignoring.\\\")\\n\\n        parameters[\\\"stream_usage\\\"] = True\\n        output = ChatOpenAI(**parameters)\\n        if self.json_mode:\\n            output = output.bind(response_format={\\\"type\\\": \\\"json_object\\\"})\\n\\n        return output\\n\\n    def _get_exception_message(self, e: Exception):\\n        \\\"\\\"\\\"Get a message from an OpenAI exception.\\n\\n        Args:\\n            e (Exception): The exception to get the message from.\\n\\n        Returns:\\n            str: The message from the exception.\\n        \\\"\\\"\\\"\\n        try:\\n            from openai import BadRequestError, NotFoundError\\n        except ImportError:\\n            return None\\n        if isinstance(e, NotFoundError):\\n            body = getattr(e, \\\"body\\\", None) or {}\\n            if isinstance(body, dict) and body.get(\\\"code\\\") == \\\"model_not_found\\\":\\n                return (\\n                    f\\\"Model '{self.model_name}' is not available for this OpenAI account. \\\"\\n                    \\\"Your API tier may not have access yet \u2014 check \\\"\\n                    \\\"https://platform.openai.com/settings/organization/limits \\\"\\n                    \\\"or select a different model.\\\"\\n                )\\n        if isinstance(e, BadRequestError):\\n            message = e.body.get(\\\"message\\\")\\n            if message:\\n                return message\\n        return None\\n\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name in {\\\"base_url\\\", \\\"model_name\\\", \\\"api_key\\\"} and field_value in OPENAI_REASONING_MODEL_NAMES:\\n            build_config[\\\"temperature\\\"][\\\"show\\\"] = False\\n            build_config[\\\"seed\\\"][\\\"show\\\"] = False\\n            # Hide system_message for o1 models - currently unsupported\\n            if field_value.startswith(\\\"o1\\\") and \\\"system_message\\\" in build_config:\\n                build_config[\\\"system_message\\\"][\\\"show\\\"] = False\\n        if field_name in {\\\"base_url\\\", \\\"model_name\\\", \\\"api_key\\\"} and field_value in OPENAI_CHAT_MODEL_NAMES:\\n            build_config[\\\"temperature\\\"][\\\"show\\\"] = True\\n            build_config[\\\"seed\\\"][\\\"show\\\"] = True\\n            if \\\"system_message\\\" in build_config:\\n                build_config[\\\"system_message\\\"][\\\"show\\\"] = True\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/src/lfx_openai/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b707b721e45726972f0987d20e6dab01fc88d9d02437491a13cde33d56a7b39d\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-openai\\\",\\n  \\\"version\\\": \\\"0.1.4\\\",\\n  \\\"name\\\": \\\"OpenAI\\\",\\n  \\\"description\\\": \\\"OpenAI component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"openai\\\",\\n      \\\"path\\\": \\\"components/openai\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/tests/test_openai_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1d997f812b00e49d5c3a002d7b427766beb06bf7581aac29e14f90d0036a922b\",\"content\":\"import os\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx_openai.components.openai.openai_chat_model import OpenAIModelComponent\\n\\n_FAKE_OPENAI_API_KEY = \\\"test-api-key\\\"  # pragma: allowlist secret\\n\\n\\ndef get_openai_api_key() -> str:\\n    return os.getenv(\\\"OPENAI_API_KEY\\\", \\\"\\\")\\n\\n\\ndef has_openai_api_key() -> bool:\\n    return bool(get_openai_api_key())\\n\\n\\nclass TestOpenAIModelComponent:\\n    @pytest.fixture\\n    def component_class(self):\\n        return OpenAIModelComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"max_tokens\\\": 1000,\\n            \\\"model_kwargs\\\": {},\\n            \\\"json_mode\\\": False,\\n            \\\"model_name\\\": \\\"gpt-4.1-nano\\\",\\n            \\\"openai_api_base\\\": \\\"https://api.openai.com/v1\\\",\\n            \\\"api_key\\\": _FAKE_OPENAI_API_KEY,\\n            \\\"temperature\\\": 0.1,\\n            \\\"seed\\\": 1,\\n            \\\"max_retries\\\": 5,\\n            \\\"timeout\\\": 700,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        # Provide an empty list or the actual mapping if versioned files exist\\n        return []\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    async def test_build_model(self, mock_chat_openai, component_class, default_kwargs):\\n        mock_instance = MagicMock()\\n        mock_chat_openai.return_value = mock_instance\\n        component = component_class(**default_kwargs)\\n        model = component.build_model()\\n\\n        mock_chat_openai.assert_called_once_with(\\n            api_key=_FAKE_OPENAI_API_KEY,\\n            model_name=\\\"gpt-4.1-nano\\\",\\n            max_tokens=1000,\\n            model_kwargs={},\\n            base_url=\\\"https://api.openai.com/v1\\\",\\n            seed=1,\\n            max_retries=5,\\n            timeout=700,\\n            temperature=0.1,\\n            stream_usage=True,\\n        )\\n        assert model == mock_instance\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    async def test_build_model_reasoning_model(self, mock_chat_openai, component_class, default_kwargs):\\n        mock_instance = MagicMock()\\n        mock_chat_openai.return_value = mock_instance\\n        default_kwargs[\\\"model_name\\\"] = \\\"o1\\\"\\n        component = component_class(**default_kwargs)\\n        model = component.build_model()\\n\\n        # For reasoning models, temperature and seed should be excluded\\n        mock_chat_openai.assert_called_once_with(\\n            api_key=_FAKE_OPENAI_API_KEY,\\n            model_name=\\\"o1\\\",\\n            max_tokens=1000,\\n            model_kwargs={},\\n            base_url=\\\"https://api.openai.com/v1\\\",\\n            max_retries=5,\\n            timeout=700,\\n            stream_usage=True,\\n        )\\n        assert model == mock_instance\\n\\n        # Verify that temperature and seed are not in the parameters\\n        _args, kwargs = mock_chat_openai.call_args\\n        assert \\\"temperature\\\" not in kwargs\\n        assert \\\"seed\\\" not in kwargs\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    async def test_build_model_with_json_mode(self, mock_chat_openai, component_class, default_kwargs):\\n        mock_instance = MagicMock()\\n        mock_bound_instance = MagicMock()\\n        mock_instance.bind.return_value = mock_bound_instance\\n        mock_chat_openai.return_value = mock_instance\\n\\n        default_kwargs[\\\"json_mode\\\"] = True\\n        component = component_class(**default_kwargs)\\n        model = component.build_model()\\n\\n        mock_chat_openai.assert_called_once()\\n        mock_instance.bind.assert_called_once_with(response_format={\\\"type\\\": \\\"json_object\\\"})\\n        assert model == mock_bound_instance\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    async def test_build_model_no_api_key(self, mock_chat_openai, component_class, default_kwargs):\\n        mock_instance = MagicMock()\\n        mock_chat_openai.return_value = mock_instance\\n        default_kwargs[\\\"api_key\\\"] = None\\n        component = component_class(**default_kwargs)\\n        component.build_model()\\n\\n        # When api_key is None, it should be passed as None to ChatOpenAI\\n        _args, kwargs = mock_chat_openai.call_args\\n        assert kwargs[\\\"api_key\\\"] is None\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    async def test_build_model_max_tokens_zero(self, mock_chat_openai, component_class, default_kwargs):\\n        mock_instance = MagicMock()\\n        mock_chat_openai.return_value = mock_instance\\n        default_kwargs[\\\"max_tokens\\\"] = 0\\n        component = component_class(**default_kwargs)\\n        component.build_model()\\n\\n        # When max_tokens is 0, it should be passed as None to ChatOpenAI\\n        _args, kwargs = mock_chat_openai.call_args\\n        assert kwargs[\\\"max_tokens\\\"] is None\\n\\n    async def test_get_exception_message_bad_request_error(self, component_class, default_kwargs):\\n        component_class(**default_kwargs)\\n\\n        # Create a mock BadRequestError with a body attribute\\n        mock_error = MagicMock()\\n        mock_error.body = {\\\"message\\\": \\\"test error message\\\"}\\n\\n        # Test the method directly by patching the import\\n        with patch(\\\"openai.BadRequestError\\\", mock_error.__class__):\\n            # Manually call isinstance to avoid mocking it\\n            if hasattr(mock_error, \\\"body\\\"):\\n                message = mock_error.body.get(\\\"message\\\")\\n                assert message == \\\"test error message\\\"\\n\\n    async def test_get_exception_message_no_openai_import(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n\\n        # Test when openai module is not available\\n        with patch.dict(\\\"sys.modules\\\", {\\\"openai\\\": None}), patch(\\\"builtins.__import__\\\", side_effect=ImportError):\\n            message = component._get_exception_message(Exception(\\\"test\\\"))\\n            assert message is None\\n\\n    async def test_get_exception_message_other_exception(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n\\n        # Create a regular exception (not BadRequestError)\\n        regular_exception = ValueError(\\\"test error\\\")\\n\\n        # Create a simple mock for BadRequestError that the exception won't match\\n        class MockBadRequestError:\\n            pass\\n\\n        with patch(\\\"openai.BadRequestError\\\", MockBadRequestError):\\n            message = component._get_exception_message(regular_exception)\\n            assert message is None\\n\\n    async def test_should_return_helpful_message_when_openai_returns_model_not_found(\\n        self, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Bug: NotFoundError(model_not_found) falls through _get_exception_message and returns None.\\n\\n        Before fix: only BadRequestError was handled, so NotFoundError (HTTP 404) with\\n        code=model_not_found left the raw verbose OpenAI error to bubble up as\\n        ComponentBuildError without actionable context.\\n\\n        Expected: _get_exception_message recognizes openai.NotFoundError with\\n        code=model_not_found and returns a helpful message that references the model\\n        name and directs the user to check account/tier access.\\n        \\\"\\\"\\\"\\n        import httpx\\n        from openai import NotFoundError\\n\\n        default_kwargs[\\\"model_name\\\"] = \\\"gpt-nonexistent\\\"\\n        component = component_class(**default_kwargs)\\n\\n        request = httpx.Request(\\\"POST\\\", \\\"https://api.openai.com/v1/chat/completions\\\")\\n        response = httpx.Response(status_code=404, request=request)\\n        error = NotFoundError(\\n            message=\\\"The model `gpt-nonexistent` does not exist or you do not have access to it.\\\",\\n            response=response,\\n            body={\\n                \\\"code\\\": \\\"model_not_found\\\",\\n                \\\"message\\\": \\\"The model `gpt-nonexistent` does not exist or you do not have access to it.\\\",\\n                \\\"type\\\": \\\"invalid_request_error\\\",\\n                \\\"param\\\": None,\\n            },\\n        )\\n\\n        message = component._get_exception_message(error)\\n\\n        assert message is not None, \\\"Expected a helpful message for NotFoundError(model_not_found), got None\\\"\\n        assert \\\"gpt-nonexistent\\\" in message, f\\\"Expected model name in message, got: {message!r}\\\"\\n        assert any(keyword in message.lower() for keyword in (\\\"tier\\\", \\\"access\\\")), (\\n            f\\\"Expected message to mention tier/access, got: {message!r}\\\"\\n        )\\n\\n    async def test_should_not_expose_fictional_gpt53_ids_in_openai_model_name_options(self):\\n        \\\"\\\"\\\"Bug: fictional gpt-5.3 ids in the OpenAI dropdown cause 404 at runtime.\\n\\n        gpt-5.3 and gpt-5.3-instant were listed as selectable model options but do\\n        not exist as OpenAI API model IDs. Only gpt-5.3-chat-latest and gpt-5.3-codex\\n        exist in the OpenAI API for the 5.3 family. The bare gpt-5.3 id and\\n        gpt-5.3-instant (a ChatGPT product name, not an API model id) must not be\\n        exposed as selectable options.\\n        \\\"\\\"\\\"\\n        from lfx.base.models.openai_constants import (\\n            OPENAI_CHAT_MODEL_NAMES,\\n            OPENAI_REASONING_MODEL_NAMES,\\n        )\\n\\n        selectable_ids = set(OPENAI_CHAT_MODEL_NAMES) | set(OPENAI_REASONING_MODEL_NAMES)\\n        fictional_ids = {\\\"gpt-5.3\\\", \\\"gpt-5.3-instant\\\"}\\n        leaked = fictional_ids & selectable_ids\\n\\n        assert not leaked, (\\n            f\\\"Fictional OpenAI model IDs exposed in the OpenAI component dropdown: {sorted(leaked)}. \\\"\\n            f\\\"These IDs are not real OpenAI API models and trigger 404 model_not_found at runtime.\\\"\\n        )\\n\\n    async def test_update_build_config_reasoning_model(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        build_config = {\\n            \\\"temperature\\\": {\\\"show\\\": True},\\n            \\\"seed\\\": {\\\"show\\\": True},\\n        }\\n\\n        # Test with reasoning model\\n        updated_config = component.update_build_config(build_config, \\\"o1\\\", \\\"model_name\\\")\\n        assert updated_config[\\\"temperature\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"seed\\\"][\\\"show\\\"] is False\\n\\n        # Test with regular model\\n        updated_config = component.update_build_config(build_config, \\\"gpt-4\\\", \\\"model_name\\\")\\n        assert updated_config[\\\"temperature\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"seed\\\"][\\\"show\\\"] is True\\n\\n    @pytest.mark.skipif(not has_openai_api_key(), reason=\\\"OPENAI_API_KEY is not set or is empty\\\")\\n    def test_build_model_integration(self):\\n        component = OpenAIModelComponent()\\n        try:\\n            component.api_key = get_openai_api_key()\\n        except ValueError:\\n            component.api_key = None\\n        component.model_name = \\\"gpt-4.1-nano\\\"\\n        component.temperature = 0.2\\n        component.max_tokens = 1000\\n        component.seed = 42\\n        component.max_retries = 3\\n        component.timeout = 600\\n        component.openai_api_base = \\\"https://api.openai.com/v1\\\"\\n\\n        model = component.build_model()\\n        assert isinstance(model, ChatOpenAI)\\n        assert model.model_name == \\\"gpt-4.1-nano\\\"\\n        assert model.openai_api_base == \\\"https://api.openai.com/v1\\\"\\n\\n    @pytest.mark.skipif(not has_openai_api_key(), reason=\\\"OPENAI_API_KEY is not set or is empty\\\")\\n    def test_build_model_integration_reasoning(self):\\n        component = OpenAIModelComponent()\\n        component.api_key = get_openai_api_key()\\n        component.model_name = \\\"o1\\\"\\n        component.temperature = 0.2  # This should be ignored for reasoning models\\n        component.max_tokens = 1000\\n        component.seed = 42  # This should be ignored for reasoning models\\n        component.max_retries = 3\\n        component.timeout = 600\\n        component.openai_api_base = \\\"https://api.openai.com/v1\\\"\\n\\n        model = component.build_model()\\n        assert isinstance(model, ChatOpenAI)\\n        assert model.model_name == \\\"o1\\\"\\n        assert model.openai_api_base == \\\"https://api.openai.com/v1\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/openai/tests/test_openai_model_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a863e674aeb362cd986548e1c0b9ab4084a8e869d8fe7e12a03ea0fc87a7f3d9\",\"content\":\"\\\"\\\"\\\"SSRF regression coverage for the OpenAI Chat Model base-URL field.\\n\\n``openai_api_base`` is tenant-editable and is handed straight to the OpenAI SDK, which\\nthen issues a server-side request to that host carrying the operator's stored provider\\ncredential. These tests pin the connector SSRF policy onto that field.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx_openai.components.openai.openai import OpenAIEmbeddingsComponent\\nfrom lfx_openai.components.openai.openai_chat_model import OpenAIModelComponent\\n\\n_FAKE_OPENAI_API_KEY = \\\"sk-not-a-real-key\\\"  # pragma: allowlist secret\\n\\n\\ndef _component(base_url: str | None) -> OpenAIModelComponent:\\n    component = OpenAIModelComponent()\\n    component.openai_api_base = base_url\\n    component.api_key = _FAKE_OPENAI_API_KEY\\n    component.model_name = \\\"gpt-4.1-nano\\\"\\n    component.max_tokens = 10\\n    component.model_kwargs = {}\\n    component.json_mode = False\\n    component.temperature = 0.1\\n    component.seed = 1\\n    component.max_retries = 5\\n    component.timeout = 700\\n    return component\\n\\n\\nclass TestOpenAIModelBaseUrlSSRF:\\n    @pytest.mark.parametrize(\\n        \\\"blocked_url\\\",\\n        [\\n            \\\"http://169.254.169.254/latest/meta-data\\\",\\n            \\\"http://[fd00::1]/v1\\\",\\n            \\\"http://10.0.0.5:8000/v1\\\",\\n            \\\"http://192.168.1.10/v1\\\",\\n            \\\"http://172.16.0.9/v1\\\",\\n        ],\\n    )\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_block_internal_base_url(self, mock_chat_openai, blocked_url):\\n        \\\"\\\"\\\"Cloud-metadata and RFC1918 base URLs must never reach the SDK.\\\"\\\"\\\"\\n        component = _component(blocked_url)\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_model()\\n\\n        mock_chat_openai.assert_not_called()\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_block_non_http_base_url(self, mock_chat_openai):\\n        \\\"\\\"\\\"A non-http(s) scheme is not a validatable connector URL and must be refused.\\\"\\\"\\\"\\n        component = _component(\\\"file:///etc/passwd\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_model()\\n\\n        mock_chat_openai.assert_not_called()\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_pin_http_clients_for_custom_base_url(self, mock_chat_openai, monkeypatch):\\n        \\\"\\\"\\\"An allowed custom endpoint still builds, but through SSRF-protected clients.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", lambda _hostname: [\\\"93.184.216.34\\\"])\\n        component = _component(\\\"https://provider.example/v1\\\")\\n\\n        component.build_model()\\n\\n        kwargs = mock_chat_openai.call_args.kwargs\\n        assert kwargs[\\\"base_url\\\"] == \\\"https://provider.example/v1\\\"\\n        assert \\\"http_client\\\" in kwargs\\n        assert \\\"http_async_client\\\" in kwargs\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_block_loopback_by_default(self, mock_chat_openai):\\n        \\\"\\\"\\\"Provider credentials must not reach a server-local listener under defaults.\\\"\\\"\\\"\\n        component = _component(\\\"http://127.0.0.1:9999/v1\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_model()\\n\\n        mock_chat_openai.assert_not_called()\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_allow_explicitly_allowlisted_loopback(self, mock_chat_openai, monkeypatch):\\n        \\\"\\\"\\\"A single-tenant operator can explicitly trust a local provider host.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"127.0.0.1\\\")\\n        component = _component(\\\"http://127.0.0.1:1234/v1\\\")\\n\\n        component.build_model()\\n\\n        assert mock_chat_openai.call_args.kwargs[\\\"base_url\\\"] == \\\"http://127.0.0.1:1234/v1\\\"\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_leave_default_endpoint_untouched(self, mock_chat_openai):\\n        \\\"\\\"\\\"No custom base URL means no behavior change: default endpoint, no injected clients.\\\"\\\"\\\"\\n        component = _component(None)\\n\\n        component.build_model()\\n\\n        kwargs = mock_chat_openai.call_args.kwargs\\n        assert kwargs[\\\"base_url\\\"] == \\\"https://api.openai.com/v1\\\"\\n        assert \\\"http_client\\\" not in kwargs\\n        assert \\\"http_async_client\\\" not in kwargs\\n\\n    @patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\n    def test_should_respect_global_ssrf_kill_switch(self, mock_chat_openai, monkeypatch):\\n        \\\"\\\"\\\"Operators who disable SSRF protection keep the previous unvalidated behavior.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"false\\\")\\n        component = _component(\\\"http://10.0.0.5:8000/v1\\\")\\n\\n        component.build_model()\\n\\n        assert mock_chat_openai.call_args.kwargs[\\\"base_url\\\"] == \\\"http://10.0.0.5:8000/v1\\\"\\n\\n\\ndef _embeddings_component(base_url: str | None) -> OpenAIEmbeddingsComponent:\\n    component = OpenAIEmbeddingsComponent()\\n    component.openai_api_base = base_url\\n    component.openai_api_key = _FAKE_OPENAI_API_KEY\\n    component.model = \\\"text-embedding-3-small\\\"\\n    component.client = None\\n    component.dimensions = None\\n    component.deployment = None\\n    component.openai_api_version = None\\n    component.openai_api_type = None\\n    component.openai_proxy = None\\n    component.embedding_ctx_length = 1536\\n    component.openai_organization = None\\n    component.chunk_size = 1000\\n    component.max_retries = 3\\n    component.request_timeout = None\\n    component.tiktoken_enable = True\\n    component.tiktoken_model_name = None\\n    component.show_progress_bar = False\\n    component.model_kwargs = {}\\n    component.skip_empty = False\\n    component.default_headers = None\\n    component.default_query = None\\n    return component\\n\\n\\nclass TestOpenAIEmbeddingsBaseUrlSSRF:\\n    @pytest.mark.parametrize(\\n        \\\"blocked_url\\\",\\n        [\\n            \\\"http://169.254.169.254/latest/meta-data\\\",\\n            \\\"http://10.0.0.5:8000/v1\\\",\\n            \\\"http://192.168.1.10/v1\\\",\\n        ],\\n    )\\n    @patch(\\\"lfx_openai.components.openai.openai.OpenAIEmbeddings\\\")\\n    def test_should_block_internal_base_url(self, mock_embeddings, blocked_url):\\n        \\\"\\\"\\\"The embeddings component shares the field name and the credential-forwarding sink.\\\"\\\"\\\"\\n        component = _embeddings_component(blocked_url)\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_embeddings()\\n\\n        mock_embeddings.assert_not_called()\\n\\n    @patch(\\\"lfx_openai.components.openai.openai.OpenAIEmbeddings\\\")\\n    def test_should_leave_default_endpoint_untouched(self, mock_embeddings):\\n        \\\"\\\"\\\"No custom base URL means no injected clients.\\\"\\\"\\\"\\n        component = _embeddings_component(None)\\n\\n        component.build_embeddings()\\n\\n        kwargs = mock_embeddings.call_args.kwargs\\n        assert kwargs[\\\"base_url\\\"] is None\\n        assert \\\"http_client\\\" not in kwargs\\n\\n    @patch(\\\"lfx_openai.components.openai.openai.OpenAIEmbeddings\\\")\\n    def test_should_block_loopback_by_default(self, mock_embeddings):\\n        component = _embeddings_component(\\\"http://127.0.0.1:9999/v1\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_embeddings()\\n\\n        mock_embeddings.assert_not_called()\\n\\n\\n@patch(\\\"lfx_openai.components.openai.openai_chat_model.ChatOpenAI\\\")\\ndef test_chat_model_explicit_default_endpoint_is_still_a_no_op(mock_chat_openai):\\n    \\\"\\\"\\\"A saved configuration that spells out the default endpoint must not change behaviour.\\n\\n    The existing coverage only exercises an unset base URL. A stored flow that explicitly\\n    carries ``https://api.openai.com/v1`` must take the same no-op path, otherwise the\\n    default endpoint gets DNS-pinned, redirect-free clients it never had before.\\n    \\\"\\\"\\\"\\n    component = _component(\\\"https://api.openai.com/v1\\\")\\n\\n    component.build_model()\\n\\n    kwargs = mock_chat_openai.call_args.kwargs\\n    assert kwargs[\\\"base_url\\\"] == \\\"https://api.openai.com/v1\\\"\\n    assert \\\"http_client\\\" not in kwargs\\n    assert \\\"http_async_client\\\" not in kwargs\\n\\n\\n@patch(\\\"lfx_openai.components.openai.openai.OpenAIEmbeddings\\\")\\ndef test_embeddings_explicit_default_endpoint_is_still_a_no_op(mock_embeddings):\\n    \\\"\\\"\\\"Same for the embeddings component, which previously omitted ``default_url``.\\\"\\\"\\\"\\n    component = _embeddings_component(\\\"https://api.openai.com/v1\\\")\\n\\n    component.build_embeddings()\\n\\n    kwargs = mock_embeddings.call_args.kwargs\\n    assert \\\"http_client\\\" not in kwargs\\n    assert \\\"http_async_client\\\" not in kwargs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"57c592cb9ca9504c4845b031103d3fabc5c60434c6614f076efffa9a4517e773\",\"content\":\"# lfx-oracle\\n\\nOracle Database components (Doc Loader, Autonomous Database Loader,\\nEmbeddings, Vector Store) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-oracle\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `Oracle` group.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/oracle\\npip install -e .\\nlfx extension validate src/lfx_oracle\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.oracledb.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"725791c82720b8dcdfd7131f6c5c6fbf6045db53b59c24d59bfac7e1fd12f840\",\"content\":\"[project]\\nname = \\\"lfx-oracle\\\"\\nversion = \\\"0.1.4\\\"\\ndescription = \\\"Oracle Database components (Doc Loader, Autonomous Database Loader, Embeddings, Vector Store) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"oracle\\\", \\\"oracledb\\\", \\\"vector-store\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus the Oracle packages used\\n# by the bundled components.\\n#\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major; the floor is read from src/lfx/pyproject.toml at port time and\\n# re-synced on ``make patch`` via scripts/ci/sync_bundle_lfx_pin.py.\\n# Fine-grained BUNDLE_API compatibility is enforced via extension.json's\\n# lfx.compat list against BUNDLE_API_VERSION.\\n#\\n# * ``oracledb`` is the Oracle Database driver used for connections.\\n# * ``langchain-oracledb`` provides OracleVS, OracleEmbeddings, and the\\n#   Oracle document loaders the components wrap.  Pins match the former\\n#   ``langflow-base[oracledb]`` extra this bundle replaces.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"oracledb>=2.2.0,<4.0.0\\\",\\n    \\\"langchain-oracledb>=1.5.0,<2.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-oracle = \\\"lfx_oracle\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_oracle package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_oracle\\\"]\\ninclude = [\\\"src/lfx_oracle/extension.json\\\", \\\"src/lfx_oracle/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_oracle\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6058ea9ce7d7f8dc156ea5ffb146ce0ca7c7b5f686a4e7fe227dd1ae64acda58\",\"content\":\"\\\"\\\"\\\"lfx-oracle: Oracle Database bundle.\\n\\nDistribution unit ``lfx-oracle``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:oracle:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_oracle.components.oracle.oracledb_embeddings import OracleEmbeddingsComponent\\nfrom lfx_oracle.components.oracle.oracledb_loaders import (\\n    OracleAutonomousDatabaseLoaderComponent,\\n    OracleDocLoaderComponent,\\n)\\nfrom lfx_oracle.components.oracle.oraclevs import OracleVectorStoreComponent\\n\\n__all__ = [\\n    \\\"OracleAutonomousDatabaseLoaderComponent\\\",\\n    \\\"OracleDocLoaderComponent\\\",\\n    \\\"OracleEmbeddingsComponent\\\",\\n    \\\"OracleVectorStoreComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/components/oracle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8fa8cb34e6d107e99f4259de9853d637cd6c675afec63cf57b4a27be99cf5ab0\",\"content\":\"\\\"\\\"\\\"Component re-exports for the ``oracle`` bundle.\\n\\nSaved-flow migration entries that target the legacy in-tree\\n``lfx.components.oracledb.<Class>`` import paths resolve through this\\npackage, so the moved Component class(es) must be importable from here\\nby name.\\n\\\"\\\"\\\"\\n\\nfrom .oracledb_embeddings import OracleEmbeddingsComponent\\nfrom .oracledb_loaders import OracleAutonomousDatabaseLoaderComponent, OracleDocLoaderComponent\\nfrom .oraclevs import OracleVectorStoreComponent\\n\\n__all__ = [\\n    \\\"OracleAutonomousDatabaseLoaderComponent\\\",\\n    \\\"OracleDocLoaderComponent\\\",\\n    \\\"OracleEmbeddingsComponent\\\",\\n    \\\"OracleVectorStoreComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/components/oracle/connection.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eb3148153b2fb275145647cac0ccad959f5e61875c18dd9eb4fc59f7e794bbbe\",\"content\":\"from __future__ import annotations\\n\\nimport re\\nfrom typing import Any\\n\\n_SENSITIVE_CONNECTION_PARAM_KEYS = {\\n    \\\"access_token\\\",\\n    \\\"connection_string\\\",\\n    \\\"credential\\\",\\n    \\\"credentials\\\",\\n    \\\"dsn\\\",\\n    \\\"newpassword\\\",\\n    \\\"passwd\\\",\\n    \\\"password\\\",\\n    \\\"private_key\\\",\\n    \\\"proxy_user\\\",\\n    \\\"pwd\\\",\\n    \\\"secret\\\",\\n    \\\"tns\\\",\\n    \\\"token\\\",\\n    \\\"user\\\",\\n    \\\"username\\\",\\n    \\\"wallet_password\\\",\\n}\\n\\n\\ndef _is_sensitive_connection_param_key(key: str) -> bool:\\n    normalized_key = re.sub(r\\\"[^0-9a-zA-Z]+\\\", \\\"_\\\", key.strip().lower()).strip(\\\"_\\\")\\n    compact_key = normalized_key.replace(\\\"_\\\", \\\"\\\")\\n    return any(\\n        normalized_key == sensitive_key or compact_key == sensitive_key.replace(\\\"_\\\", \\\"\\\")\\n        for sensitive_key in _SENSITIVE_CONNECTION_PARAM_KEYS\\n    )\\n\\n\\ndef split_credentialized_dsn(dsn: str) -> tuple[str | None, str | None, str]:\\n    if \\\"@\\\" not in dsn:\\n        return None, None, dsn\\n\\n    credentials, dsn_without_credentials = dsn.rsplit(\\\"@\\\", 1)\\n    if \\\"/\\\" not in credentials:\\n        return None, None, dsn\\n\\n    user, password = credentials.split(\\\"/\\\", 1)\\n    return user or None, password or None, dsn_without_credentials\\n\\n\\ndef build_connection_params(\\n    connection_params: dict[str, Any] | None = None,\\n    *,\\n    user: str | None = None,\\n    password: str | None = None,\\n    dsn: str | None = None,\\n    wallet_password: str | None = None,\\n) -> dict[str, Any]:\\n    raw_params = {key: value for key, value in (connection_params or {}).items() if value not in (None, \\\"\\\")}\\n    sensitive_keys = sorted(key for key in raw_params if _is_sensitive_connection_param_key(key))\\n    if sensitive_keys:\\n        keys = \\\", \\\".join(sensitive_keys)\\n        msg = (\\n            f\\\"connection_params contains sensitive keys: {keys}. \\\"\\n            \\\"Use the dedicated secret fields for user, password, dsn, wallet_password, and proxy.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    if isinstance(dsn, str) and (not user or not password):\\n        parsed_user, parsed_password, parsed_dsn = split_credentialized_dsn(dsn)\\n        user = user or parsed_user\\n        password = password or parsed_password\\n        dsn = parsed_dsn\\n\\n    params = dict(raw_params)\\n\\n    if user:\\n        params[\\\"user\\\"] = user\\n    if password:\\n        params[\\\"password\\\"] = password\\n    if dsn:\\n        params[\\\"dsn\\\"] = dsn\\n    if wallet_password:\\n        params[\\\"wallet_password\\\"] = wallet_password\\n\\n    return params\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/components/oracle/oracledb_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4886353a338c61747fb17ed7f40e52e1de35eaace279c0f20b8ec6b4a771aa0b\",\"content\":\"from contextlib import suppress\\nfrom typing import Any\\n\\nimport oracledb\\nfrom langchain_oracledb import OracleEmbeddings\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import DictInput, Output, SecretStrInput\\n\\nfrom .connection import build_connection_params\\n\\n\\nclass OracleEmbeddingsComponent(LCModelComponent):\\n    display_name = \\\"Oracle Embeddings\\\"\\n    description = \\\"Generate embeddings using Oracle AI Vector Search.\\\"\\n    icon = \\\"Oracle\\\"\\n    name = \\\"OracleEmbeddings\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"user\\\", display_name=\\\"User\\\", required=False),\\n        SecretStrInput(name=\\\"password\\\", display_name=\\\"Password\\\", required=False),\\n        SecretStrInput(name=\\\"dsn\\\", display_name=\\\"DSN\\\", required=True),\\n        SecretStrInput(name=\\\"wallet_password\\\", display_name=\\\"Wallet Password\\\", required=False, advanced=True),\\n        DictInput(\\n            name=\\\"connection_params\\\",\\n            display_name=\\\"Additional Connection Parameters\\\",\\n            info=\\\"Non-secret arguments passed to python-oracledb connect(), such as config_dir and wallet_location.\\\",\\n            list=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"embedding_params\\\",\\n            display_name=\\\"Embedding Parameters\\\",\\n            list=True,\\n            info=(\\n                \\\"https://docs.oracle.com/en/database/oracle/oracle-database/23/vecse/utl_to_embedding-and-utl_to_embeddings-dbms_vector.html\\\"\\n            ),\\n        ),\\n        SecretStrInput(name=\\\"proxy\\\", display_name=\\\"Proxy\\\", required=False, advanced=True),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def build_template_config(self) -> dict[str, Any]:\\n        return self.get_template_config(self)\\n\\n    def build_embeddings(self) -> Embeddings:\\n        connection_params = build_connection_params(\\n            self.connection_params,\\n            user=self.user,\\n            password=self.password,\\n            dsn=self.dsn,\\n            wallet_password=self.wallet_password,\\n        )\\n        connection = oracledb.connect(**connection_params)\\n\\n        try:\\n            return OracleEmbeddings(\\n                conn=connection,\\n                params=self.embedding_params,\\n                proxy=self.proxy or None,\\n            )\\n        except Exception as e:\\n            with suppress(Exception):\\n                connection.close()\\n            msg = \\\"Unable to create OracleEmbeddings.\\\"\\n            raise ValueError(msg) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/components/oracle/oracledb_loaders.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"19108fbae3b56fd331a05e95fb57ca02ec5b068911c5b059f61334b22f03d87c\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import Any\\n\\nimport oracledb\\nfrom langchain_oracledb.document_loaders import OracleAutonomousDatabaseLoader, OracleDocLoader\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DictInput, MultilineInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\nfrom .connection import build_connection_params, split_credentialized_dsn\\n\\n\\nclass OracleDocLoaderComponent(Component):\\n    display_name = \\\"Oracle Doc Loader\\\"\\n    description = \\\"Read documents from Oracle Database using OracleDocLoader.\\\"\\n    documentation = \\\"https://docs.langchain.com/oss/python/integrations/document_loaders/oracleai\\\"\\n    trace_type = \\\"tool\\\"\\n    icon = \\\"Oracle\\\"\\n    name = \\\"OracleDocLoader\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"user\\\", display_name=\\\"User\\\", required=False),\\n        SecretStrInput(name=\\\"password\\\", display_name=\\\"Password\\\", required=False),\\n        SecretStrInput(name=\\\"dsn\\\", display_name=\\\"DSN\\\", required=True),\\n        SecretStrInput(name=\\\"wallet_password\\\", display_name=\\\"Wallet Password\\\", required=False, advanced=True),\\n        DictInput(\\n            name=\\\"connection_params\\\",\\n            display_name=\\\"Additional Connection Parameters\\\",\\n            info=\\\"Non-secret arguments passed to python-oracledb connect(), such as config_dir and wallet_location.\\\",\\n            required=False,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"params\\\",\\n            display_name=\\\"Loader Parameters\\\",\\n            info=\\\"Arguments passed to langchain-oracledb OracleDocLoader.\\\",\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"data\\\", display_name=\\\"JSON\\\", method=\\\"load_documents\\\"),\\n    ]\\n\\n    def build_template_config(self) -> dict[str, Any]:\\n        return self.get_template_config(self)\\n\\n    def load_documents(self) -> list[Data]:\\n        connection_params = build_connection_params(\\n            self.connection_params,\\n            user=self.user,\\n            password=self.password,\\n            dsn=self.dsn,\\n            wallet_password=self.wallet_password,\\n        )\\n        with oracledb.connect(**connection_params) as connection:\\n            loader = OracleDocLoader(connection, self.params)\\n            data = [Data.from_document(doc) for doc in loader.load()]\\n\\n        self.status = data\\n        return data\\n\\n\\nclass OracleAutonomousDatabaseLoaderComponent(Component):\\n    display_name = \\\"Oracle Autonomous Database Loader\\\"\\n    description = \\\"Load rows from Oracle Autonomous Database as documents.\\\"\\n    documentation = (\\n        \\\"https://github.com/oracle/langchain-oracle/blob/main/libs/oracledb/\\\"\\n        \\\"langchain_oracledb/document_loaders/oracleadb_loader.py\\\"\\n    )\\n    trace_type = \\\"tool\\\"\\n    icon = \\\"Oracle\\\"\\n    name = \\\"OracleAutonomousDatabaseLoader\\\"\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"query\\\",\\n            display_name=\\\"SQL Query\\\",\\n            required=True,\\n            info=\\\"SQL query to execute. Each row becomes a document.\\\",\\n        ),\\n        SecretStrInput(name=\\\"user\\\", display_name=\\\"User\\\", required=False),\\n        SecretStrInput(name=\\\"password\\\", display_name=\\\"Password\\\", required=False),\\n        SecretStrInput(name=\\\"dsn\\\", display_name=\\\"DSN\\\", required=True),\\n        SecretStrInput(name=\\\"wallet_password\\\", display_name=\\\"Wallet Password\\\", required=False, advanced=True),\\n        DictInput(\\n            name=\\\"connection_params\\\",\\n            display_name=\\\"Additional Connection Parameters\\\",\\n            info=\\\"Non-secret Oracle options such as schema, config_dir, and wallet_location.\\\",\\n            required=False,\\n            advanced=True,\\n        ),\\n        MultilineInput(\\n            name=\\\"metadata\\\",\\n            display_name=\\\"Metadata Columns\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"Comma-separated list of result columns to copy into document metadata.\\\",\\n        ),\\n        DictInput(\\n            name=\\\"parameter\\\",\\n            display_name=\\\"Bind Parameters\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"Bind variables for the SQL query.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"data\\\", display_name=\\\"JSON\\\", method=\\\"load_documents\\\"),\\n    ]\\n\\n    def build_template_config(self) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build template config from this class to avoid cross-class metadata bleed.\\\"\\\"\\\"\\n        return self.get_template_config(self)\\n\\n    def _parse_metadata(self) -> list[str] | None:\\n        metadata = getattr(self, \\\"metadata\\\", None)\\n        if metadata is None:\\n            return None\\n        if isinstance(metadata, str):\\n            values = [column.strip() for column in metadata.split(\\\",\\\") if column.strip()]\\n            return values or None\\n        if isinstance(metadata, list):\\n            return metadata or None\\n        return None\\n\\n    def _parse_connection_params(self) -> dict[str, Any]:\\n        connection_params = build_connection_params(\\n            self.connection_params,\\n            user=self.user,\\n            password=self.password,\\n            dsn=self.dsn,\\n            wallet_password=self.wallet_password,\\n        )\\n        dsn = connection_params.get(\\\"dsn\\\") or connection_params.get(\\\"connection_string\\\") or connection_params.get(\\\"tns\\\")\\n\\n        user = connection_params.get(\\\"user\\\") or connection_params.get(\\\"username\\\")\\n        password = connection_params.get(\\\"password\\\")\\n\\n        if isinstance(dsn, str) and (not user or not password):\\n            parsed_user, parsed_password, parsed_dsn = split_credentialized_dsn(dsn)\\n            user = user or parsed_user\\n            password = password or parsed_password\\n            dsn = parsed_dsn\\n\\n        if not user or not password:\\n            msg = (\\n                \\\"Connection settings must include user and password, either in the dedicated fields or inside the DSN.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        return {\\n            \\\"user\\\": user,\\n            \\\"password\\\": password,\\n            \\\"dsn\\\": dsn,\\n            \\\"schema\\\": connection_params.get(\\\"schema\\\"),\\n            \\\"config_dir\\\": connection_params.get(\\\"config_dir\\\"),\\n            \\\"wallet_location\\\": connection_params.get(\\\"wallet_location\\\"),\\n            \\\"wallet_password\\\": connection_params.get(\\\"wallet_password\\\"),\\n        }\\n\\n    def _parse_parameter(self) -> Any:\\n        parameter = getattr(self, \\\"parameter\\\", None)\\n        return parameter or None\\n\\n    def load_documents(self) -> list[Data]:\\n        loader = OracleAutonomousDatabaseLoader(\\n            query=self.query,\\n            metadata=self._parse_metadata(),\\n            parameter=self._parse_parameter(),\\n            **self._parse_connection_params(),\\n        )\\n\\n        data = [Data.from_document(doc) for doc in loader.load()]\\n        self.status = data\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/components/oracle/oraclevs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c361dc95d78bd2c5f794230fc2ac6c9cb201d99eb7aa41c96103fb7728627b9c\",\"content\":\"import hashlib\\nimport json\\nfrom contextlib import suppress\\nfrom decimal import Decimal\\nfrom importlib.metadata import version\\nfrom typing import Any\\n\\nimport oracledb\\nfrom langchain_oracledb.vectorstores import DistanceStrategy, OracleVS\\nfrom langchain_oracledb.vectorstores.oraclevs import create_index\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.io import BoolInput, DictInput, DropdownInput, HandleInput, IntInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom pydantic import BaseModel\\n\\nfrom .connection import build_connection_params\\n\\n\\ndef serialize(obj: Any) -> dict | list:\\n    if isinstance(obj, BaseModel):\\n        return obj.model_dump(mode=\\\"json\\\")\\n    if isinstance(obj, dict):\\n        return {k: serialize(v) for k, v in obj.items()}\\n    if isinstance(obj, list):\\n        return [serialize(item) for item in obj]\\n    if isinstance(obj, tuple):\\n        return [serialize(item) for item in obj]\\n    return obj\\n\\n\\ndef normalize_search_result(obj: Any) -> Any:\\n    if isinstance(obj, Decimal):\\n        return float(obj)\\n    if isinstance(obj, dict):\\n        return {key: normalize_search_result(value) for key, value in obj.items()}\\n    if isinstance(obj, list):\\n        return [normalize_search_result(item) for item in obj]\\n    if isinstance(obj, tuple):\\n        return [normalize_search_result(item) for item in obj]\\n    return obj\\n\\n\\nclass OracleVectorStoreComponent(LCVectorStoreComponent):\\n    display_name = \\\"Oracle Vector Store\\\"\\n    description = \\\"Oracle vector store with search capabilities\\\"\\n    name = \\\"OracleVS\\\"\\n    icon = \\\"Oracle\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"user\\\", display_name=\\\"User\\\", required=False),\\n        SecretStrInput(name=\\\"password\\\", display_name=\\\"Password\\\", required=False),\\n        SecretStrInput(name=\\\"dsn\\\", display_name=\\\"DSN\\\", required=True),\\n        SecretStrInput(name=\\\"wallet_password\\\", display_name=\\\"Wallet Password\\\", required=False, advanced=True),\\n        DictInput(\\n            name=\\\"connection_params\\\",\\n            display_name=\\\"Additional Connection Parameters\\\",\\n            info=\\\"Non-secret arguments passed to python-oracledb connect(), such as config_dir and wallet_location.\\\",\\n            list=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        StrInput(name=\\\"table_name\\\", display_name=\\\"Table Name\\\", required=True),\\n        *LCVectorStoreComponent.inputs,\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"], required=True),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            value=4,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\\"Similarity\\\", \\\"MMR (Max Marginal Relevance)\\\"],\\n            value=\\\"Similarity\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"distance_strategy\\\",\\n            display_name=\\\"Distance Strategy\\\",\\n            options=[\\\"EUCLIDEAN\\\", \\\"DOT\\\", \\\"COSINE\\\"],\\n            value=\\\"COSINE\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"create_index\\\",\\n            display_name=\\\"Create Vector Index\\\",\\n            info=(\\n                \\\"Boolean flag to determine whether to create a vector index. \\\"\\n                \\\"Check `Controls` to use advanced parameters.\\\"\\n            ),\\n            value=True,\\n        ),\\n        DictInput(\\n            name=\\\"index_params\\\",\\n            display_name=\\\"Vector Index Parameters\\\",\\n            list=True,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"mutate_on_duplicate\\\",\\n            display_name=\\\"Mutate on Duplicate Inserts\\\",\\n            info=\\\"Whether to update existing rows when duplicate inserts are encountered.\\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    # Mirrors LCVectorStoreComponent.outputs verbatim: the extension\\n    # validator statically scans this file and cannot see inherited\\n    # outputs, so the declaration must be repeated here.\\n    outputs = [\\n        Output(\\n            display_name=\\\"Search Results\\\",\\n            name=\\\"search_results\\\",\\n            method=\\\"search_documents\\\",\\n            info=(\\n                \\\"Performs semantic similarity search in the vector store to find relevant documents/files. \\\"\\n                \\\"Input: A natural language search query (str). \\\"\\n                \\\"Returns: A list of Data objects (dicts). Each result has structure: {'data': {'text': '...', ...}}. \\\"\\n                \\\"The 'text' field always contains the matched document content. \\\"\\n                \\\"Other metadata fields depend on what was indexed \\\"\\n                \\\"(may include: 'file_path', 'source', 'page', etc.). \\\"\\n                \\\"IMPORTANT: To extract metadata like file_path, use: \\\"\\n                \\\"result['data'].get('file_path') or result.data.get('file_path'). \\\"\\n                \\\"Check what fields are available by inspecting result['data'].keys() or the first search result.\\\"\\n            ),\\n            tool_mode=True,\\n        ),\\n        Output(\\n            display_name=\\\"Table\\\",\\n            name=\\\"dataframe\\\",\\n            method=\\\"as_dataframe\\\",\\n        ),\\n    ]\\n\\n    def build_template_config(self) -> dict[str, Any]:\\n        return self.get_template_config(self)\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> OracleVS:\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            inp = _input\\n            if isinstance(_input, Data):\\n                inp = _input.to_lc_document()\\n\\n            if hasattr(inp, \\\"metadata\\\"):\\n                inp.metadata = serialize(inp.metadata)\\n\\n            documents.append(inp)\\n\\n        opened_connection = False\\n        if (not hasattr(self, \\\"connection\\\")) or (not self.connection):\\n            connection_params = build_connection_params(\\n                self.connection_params,\\n                user=self.user,\\n                password=self.password,\\n                dsn=self.dsn,\\n                wallet_password=self.wallet_password,\\n            )\\n            self.connection = oracledb.connect(**connection_params)\\n            opened_connection = True\\n\\n        distance_strategy2function = {\\n            \\\"EUCLIDEAN\\\": DistanceStrategy.EUCLIDEAN_DISTANCE,\\n            \\\"DOT\\\": DistanceStrategy.DOT_PRODUCT,\\n            \\\"COSINE\\\": DistanceStrategy.COSINE,\\n        }\\n        distance_strategy = distance_strategy2function[self.distance_strategy]\\n\\n        params = {\\n            \\\"client\\\": self.connection,\\n            \\\"table_name\\\": self.table_name,\\n            \\\"distance_strategy\\\": distance_strategy,\\n        }\\n\\n        if not version(\\\"langchain_oracledb\\\").startswith(\\\"1.0\\\"):\\n            params[\\\"mutate_on_duplicate\\\"] = self.mutate_on_duplicate\\n\\n        try:\\n            if documents:\\n                vs = OracleVS.from_documents(embedding=self.embedding, documents=documents, **params)\\n            else:\\n                vs = OracleVS(embedding_function=self.embedding, **params)\\n\\n            if self.create_index:\\n                index_params = (self.index_params or {}).copy()\\n\\n                if \\\"idx_name\\\" not in index_params:\\n                    params_str = json.dumps(index_params, sort_keys=True)\\n                    distance_strategy = self.distance_strategy\\n                    params_str = params_str + distance_strategy\\n                    index_name = params[\\\"table_name\\\"] + \\\"_idx_\\\" + hashlib.sha256(params_str.encode()).hexdigest()[:16]\\n                    index_params[\\\"idx_name\\\"] = index_name\\n\\n                if \\\"idx_type\\\" not in index_params:\\n                    index_params[\\\"idx_type\\\"] = \\\"HNSW\\\"\\n\\n                if \\\"\\\" in index_params:\\n                    del index_params[\\\"\\\"]\\n                create_index(self.connection, vs, index_params)\\n        except Exception:\\n            if opened_connection:\\n                with suppress(Exception):\\n                    self.connection.close()\\n                self.connection = None\\n            raise\\n\\n        return vs\\n\\n    def _map_search_type(self) -> str:\\n        if self.search_type == \\\"MMR (Max Marginal Relevance)\\\":\\n            return \\\"mmr\\\"\\n        return \\\"similarity\\\"\\n\\n    def _build_search_args(self) -> dict[str, Any]:\\n        return {\\\"k\\\": self.number_of_results}\\n\\n    def search_documents(self) -> list[Data]:\\n        raw_search_query = getattr(self, \\\"search_query\\\", None)\\n        search_query = str(raw_search_query).strip() if raw_search_query is not None else \\\"\\\"\\n\\n        if not search_query:\\n            self.status = []\\n            return []\\n\\n        vector_store = self.build_vector_store()\\n        docs = vector_store.search(\\n            query=search_query,\\n            search_type=self._map_search_type(),\\n            **self._build_search_args(),\\n        )\\n\\n        data = docs_to_data(docs)\\n        for item in data:\\n            item.data = normalize_search_result(item.data)\\n        self.status = data\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/src/lfx_oracle/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b86010f60f368abcc92b2c2ac5b485fddaa6651645c5411ecab0256de422a35e\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-oracle\\\",\\n  \\\"version\\\": \\\"0.1.4\\\",\\n  \\\"name\\\": \\\"Oracle\\\",\\n  \\\"description\\\": \\\"Oracle component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"oracle\\\",\\n      \\\"path\\\": \\\"components/oracle\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/tests/oracle_test_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"62e9dacd1fcff2dc0825264d66f063ab20cda0c21273b2462159a230ef51b209\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nimport os\\nfrom typing import Any\\nfrom uuid import uuid4\\n\\n\\ndef get_oracle_connection_params() -> dict[str, Any] | None:\\n    raw_params = os.getenv(\\\"ORACLE_CONNECTION_PARAMS\\\")\\n    if raw_params:\\n        return json.loads(raw_params)\\n\\n    user = os.getenv(\\\"ORACLE_USER\\\") or os.getenv(\\\"VECDB_USER\\\")\\n    password = os.getenv(\\\"ORACLE_PASSWORD\\\") or os.getenv(\\\"VECDB_PASS\\\")\\n    dsn = os.getenv(\\\"ORACLE_DSN\\\") or os.getenv(\\\"VECDB_HOST\\\")\\n    wallet_password = os.getenv(\\\"ORACLE_WALLET_PASSWORD\\\")\\n\\n    if dsn:\\n        connection_params = {\\n            \\\"user\\\": user,\\n            \\\"password\\\": password,\\n            \\\"dsn\\\": dsn,\\n            \\\"wallet_password\\\": wallet_password,\\n        }\\n        return {key: value for key, value in connection_params.items() if value}\\n\\n    return None\\n\\n\\ndef get_oracle_connection_inputs(connection_params: dict[str, Any] | None = None) -> dict[str, Any]:\\n    connection_params = dict(connection_params or get_oracle_connection_params() or {})\\n    inputs: dict[str, Any] = {\\n        \\\"connection_params\\\": {\\n            key: value\\n            for key, value in connection_params.items()\\n            if key not in {\\\"user\\\", \\\"username\\\", \\\"password\\\", \\\"dsn\\\", \\\"tns\\\", \\\"connection_string\\\", \\\"wallet_password\\\"}\\n        }\\n    }\\n\\n    user = connection_params.get(\\\"user\\\") or connection_params.get(\\\"username\\\")\\n    if user:\\n        inputs[\\\"user\\\"] = user\\n\\n    password = connection_params.get(\\\"password\\\")\\n    if password:\\n        inputs[\\\"password\\\"] = password\\n\\n    dsn = connection_params.get(\\\"dsn\\\") or connection_params.get(\\\"connection_string\\\") or connection_params.get(\\\"tns\\\")\\n    if dsn:\\n        inputs[\\\"dsn\\\"] = dsn\\n\\n    wallet_password = connection_params.get(\\\"wallet_password\\\")\\n    if wallet_password:\\n        inputs[\\\"wallet_password\\\"] = wallet_password\\n\\n    return inputs\\n\\n\\ndef has_oracle_connection_params() -> bool:\\n    return get_oracle_connection_params() is not None\\n\\n\\ndef get_oracle_embedding_params() -> dict[str, Any]:\\n    raw_params = os.getenv(\\\"ORACLE_EMBEDDING_PARAMS\\\")\\n    if raw_params:\\n        return json.loads(raw_params)\\n    return {\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"}\\n\\n\\ndef get_oracle_test_connection_inputs(*, include_wallet_password: bool = False) -> dict[str, str]:\\n    inputs = {\\n        \\\"user\\\": os.getenv(\\\"ORACLE_TEST_USER\\\") or os.getenv(\\\"VECDB_USER\\\") or uuid4().hex,\\n        \\\"password\\\": os.getenv(\\\"ORACLE_TEST_PASSWORD\\\") or os.getenv(\\\"VECDB_PASS\\\") or uuid4().hex,\\n        \\\"dsn\\\": os.getenv(\\\"ORACLE_TEST_DSN\\\") or os.getenv(\\\"VECDB_HOST\\\") or uuid4().hex,\\n    }\\n    if include_wallet_password:\\n        inputs[\\\"wallet_password\\\"] = os.getenv(\\\"ORACLE_TEST_WALLET_PASSWORD\\\") or uuid4().hex\\n    return inputs\\n\\n\\ndef get_oracle_owner(connection_params: dict[str, Any]) -> str:\\n    owner = os.getenv(\\\"ORACLE_OWNER\\\") or connection_params.get(\\\"user\\\") or connection_params.get(\\\"username\\\")\\n    if owner:\\n        return owner\\n\\n    dsn = connection_params.get(\\\"dsn\\\")\\n    if isinstance(dsn, str) and \\\"/\\\" in dsn and \\\"@\\\" in dsn:\\n        return dsn.split(\\\"/\\\", 1)[0]\\n\\n    msg = \\\"ORACLE_OWNER, ORACLE_USER, or VECDB_USER is required when DSN does not include a user.\\\"\\n    raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/tests/test_oracle_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4a05a32f43c0c096c6ec69c2850954aff5b5eb0f85c28155a106c6636f004f79\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_oracledb import OracleEmbeddings\\nfrom lfx_oracle.components.oracle.oracledb_embeddings import OracleEmbeddingsComponent\\nfrom oracle_test_utils import (\\n    get_oracle_connection_inputs,\\n    get_oracle_connection_params,\\n    get_oracle_embedding_params,\\n    get_oracle_test_connection_inputs,\\n)\\n\\n\\ndef test_oracle_embeddings_connection_secrets_are_password_inputs():\\n    inputs = {input_.name: input_ for input_ in OracleEmbeddingsComponent.inputs}\\n\\n    for name in (\\\"user\\\", \\\"password\\\", \\\"dsn\\\", \\\"wallet_password\\\", \\\"proxy\\\"):\\n        assert inputs[name].password is True\\n\\n    assert inputs[\\\"connection_params\\\"].advanced is True\\n    assert \\\"Non-secret\\\" in inputs[\\\"connection_params\\\"].info\\n\\n\\ndef test_build_embeddings_returns_oracle_embeddings_instance():\\n    connection_params = get_oracle_connection_params()\\n    if connection_params:\\n        component = OracleEmbeddingsComponent().set(\\n            **get_oracle_connection_inputs(connection_params),\\n            embedding_params=get_oracle_embedding_params(),\\n        )\\n\\n        result = component.build_embeddings()\\n\\n        assert isinstance(result, OracleEmbeddings)\\n        return\\n\\n    with (\\n        patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.OracleEmbeddings\\\") as mock_oracle_embeddings,\\n        patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.oracledb.connect\\\") as mock_connect,\\n    ):\\n        connection = MagicMock()\\n        embeddings = MagicMock()\\n        mock_connect.return_value = connection\\n        mock_oracle_embeddings.return_value = embeddings\\n        test_connection_inputs = get_oracle_test_connection_inputs()\\n\\n        component = OracleEmbeddingsComponent().set(\\n            dsn=test_connection_inputs[\\\"dsn\\\"],\\n            embedding_params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n            proxy=\\\"http://proxy.internal\\\",\\n        )\\n\\n        result = component.build_embeddings()\\n\\n    assert result is embeddings\\n    mock_connect.assert_called_once_with(dsn=test_connection_inputs[\\\"dsn\\\"])\\n    mock_oracle_embeddings.assert_called_once_with(\\n        conn=connection,\\n        params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n        proxy=\\\"http://proxy.internal\\\",\\n    )\\n\\n\\ndef test_build_embeddings_accepts_credentialized_dsn_without_user_password():\\n    connection_params = get_oracle_connection_params()\\n    if connection_params:\\n        user = connection_params.get(\\\"user\\\") or connection_params.get(\\\"username\\\")\\n        password = connection_params.get(\\\"password\\\")\\n        dsn = connection_params.get(\\\"dsn\\\") or connection_params.get(\\\"connection_string\\\") or connection_params.get(\\\"tns\\\")\\n\\n        if user and password and dsn:\\n            credentialized_dsn = f\\\"{user}/{password}@{dsn}\\\"\\n        elif isinstance(dsn, str) and \\\"/\\\" in dsn and \\\"@\\\" in dsn:\\n            credentialized_dsn = dsn\\n        else:\\n            pytest.skip(\\\"Credentialized DSN test requires split credentials or an already credentialized DSN.\\\")\\n\\n        component = OracleEmbeddingsComponent().set(\\n            dsn=credentialized_dsn,\\n            embedding_params=get_oracle_embedding_params(),\\n        )\\n\\n        result = component.build_embeddings()\\n\\n        assert isinstance(result, OracleEmbeddings)\\n        return\\n\\n    with (\\n        patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.OracleEmbeddings\\\") as mock_oracle_embeddings,\\n        patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.oracledb.connect\\\") as mock_connect,\\n    ):\\n        connection = MagicMock()\\n        embeddings = MagicMock()\\n        mock_connect.return_value = connection\\n        mock_oracle_embeddings.return_value = embeddings\\n        test_connection_inputs = get_oracle_test_connection_inputs()\\n\\n        component = OracleEmbeddingsComponent().set(\\n            dsn=f\\\"{test_connection_inputs['user']}/{test_connection_inputs['password']}@{test_connection_inputs['dsn']}\\\",\\n            embedding_params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n        )\\n\\n        result = component.build_embeddings()\\n\\n    assert result is embeddings\\n    mock_connect.assert_called_once_with(**test_connection_inputs)\\n\\n\\n@patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.OracleEmbeddings\\\")\\n@patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.oracledb.connect\\\")\\ndef test_build_embeddings_passes_none_proxy_when_unset(mock_connect, mock_oracle_embeddings):\\n    connection = MagicMock()\\n    embeddings = MagicMock()\\n    mock_connect.return_value = connection\\n    mock_oracle_embeddings.return_value = embeddings\\n    test_connection_inputs = get_oracle_test_connection_inputs()\\n\\n    component = OracleEmbeddingsComponent().set(\\n        **test_connection_inputs,\\n        embedding_params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n    )\\n\\n    result = component.build_embeddings()\\n\\n    assert result is embeddings\\n    mock_connect.assert_called_once_with(**test_connection_inputs)\\n    mock_oracle_embeddings.assert_called_once_with(\\n        conn=connection,\\n        params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n        proxy=None,\\n    )\\n\\n\\n@patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.OracleEmbeddings\\\")\\n@patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.oracledb.connect\\\")\\ndef test_build_embeddings_wraps_oracle_embeddings_errors(mock_connect, mock_oracle_embeddings):\\n    connection = MagicMock()\\n    mock_connect.return_value = connection\\n    mock_oracle_embeddings.side_effect = RuntimeError(\\\"boom\\\")\\n    test_connection_inputs = get_oracle_test_connection_inputs()\\n\\n    component = OracleEmbeddingsComponent().set(\\n        dsn=test_connection_inputs[\\\"dsn\\\"],\\n        embedding_params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n    )\\n\\n    with pytest.raises(ValueError, match=\\\"Unable to create OracleEmbeddings\\\\\\\\.\\\") as exc_info:\\n        component.build_embeddings()\\n\\n    assert isinstance(exc_info.value.__cause__, RuntimeError)\\n    assert str(exc_info.value.__cause__) == \\\"boom\\\"\\n    connection.close.assert_called_once_with()\\n\\n\\n@patch(\\\"lfx_oracle.components.oracle.oracledb_embeddings.oracledb.connect\\\")\\ndef test_build_embeddings_propagates_connection_errors(mock_connect):\\n    mock_connect.side_effect = RuntimeError(\\\"connect boom\\\")\\n    test_connection_inputs = get_oracle_test_connection_inputs()\\n\\n    component = OracleEmbeddingsComponent().set(\\n        dsn=test_connection_inputs[\\\"dsn\\\"],\\n        embedding_params={\\\"provider\\\": \\\"database\\\", \\\"model\\\": \\\"ALL_MINILM_L12_V2\\\"},\\n    )\\n\\n    with pytest.raises(RuntimeError, match=\\\"connect boom\\\"):\\n        component.build_embeddings()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/tests/test_oracle_loaders.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"be4088abd5eb1a2f801fbd2453f323b0bca001ca7dd053389cdbc44bff2e56cd\",\"content\":\"from __future__ import annotations\\n\\nimport re\\nfrom contextlib import suppress\\nfrom unittest.mock import MagicMock, patch\\n\\nimport oracledb\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom lfx.schema.data import Data\\nfrom lfx_oracle.components.oracle.oracledb_loaders import (\\n    OracleAutonomousDatabaseLoaderComponent,\\n    OracleDocLoaderComponent,\\n)\\nfrom oracle_test_utils import (\\n    get_oracle_connection_inputs,\\n    get_oracle_connection_params,\\n    get_oracle_owner,\\n    get_oracle_test_connection_inputs,\\n)\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef connection_params() -> dict[str, str] | None:\\n    return get_oracle_connection_params()\\n\\n\\n@pytest.fixture\\ndef dsn(connection_params: dict[str, str] | None) -> str | None:\\n    if not connection_params:\\n        return None\\n    return connection_params.get(\\\"dsn\\\")\\n\\n\\n@pytest.fixture\\ndef connection(connection_params: dict[str, str] | None):\\n    if not connection_params:\\n        yield None\\n        return\\n\\n    conn = oracledb.connect(**connection_params)\\n    try:\\n        yield conn\\n    finally:\\n        with suppress(Exception):\\n            conn.close()\\n\\n\\ndef _safe_identifier(name: str, max_len: int = 30) -> str:\\n    base = re.sub(r\\\"[^A-Za-z0-9_]\\\", \\\"_\\\", name).upper()\\n    # Ensure first char is a letter\\n    if not base or not base[0].isalpha():\\n        base = \\\"T_\\\" + base\\n    return base[:max_len]\\n\\n\\ndef _drop_table_if_exists(cur: oracledb.Cursor, table_name: str) -> None:\\n    # Drop table if exists: ORA-00942 (table or view does not exist) -> ignore\\n    cur.execute(\\n        f\\\"\\\"\\\"\\n        BEGIN\\n            EXECUTE IMMEDIATE 'DROP TABLE {table_name} PURGE';\\n        EXCEPTION\\n            WHEN OTHERS THEN\\n                IF SQLCODE != -942 THEN\\n                    RAISE;\\n                END IF;\\n        END;\\\"\\\"\\\"\\n    )\\n\\n\\ndef _adb_expected_documents() -> list[Document]:\\n    return [\\n        Document(\\n            page_content=\\\"{'FIELD1': '1', 'FIELD_JSON': {'INNER_FIELD1': '1', 'INNER_FIELD2': '1'}}\\\",\\n            metadata={\\\"FIELD1\\\": \\\"1\\\"},\\n        ),\\n        Document(\\n            page_content=\\\"{'FIELD1': '2', 'FIELD_JSON': {'INNER_FIELD1': '2', 'INNER_FIELD2': '2'}}\\\",\\n            metadata={\\\"FIELD1\\\": \\\"2\\\"},\\n        ),\\n        Document(\\n            page_content=\\\"{'FIELD1': '3', 'FIELD_JSON': {'INNER_FIELD1': '3', 'INNER_FIELD2': '3'}}\\\",\\n            metadata={\\\"FIELD1\\\": \\\"3\\\"},\\n        ),\\n    ]\\n\\n\\ndef test_oracle_loader_connection_secrets_are_password_inputs() -> None:\\n    for component_class in (OracleDocLoaderComponent, OracleAutonomousDatabaseLoaderComponent):\\n        inputs = {input_.name: input_ for input_ in component_class.inputs}\\n        for name in (\\\"user\\\", \\\"password\\\", \\\"dsn\\\", \\\"wallet_password\\\"):\\n            assert inputs[name].password is True\\n\\n        assert inputs[\\\"connection_params\\\"].advanced is True\\n        assert \\\"Non-secret\\\" in inputs[\\\"connection_params\\\"].info\\n\\n\\ndef test_oracle_doc_loader_component_integration(\\n    request,\\n    connection: oracledb.Connection | None,\\n    connection_params: dict[str, str] | None,\\n) -> None:\\n    \\\"\\\"\\\"Integration test for loading rows from OracleDocLoaderComponent.\\\"\\\"\\\"\\n    if not connection_params:\\n        with (\\n            patch(\\n                \\\"lfx_oracle.components.oracle.oracledb_loaders.oracledb.connect\\\",\\n                return_value=MagicMock(),\\n            ) as mock_connect,\\n            patch(\\\"lfx_oracle.components.oracle.oracledb_loaders.OracleDocLoader\\\") as mock_loader,\\n        ):\\n            mock_loader.return_value.load.return_value = [\\n                Document(page_content=\\\"row1\\\"),\\n                Document(page_content=\\\"row2\\\"),\\n            ]\\n            test_connection_inputs = get_oracle_test_connection_inputs()\\n            component = OracleDocLoaderComponent().set(\\n                dsn=test_connection_inputs[\\\"dsn\\\"],\\n                params={\\\"owner\\\": \\\"mock_owner\\\", \\\"tablename\\\": \\\"MOCK_TABLE\\\", \\\"colname\\\": \\\"MARKDOWN\\\"},\\n            )\\n\\n            data_list = component.load_documents()\\n\\n        assert isinstance(data_list, list)\\n        assert len(data_list) == 2\\n        assert all(isinstance(d, Data) for d in data_list)\\n        assert {d.text for d in data_list} == {\\\"row1\\\", \\\"row2\\\"}\\n        assert component.status == data_list\\n        mock_connect.assert_called_once_with(dsn=test_connection_inputs[\\\"dsn\\\"])\\n        mock_loader.assert_called_once()\\n        return\\n\\n    assert connection is not None\\n    cur = connection.cursor()\\n\\n    table_name = _safe_identifier(f\\\"lfx_{request.node.name}\\\")\\n    col_name = \\\"MARKDOWN\\\"\\n    owner = get_oracle_owner(connection_params)\\n\\n    # Ensure clean slate\\n    _drop_table_if_exists(cur, table_name)\\n\\n    # Create table and insert rows\\n    cur.execute(f\\\"CREATE TABLE {table_name} ({col_name} CLOB)\\\")\\n    cur.execute(f\\\"INSERT INTO {table_name} ({col_name}) VALUES (:1)\\\", [\\\"row1\\\"])  # noqa: S608\\n    cur.execute(f\\\"INSERT INTO {table_name} ({col_name}) VALUES (:1)\\\", [\\\"row2\\\"])  # noqa: S608\\n    connection.commit()\\n\\n    try:\\n        component = OracleDocLoaderComponent().set(\\n            **get_oracle_connection_inputs(connection_params),\\n            params={\\n                \\\"owner\\\": owner,\\n                \\\"tablename\\\": table_name,\\n                \\\"colname\\\": col_name,\\n            },\\n        )\\n\\n        data_list = component.load_documents()\\n\\n        # Basic assertions\\n        assert isinstance(data_list, list)\\n        assert len(data_list) == 2\\n        assert all(isinstance(d, Data) for d in data_list)\\n\\n        texts = {d.text for d in data_list}\\n        assert texts == {\\\"row1\\\", \\\"row2\\\"}\\n\\n        # status updated\\n        assert component.status == data_list\\n    finally:\\n        # Cleanup the table\\n        _drop_table_if_exists(cur, table_name)\\n        connection.commit()\\n\\n\\ndef test_oracle_doc_loader_component_empty_table(\\n    request,\\n    connection: oracledb.Connection | None,\\n    connection_params: dict[str, str] | None,\\n) -> None:\\n    \\\"\\\"\\\"Integration test for OracleDocLoaderComponent with an empty table.\\\"\\\"\\\"\\n    if not connection_params:\\n        with (\\n            patch(\\n                \\\"lfx_oracle.components.oracle.oracledb_loaders.oracledb.connect\\\",\\n                return_value=MagicMock(),\\n            ) as mock_connect,\\n            patch(\\\"lfx_oracle.components.oracle.oracledb_loaders.OracleDocLoader\\\") as mock_loader,\\n        ):\\n            mock_loader.return_value.load.return_value = []\\n            test_connection_inputs = get_oracle_test_connection_inputs()\\n            component = OracleDocLoaderComponent().set(\\n                dsn=test_connection_inputs[\\\"dsn\\\"],\\n                params={\\\"owner\\\": \\\"mock_owner\\\", \\\"tablename\\\": \\\"MOCK_TABLE\\\", \\\"colname\\\": \\\"MARKDOWN\\\"},\\n            )\\n\\n            data_list = component.load_documents()\\n\\n        assert isinstance(data_list, list)\\n        assert data_list == []\\n        assert component.status == []\\n        mock_connect.assert_called_once_with(dsn=test_connection_inputs[\\\"dsn\\\"])\\n        mock_loader.assert_called_once()\\n        return\\n\\n    assert connection is not None\\n    cur = connection.cursor()\\n\\n    table_name = _safe_identifier(f\\\"lfx_empty_{request.node.name}\\\")\\n    col_name = \\\"MARKDOWN\\\"\\n    owner = get_oracle_owner(connection_params)\\n\\n    _drop_table_if_exists(cur, table_name)\\n    cur.execute(f\\\"CREATE TABLE {table_name} ({col_name} CLOB)\\\")\\n    connection.commit()\\n\\n    try:\\n        component = OracleDocLoaderComponent().set(\\n            **get_oracle_connection_inputs(connection_params),\\n            params={\\n                \\\"owner\\\": owner,\\n                \\\"tablename\\\": table_name,\\n                \\\"colname\\\": col_name,\\n            },\\n        )\\n\\n        data_list = component.load_documents()\\n        assert isinstance(data_list, list)\\n        assert data_list == []\\n        assert component.status == []\\n    finally:\\n        _drop_table_if_exists(cur, table_name)\\n        connection.commit()\\n\\n\\ndef test_oracle_autonomous_database_loader_component_load_documents(\\n    request,\\n    connection: oracledb.Connection | None,\\n    connection_params: dict[str, str] | None,\\n) -> None:\\n    if not connection_params:\\n        with patch(\\\"lfx_oracle.components.oracle.oracledb_loaders.OracleAutonomousDatabaseLoader\\\") as mock_loader:\\n            mock_loader.return_value.load.return_value = _adb_expected_documents()\\n            test_connection_inputs = get_oracle_test_connection_inputs()\\n            component = OracleAutonomousDatabaseLoaderComponent().set(\\n                query=\\\"select * from test_table\\\",\\n                **test_connection_inputs,\\n                metadata=\\\"FIELD1\\\",\\n            )\\n\\n            data_list = component.load_documents()\\n\\n        assert [data.text for data in data_list] == [doc.page_content for doc in _adb_expected_documents()]\\n        assert [data.data[\\\"FIELD1\\\"] for data in data_list] == [\\\"1\\\", \\\"2\\\", \\\"3\\\"]\\n        assert component.status == data_list\\n        mock_loader.assert_called_once()\\n        assert mock_loader.call_args.kwargs == {\\n            \\\"query\\\": \\\"select * from test_table\\\",\\n            \\\"user\\\": test_connection_inputs[\\\"user\\\"],\\n            \\\"password\\\": test_connection_inputs[\\\"password\\\"],\\n            \\\"schema\\\": None,\\n            \\\"dsn\\\": test_connection_inputs[\\\"dsn\\\"],\\n            \\\"config_dir\\\": None,\\n            \\\"wallet_location\\\": None,\\n            \\\"wallet_password\\\": None,\\n            \\\"metadata\\\": [\\\"FIELD1\\\"],\\n            \\\"parameter\\\": mock_loader.call_args.kwargs[\\\"parameter\\\"],\\n        }\\n        assert mock_loader.call_args.kwargs[\\\"parameter\\\"] in (None, {})\\n        return\\n\\n    assert connection is not None\\n    cur = connection.cursor()\\n    table_name = _safe_identifier(f\\\"adb_{request.node.name}\\\")\\n    owner = get_oracle_owner(connection_params)\\n\\n    _drop_table_if_exists(cur, table_name)\\n    cur.execute(f\\\"CREATE TABLE {table_name} (FIELD1 VARCHAR2(10), FIELD_JSON CLOB)\\\")\\n    cur.execute(\\n        f\\\"INSERT INTO {table_name} (FIELD1, FIELD_JSON) VALUES (:1, :2)\\\",  # noqa: S608\\n        [\\\"1\\\", \\\"{'INNER_FIELD1': '1', 'INNER_FIELD2': '1'}\\\"],\\n    )\\n    cur.execute(\\n        f\\\"INSERT INTO {table_name} (FIELD1, FIELD_JSON) VALUES (:1, :2)\\\",  # noqa: S608\\n        [\\\"2\\\", \\\"{'INNER_FIELD1': '2', 'INNER_FIELD2': '2'}\\\"],\\n    )\\n    connection.commit()\\n\\n    try:\\n        component = OracleAutonomousDatabaseLoaderComponent().set(\\n            query=f\\\"SELECT FIELD1, FIELD_JSON FROM {owner}.{table_name} ORDER BY FIELD1\\\",  # noqa: S608\\n            **get_oracle_connection_inputs(connection_params),\\n            metadata=\\\"FIELD1\\\",\\n        )\\n\\n        data_list = component.load_documents()\\n\\n        assert len(data_list) == 2\\n        assert [data.data[\\\"FIELD1\\\"] for data in data_list] == [\\\"1\\\", \\\"2\\\"]\\n        assert \\\"FIELD_JSON\\\" in data_list[0].text\\n        assert component.status == data_list\\n    finally:\\n        _drop_table_if_exists(cur, table_name)\\n        connection.commit()\\n\\n\\ndef test_oracle_autonomous_database_loader_component_maps_aliases_and_optional_args() -> None:\\n    with patch(\\\"lfx_oracle.components.oracle.oracledb_loaders.OracleAutonomousDatabaseLoader\\\") as mock_loader:\\n        mock_loader.return_value.load.return_value = []\\n        test_connection_inputs = get_oracle_test_connection_inputs(include_wallet_password=True)\\n        component = OracleAutonomousDatabaseLoaderComponent().set(\\n            query=\\\"select * from my_table where id = :id\\\",\\n            **test_connection_inputs,\\n            connection_params={\\n                \\\"config_dir\\\": \\\"/wallet/config\\\",\\n                \\\"wallet_location\\\": \\\"/wallet\\\",\\n                \\\"schema\\\": \\\"MY_SCHEMA\\\",\\n            },\\n            metadata=\\\"FIELD1, FIELD2\\\",\\n            parameter={\\\"id\\\": 7},\\n        )\\n\\n        data_list = component.load_documents()\\n\\n    assert data_list == []\\n    assert component.status == []\\n    mock_loader.assert_called_once_with(\\n        query=\\\"select * from my_table where id = :id\\\",\\n        user=test_connection_inputs[\\\"user\\\"],\\n        password=test_connection_inputs[\\\"password\\\"],\\n        schema=\\\"MY_SCHEMA\\\",\\n        dsn=test_connection_inputs[\\\"dsn\\\"],\\n        config_dir=\\\"/wallet/config\\\",\\n        wallet_location=\\\"/wallet\\\",\\n        wallet_password=test_connection_inputs[\\\"wallet_password\\\"],\\n        metadata=[\\\"FIELD1\\\", \\\"FIELD2\\\"],\\n        parameter={\\\"id\\\": 7},\\n    )\\n\\n\\ndef test_oracle_autonomous_database_loader_component_rejects_sensitive_connection_params() -> None:\\n    test_connection_inputs = get_oracle_test_connection_inputs(include_wallet_password=True)\\n    component = OracleAutonomousDatabaseLoaderComponent().set(\\n        query=\\\"select * from my_table\\\",\\n        **test_connection_inputs,\\n        connection_params={\\n            \\\"access_token\\\": (test_connection_inputs[\\\"user\\\"], test_connection_inputs[\\\"wallet_password\\\"]),\\n            \\\"private_key\\\": test_connection_inputs[\\\"wallet_password\\\"],\\n        },\\n    )\\n\\n    with pytest.raises(\\n        ValueError,\\n        match=\\\"connection_params contains sensitive keys: access_token, private_key\\\\\\\\. Use the dedicated secret fields\\\",\\n    ):\\n        component.load_documents()\\n\\n\\ndef test_oracle_autonomous_database_loader_component_parses_credentials_from_dsn() -> None:\\n    with patch(\\\"lfx_oracle.components.oracle.oracledb_loaders.OracleAutonomousDatabaseLoader\\\") as mock_loader:\\n        mock_loader.return_value.load.return_value = []\\n        test_connection_inputs = get_oracle_test_connection_inputs()\\n        component = OracleAutonomousDatabaseLoaderComponent().set(\\n            query=\\\"select * from my_table\\\",\\n            dsn=(\\n                f\\\"{test_connection_inputs['user']}/{test_connection_inputs['password']}@{test_connection_inputs['dsn']}\\\"\\n            ),\\n            metadata=\\\"FIELD1\\\",\\n        )\\n\\n        data_list = component.load_documents()\\n\\n    assert data_list == []\\n    assert component.status == []\\n    mock_loader.assert_called_once()\\n    assert mock_loader.call_args.kwargs == {\\n        \\\"query\\\": \\\"select * from my_table\\\",\\n        \\\"user\\\": test_connection_inputs[\\\"user\\\"],\\n        \\\"password\\\": test_connection_inputs[\\\"password\\\"],\\n        \\\"schema\\\": None,\\n        \\\"dsn\\\": test_connection_inputs[\\\"dsn\\\"],\\n        \\\"config_dir\\\": None,\\n        \\\"wallet_location\\\": None,\\n        \\\"wallet_password\\\": None,\\n        \\\"metadata\\\": [\\\"FIELD1\\\"],\\n        \\\"parameter\\\": mock_loader.call_args.kwargs[\\\"parameter\\\"],\\n    }\\n    assert mock_loader.call_args.kwargs[\\\"parameter\\\"] in (None, {})\\n\\n\\ndef test_oracle_autonomous_database_loader_component_requires_user_and_password() -> None:\\n    test_connection_inputs = get_oracle_test_connection_inputs()\\n    component = OracleAutonomousDatabaseLoaderComponent().set(\\n        query=\\\"select * from my_table\\\",\\n        dsn=test_connection_inputs[\\\"dsn\\\"],\\n    )\\n\\n    with pytest.raises(\\n        ValueError,\\n        match=\\\"Connection settings must include user and password, either in the dedicated fields or inside the DSN\\\\\\\\.\\\",\\n    ):\\n        component.load_documents()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/oracle/tests/test_oraclevs_vector_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f9ae024ffdff1e1098a438e1f7c161b04158e84079212f93f0b69d92af6fc9ad\",\"content\":\"\\\"\\\"\\\"Unit tests for the Oracle Vector Store component (lfx-oracle bundle).\\n\\nThe component used to live at ``lfx.components.oracledb.oraclevs`` and was\\ntested under ``src/backend/tests/unit/components/vectorstores/`` using the\\nin-tree ``ComponentTestBaseWithoutClient`` helper.  It has since been\\nextracted into a standalone bundle; these tests now travel with the bundle\\nand import the public bundle entry point.  The base-class scaffolding\\n(which parametrised version-compat tests against a saved-fixture\\ndirectory) is dropped: ``OracleVectorStoreComponent`` is new in 1.11.0 and\\nhas no historical schema fixtures to validate against\\n(``file_names_mapping`` was empty).\\n\\\"\\\"\\\"\\n\\nfrom decimal import Decimal\\nfrom typing import Any\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom langchain_oracledb.vectorstores.oraclevs import drop_table_purge\\nfrom lfx.schema.data import Data\\nfrom lfx_oracle.components.oracle import OracleVectorStoreComponent\\nfrom lfx_oracle.components.oracle.connection import build_connection_params, split_credentialized_dsn\\nfrom oracle_test_utils import (\\n    get_oracle_connection_inputs,\\n    get_oracle_connection_params,\\n    get_oracle_embedding_params,\\n    get_oracle_test_connection_inputs,\\n)\\nfrom pydantic import BaseModel\\n\\n\\ndef _expected_connection_params(kwargs: dict[str, Any]) -> dict[str, Any]:\\n    return build_connection_params(\\n        kwargs.get(\\\"connection_params\\\"),\\n        user=kwargs.get(\\\"user\\\"),\\n        password=kwargs.get(\\\"password\\\"),\\n        dsn=kwargs.get(\\\"dsn\\\"),\\n        wallet_password=kwargs.get(\\\"wallet_password\\\"),\\n    )\\n\\n\\nclass _MetadataModel(BaseModel):\\n    value: str\\n\\n\\ndef test_oracle_vector_store_connection_secrets_are_password_inputs() -> None:\\n    inputs = {input_.name: input_ for input_ in OracleVectorStoreComponent.inputs}\\n\\n    for name in (\\\"user\\\", \\\"password\\\", \\\"dsn\\\", \\\"wallet_password\\\"):\\n        assert inputs[name].password is True\\n\\n    assert inputs[\\\"connection_params\\\"].advanced is True\\n    assert \\\"Non-secret\\\" in inputs[\\\"connection_params\\\"].info\\n\\n\\ndef test_connection_params_rejects_sensitive_keys() -> None:\\n    with pytest.raises(\\n        ValueError,\\n        match=(\\n            \\\"connection_params contains sensitive keys: connection_string, private_key\\\\\\\\. \\\"\\n            \\\"Use the dedicated secret fields\\\"\\n        ),\\n    ):\\n        build_connection_params(\\n            {\\n                \\\"connection_string\\\": \\\"user/password@host/service\\\",  # pragma: allowlist secret\\n                \\\"config_dir\\\": \\\"/wallet/config\\\",\\n                \\\"private_key\\\": \\\"key\\\",  # pragma: allowlist secret\\n            },\\n            dsn=\\\"host/service\\\",\\n        )\\n\\n\\ndef test_connection_params_rejects_normalized_sensitive_keys() -> None:\\n    with pytest.raises(ValueError, match=\\\"connection_params contains sensitive keys\\\"):\\n        build_connection_params(\\n            {\\\"password \\\": \\\"secret\\\", \\\"wallet-password\\\": \\\"wallet-secret\\\"},  # pragma: allowlist secret\\n            dsn=\\\"host/service\\\",\\n        )\\n\\n\\ndef test_connection_params_allows_non_secret_sharding_keys() -> None:\\n    params = build_connection_params(\\n        {\\\"shardingkey\\\": [\\\"tenant\\\"], \\\"supershardingkey\\\": [\\\"region\\\"]},\\n        dsn=\\\"host/service\\\",\\n    )\\n\\n    assert params == {\\n        \\\"dsn\\\": \\\"host/service\\\",\\n        \\\"shardingkey\\\": [\\\"tenant\\\"],\\n        \\\"supershardingkey\\\": [\\\"region\\\"],\\n    }\\n\\n\\ndef test_build_connection_params_parses_credentials_from_dsn() -> None:\\n    params = build_connection_params(\\n        {\\\"config_dir\\\": \\\"/wallet/config\\\"},\\n        dsn=\\\"user/p@ssword@host/service\\\",\\n    )\\n\\n    assert params == {\\n        \\\"config_dir\\\": \\\"/wallet/config\\\",\\n        \\\"dsn\\\": \\\"host/service\\\",\\n        \\\"password\\\": \\\"p\\\" + \\\"@ssword\\\",\\n        \\\"user\\\": \\\"user\\\",\\n    }\\n\\n\\ndef test_split_credentialized_dsn_allows_at_sign_in_password() -> None:\\n    user, password, dsn = split_credentialized_dsn(\\\"user/p@ssword@host/service\\\")\\n\\n    assert user == \\\"user\\\"\\n    assert password == \\\"p\\\" + \\\"@ssword\\\"\\n    assert dsn == \\\"host/service\\\"\\n\\n\\nclass TestOracleVectorStoreComponent:\\n    @pytest.fixture\\n    def component_class(self) -> type[Any]:\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return OracleVectorStoreComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self, request) -> dict[str, Any]:\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        connection_params = get_oracle_connection_params()\\n        if connection_params:\\n            from lfx_oracle.components.oracle import OracleEmbeddingsComponent\\n\\n            embedding = OracleEmbeddingsComponent(\\n                **get_oracle_connection_inputs(connection_params),\\n                embedding_params=get_oracle_embedding_params(),\\n            ).build_embeddings()\\n        else:\\n            embedding = MagicMock(name=\\\"oracle_embedding\\\")\\n\\n        return {\\n            \\\"embedding\\\": embedding,\\n            \\\"table_name\\\": f\\\"table_{request.node.name}\\\",\\n            **get_oracle_connection_inputs(connection_params or get_oracle_test_connection_inputs()),\\n            \\\"create_index\\\": True,\\n            \\\"index_params\\\": {\\\"idx_name\\\": f\\\"index_{request.node.name}\\\", \\\"idx_type\\\": \\\"HNSW\\\"},\\n            \\\"mutate_on_duplicate\\\": False,\\n        }\\n\\n    def test_create_db(self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Test the create_collection method.\\\"\\\"\\\"\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        if get_oracle_connection_params():\\n            component.build_vector_store()\\n            return\\n\\n        vector_store = MagicMock()\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=MagicMock()) as mock_connect,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.OracleVS\\\", return_value=vector_store) as mock_oracle_vs,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.create_index\\\") as mock_create_index,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.1.0\\\", create=True),\\n        ):\\n            assert component.build_vector_store() is vector_store\\n\\n        mock_connect.assert_called_once_with(**_expected_connection_params(default_kwargs))\\n        mock_oracle_vs.assert_called_once()\\n        mock_create_index.assert_called_once()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"search_type\\\", \\\"expected_search_type\\\", \\\"expected_kwargs\\\"),\\n        [\\n            (\\\"Similarity\\\", \\\"similarity\\\", {\\\"k\\\": 2}),\\n            (\\\"Similarity with score threshold\\\", \\\"similarity\\\", {\\\"k\\\": 2}),\\n            (\\\"MMR (Max Marginal Relevance)\\\", \\\"mmr\\\", {\\\"k\\\": 2}),\\n        ],\\n    )\\n    def test_search_dispatches_to_expected_langchain_mode(\\n        self,\\n        component_class: type[OracleVectorStoreComponent],\\n        search_type: str,\\n        expected_search_type: str,\\n        expected_kwargs: dict[str, Any],\\n    ) -> None:\\n        component: OracleVectorStoreComponent = component_class().set(\\n            search_type=search_type,\\n            search_query=\\\"oracle vectors\\\",\\n            number_of_results=2,\\n        )\\n\\n        vector_store = MagicMock()\\n        vector_store.search.return_value = [Document(page_content=\\\"Oracle vector search result\\\")]\\n        component._cached_vector_store = vector_store\\n\\n        results = component.search_documents()\\n\\n        assert len(results) == 1\\n        assert results[0].text == \\\"Oracle vector search result\\\"\\n        vector_store.search.assert_called_once_with(\\n            query=\\\"oracle vectors\\\",\\n            search_type=expected_search_type,\\n            **expected_kwargs,\\n        )\\n\\n    def test_similarity_search(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the similarity search functionality through the component.\\\"\\\"\\\"\\n        # Create test data with distinct topics\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n            \\\"The lazy dog sleeps all day long\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"search_type\\\"] = \\\"Similarity\\\"\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.side_effect = [\\n                [\\n                    Document(page_content=\\\"The lazy dog sleeps all day long\\\"),\\n                    Document(page_content=\\\"The quick brown fox jumps over the lazy dog\\\"),\\n                ],\\n                [\\n                    Document(page_content=\\\"The lazy dog sleeps all day long\\\"),\\n                    Document(page_content=\\\"The quick brown fox jumps over the lazy dog\\\"),\\n                    Document(page_content=\\\"Machine learning models process data\\\"),\\n                ],\\n            ]\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        # Test similarity search through the component\\n        component.set(search_query=\\\"dog sleeping\\\")\\n        results = component.search_documents()\\n\\n        assert len(results) == 2\\n        # The most relevant results should be about dogs\\n        assert any(\\\"dog\\\" in result.text.lower() for result in results)\\n\\n        # Test with different number of results\\n        component.set(number_of_results=3)\\n        results = component.search_documents()\\n        assert len(results) == 3\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_mmr_search(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the MMR search functionality through the component.\\\"\\\"\\\"\\n        # Create test data with some similar documents\\n        test_data = [\\n            \\\"The quick brown fox jumps\\\",\\n            \\\"The quick brown fox leaps\\\",\\n            \\\"The quick brown fox hops\\\",\\n            \\\"Something completely different about cats\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"search_type\\\"] = \\\"MMR (Max Marginal Relevance)\\\"\\n        default_kwargs[\\\"number_of_results\\\"] = 3\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.side_effect = [\\n                [\\n                    Document(page_content=\\\"The quick brown fox jumps\\\"),\\n                    Document(page_content=\\\"The quick brown fox leaps\\\"),\\n                    Document(page_content=\\\"Something completely different about cats\\\"),\\n                ],\\n                [\\n                    Document(page_content=\\\"The quick brown fox jumps\\\"),\\n                    Document(page_content=\\\"Something completely different about cats\\\"),\\n                ],\\n            ]\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        # Test MMR search through the component\\n        component.set(search_query=\\\"quick fox\\\")\\n        results = component.search_documents()\\n\\n        assert len(results) == 3\\n        # Results should be diverse but relevant\\n        assert any(\\\"fox\\\" in result.text.lower() for result in results)\\n\\n        # Test with different settings\\n        component.set(number_of_results=2)\\n        diverse_results = component.search_documents()\\n        assert len(diverse_results) == 2\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_search_with_different_types(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test search with different search types.\\\"\\\"\\\"\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.side_effect = [\\n                [\\n                    Document(page_content=\\\"Python is a popular programming language\\\"),\\n                    Document(page_content=\\\"Machine learning models process data\\\"),\\n                ],\\n                [\\n                    Document(page_content=\\\"Python is a popular programming language\\\"),\\n                    Document(page_content=\\\"Machine learning models process data\\\"),\\n                ],\\n            ]\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        # Test similarity search\\n        component.set(search_type=\\\"Similarity\\\", search_query=\\\"programming languages\\\")\\n        similarity_results = component.search_documents()\\n        assert len(similarity_results) == 2\\n        assert any(\\\"python\\\" in result.text.lower() for result in similarity_results)\\n\\n        # Test MMR search\\n        component.set(search_type=\\\"MMR (Max Marginal Relevance)\\\", search_query=\\\"programming languages\\\")\\n        mmr_results = component.search_documents()\\n        assert len(mmr_results) == 2\\n\\n        # Test with empty query\\n        component.set(search_query=\\\"\\\")\\n        empty_results = component.search_documents()\\n        assert len(empty_results) == 0\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_legacy_score_threshold_search_type_falls_back_to_similarity(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Old saved flows using score-threshold mode should degrade to similarity.\\\"\\\"\\\"\\n        test_data = [\\n            \\\"The quick brown fox jumps over the lazy dog\\\",\\n            \\\"Python is a popular programming language\\\",\\n            \\\"Machine learning models process data\\\",\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = [Data(text=text) for text in test_data]\\n        default_kwargs[\\\"number_of_results\\\"] = 2\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.side_effect = [\\n                [\\n                    Document(page_content=\\\"Python is a popular programming language\\\"),\\n                    Document(page_content=\\\"The quick brown fox jumps over the lazy dog\\\"),\\n                ],\\n                [\\n                    Document(page_content=\\\"Python is a popular programming language\\\"),\\n                    Document(page_content=\\\"The quick brown fox jumps over the lazy dog\\\"),\\n                    Document(page_content=\\\"Machine learning models process data\\\"),\\n                ],\\n            ]\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        component.set(\\n            search_type=\\\"Similarity with score threshold\\\",\\n            search_query=\\\"programming languages\\\",\\n            number_of_results=2,\\n        )\\n        results = component.search_documents()\\n\\n        assert len(results) == 2\\n        assert any(\\\"python\\\" in result.text.lower() for result in results)\\n        assert any(\\\"programming\\\" in result.text.lower() for result in results)\\n\\n        component.set(number_of_results=3)\\n        results = component.search_documents()\\n        assert len(results) == 3\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_retrieval_data_without_metadata(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the retrieval with documents that have no metadata.\\\"\\\"\\\"\\n        # Create a collection with documents but no metadata\\n        test_data = [\\n            Data(data={\\\"text\\\": \\\"Simple document 1\\\"}),\\n            Data(data={\\\"text\\\": \\\"Simple document 2\\\"}),\\n        ]\\n        default_kwargs[\\\"ingest_data\\\"] = test_data\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.return_value = [\\n                Document(page_content=\\\"Simple document 1\\\"),\\n                Document(page_content=\\\"Simple document 2\\\"),\\n            ]\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        # Get the collection data\\n        component.set(search_query=\\\"simple search\\\")\\n        data_objects = component.search_documents()\\n\\n        # Verify the conversion\\n        assert len(data_objects) == 2\\n        for data_obj in data_objects:\\n            assert isinstance(data_obj, Data)\\n            assert \\\"text\\\" in data_obj.data\\n            assert data_obj.data[\\\"text\\\"] in {\\\"Simple document 1\\\", \\\"Simple document 2\\\"}\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_retrieval_data_empty_collection(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        \\\"\\\"\\\"Test the retrieval function with an empty collection.\\\"\\\"\\\"\\n        # Create an empty collection\\n        default_kwargs[\\\"ingest_data\\\"] = []\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        if not get_oracle_connection_params():\\n            vector_store = MagicMock()\\n            vector_store.search.return_value = []\\n            component._cached_vector_store = vector_store\\n        else:\\n            component.build_vector_store()\\n\\n        # Get the collection data\\n        component.set(search_query=\\\"search empty\\\")\\n        data_objects = component.search_documents()\\n\\n        # Verify the conversion\\n        assert len(data_objects) == 0\\n\\n        if get_oracle_connection_params():\\n            drop_table_purge(component.connection, default_kwargs[\\\"table_name\\\"])\\n\\n    def test_build_vector_store_generates_index_defaults_and_serializes_metadata(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        default_kwargs[\\\"ingest_data\\\"] = [\\n            Data(\\n                data={\\n                    \\\"text\\\": \\\"Oracle vectors\\\",\\n                    \\\"model\\\": _MetadataModel(value=\\\"nested\\\"),\\n                    \\\"items\\\": [_MetadataModel(value=\\\"list-item\\\"), {\\\"inner\\\": _MetadataModel(value=\\\"dict-item\\\")}],\\n                    \\\"coords\\\": (1, 2),\\n                }\\n            )\\n        ]\\n        default_kwargs[\\\"index_params\\\"] = {\\\"\\\": \\\"drop-me\\\"}\\n\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        supports_mutate_on_duplicate = any(\\n            getattr(input_, \\\"name\\\", None) == \\\"mutate_on_duplicate\\\" for input_ in component.inputs\\n        )\\n        vector_store = MagicMock()\\n\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=MagicMock()) as mock_connect,\\n            patch(\\n                \\\"lfx_oracle.components.oracle.oraclevs.OracleVS.from_documents\\\",\\n                return_value=vector_store,\\n            ) as mock_from_documents,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.create_index\\\") as mock_create_index,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.1.0\\\", create=True),\\n        ):\\n            assert component.build_vector_store() is vector_store\\n\\n        mock_connect.assert_called_once_with(**_expected_connection_params(default_kwargs))\\n        documents = mock_from_documents.call_args.kwargs[\\\"documents\\\"]\\n        assert len(documents) == 1\\n        assert documents[0].metadata == {\\n            \\\"model\\\": {\\\"value\\\": \\\"nested\\\"},\\n            \\\"items\\\": [{\\\"value\\\": \\\"list-item\\\"}, {\\\"inner\\\": {\\\"value\\\": \\\"dict-item\\\"}}],\\n            \\\"coords\\\": [1, 2],\\n        }\\n        if supports_mutate_on_duplicate:\\n            assert mock_from_documents.call_args.kwargs.get(\\\"mutate_on_duplicate\\\", False) is False\\n        else:\\n            assert \\\"mutate_on_duplicate\\\" not in mock_from_documents.call_args.kwargs\\n\\n        index_params = mock_create_index.call_args.args[2]\\n        assert index_params[\\\"idx_type\\\"] == \\\"HNSW\\\"\\n        assert index_params[\\\"idx_name\\\"].startswith(f\\\"{default_kwargs['table_name']}_idx_\\\")\\n        assert \\\"\\\" not in index_params\\n\\n    def test_build_vector_store_defaults_none_index_params(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        component.index_params = None\\n        vector_store = MagicMock()\\n\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=MagicMock()),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.OracleVS\\\", return_value=vector_store),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.create_index\\\") as mock_create_index,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.1.0\\\", create=True),\\n        ):\\n            assert component.build_vector_store() is vector_store\\n\\n        index_params = mock_create_index.call_args.args[2]\\n        assert index_params[\\\"idx_type\\\"] == \\\"HNSW\\\"\\n        assert index_params[\\\"idx_name\\\"].startswith(f\\\"{default_kwargs['table_name']}_idx_\\\")\\n\\n    def test_build_vector_store_omits_mutate_on_duplicate_for_langchain_1_0(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        default_kwargs[\\\"create_index\\\"] = False\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        vector_store = MagicMock()\\n\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=MagicMock()) as mock_connect,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.OracleVS\\\", return_value=vector_store) as mock_oracle_vs,\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.0.2\\\", create=True),\\n        ):\\n            assert component.build_vector_store() is vector_store\\n\\n        mock_connect.assert_called_once_with(**_expected_connection_params(default_kwargs))\\n        assert \\\"mutate_on_duplicate\\\" not in mock_oracle_vs.call_args.kwargs\\n\\n    def test_build_vector_store_closes_opened_connection_when_construction_fails(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        default_kwargs[\\\"create_index\\\"] = False\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        connection = MagicMock()\\n\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=connection),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.OracleVS\\\", side_effect=RuntimeError(\\\"construct boom\\\")),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.1.0\\\", create=True),\\n            pytest.raises(RuntimeError, match=\\\"construct boom\\\"),\\n        ):\\n            component.build_vector_store()\\n\\n        connection.close.assert_called_once_with()\\n        assert component.connection is None\\n\\n    def test_build_vector_store_closes_opened_connection_when_index_creation_fails(\\n        self, component_class: type[OracleVectorStoreComponent], default_kwargs: dict[str, Any]\\n    ) -> None:\\n        component: OracleVectorStoreComponent = component_class().set(**default_kwargs)\\n        connection = MagicMock()\\n        vector_store = MagicMock()\\n\\n        with (\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.oracledb.connect\\\", return_value=connection),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.OracleVS\\\", return_value=vector_store),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.create_index\\\", side_effect=RuntimeError(\\\"index boom\\\")),\\n            patch(\\\"lfx_oracle.components.oracle.oraclevs.version\\\", return_value=\\\"1.1.0\\\", create=True),\\n            pytest.raises(RuntimeError, match=\\\"index boom\\\"),\\n        ):\\n            component.build_vector_store()\\n\\n        connection.close.assert_called_once_with()\\n        assert component.connection is None\\n\\n    def test_search_documents_normalizes_decimal_metadata(\\n        self, component_class: type[OracleVectorStoreComponent]\\n    ) -> None:\\n        component: OracleVectorStoreComponent = component_class().set(\\n            search_type=\\\"Similarity\\\",\\n            search_query=\\\"oracle vectors\\\",\\n            number_of_results=1,\\n        )\\n        vector_store = MagicMock()\\n        vector_store.search.return_value = [\\n            Document(\\n                page_content=\\\"Oracle vector search result\\\",\\n                metadata={\\n                    \\\"score\\\": Decimal(\\\"1.5\\\"),\\n                    \\\"nested\\\": {\\\"count\\\": Decimal(2)},\\n                    \\\"items\\\": [Decimal(\\\"3.25\\\")],\\n                },\\n            )\\n        ]\\n        component._cached_vector_store = vector_store\\n\\n        results = component.search_documents()\\n\\n        assert len(results) == 1\\n        assert results[0].data[\\\"score\\\"] == 1.5\\n        assert results[0].data[\\\"nested\\\"][\\\"count\\\"] == 2.0\\n        assert results[0].data[\\\"items\\\"] == [3.25]\\n\\n    def test_search_documents_clears_status_for_empty_query(\\n        self, component_class: type[OracleVectorStoreComponent]\\n    ) -> None:\\n        component: OracleVectorStoreComponent = component_class().set(\\n            search_type=\\\"Similarity\\\",\\n            search_query=\\\"\\\",\\n            number_of_results=1,\\n        )\\n        component.status = [Data(text=\\\"stale\\\")]\\n        component.build_vector_store = MagicMock()\\n\\n        assert component.search_documents() == []\\n        assert component.status == []\\n        component.build_vector_store.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0844e4e6f420c149dfe97288598e609891f10cb02462afa941735ad226a0a2a6\",\"content\":\"# lfx-paddle\\n\\nPaddleOCR as a standalone Langflow Extension Bundle.\\n\\nShips the **PaddleOCR** component, which performs either layout-aware document\\nparsing into Markdown (`PP-StructureV3`, `PaddleOCR-VL-1.6`) or plain OCR text\\nrecognition (`PP-OCRv5`, `PP-OCRv6`). It talks to the PaddleOCR\\n[AI Studio async Job HTTP API](https://paddlepaddle.github.io/PaddleOCR/latest/en/version3.x/paddleocr_and_ppstructure.html)\\n(`submit -> poll -> fetch`) directly via `httpx`, so it does **not** require the\\n`paddleocr` Python SDK (whose transitive `pyyaml` constraint conflicts with\\nLangflow's dependency tree).\\n\\n## Install\\n\\n```bash\\npip install lfx-paddle\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point. After install, restart your Langflow server; the component will\\nappear in the palette under the `paddle` group.\\n\\nYou will need an AI Studio access token\\n(<https://aistudio.baidu.com/account/accessToken>) to run the component.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/paddle\\npip install -e .\\nlfx extension validate src/lfx_paddle\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name or the old import paths under\\n`lfx.components.paddle.*` are rewritten to the new namespaced ID\\n`ext:paddle:PaddleOCRComponent@official` by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"df5f5b7e5ca5cdc6a4b139a5f1173fcfbb980def7c51c566b4f4556ba9964c56\",\"content\":\"[project]\\nname = \\\"lfx-paddle\\\"\\nversion = \\\"0.1.4\\\"\\ndescription = \\\"PaddleOCR component (OCR and layout-aware document parsing via the AI Studio async Job API) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"paddle\\\", \\\"paddleocr\\\", \\\"ocr\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports the\\n# bundle's components rely on.  The PaddleOCR component talks to the PaddleOCR\\n# AI Studio async Job HTTP API directly via ``httpx`` -- it intentionally does\\n# NOT depend on the ``paddleocr`` SDK, whose transitive ``pyyaml`` constraint\\n# conflicts with Langflow's dependency tree.  ``httpx`` is already a runtime\\n# dependency of ``lfx``; it is declared here too because the component imports\\n# it directly.\\n# lfx is floored at the current major.minor line and capped below the next lfx\\n# major; the floor is read from src/lfx/pyproject.toml at port time and\\n# re-synced on ``make patch`` via scripts/ci/sync_bundle_lfx_pin.py.\\n# Fine-grained BUNDLE_API compatibility is enforced via extension.json's\\n# lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"httpx>=0.24.0,<1.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-paddle = \\\"lfx_paddle\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_paddle package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_paddle\\\"]\\ninclude = [\\\"src/lfx_paddle/extension.json\\\", \\\"src/lfx_paddle/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_paddle\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/src/lfx_paddle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5a329287f3a2ef1a84da519f9f1aeddcff5eb6fde9b35ac43760d9e3a5e3369d\",\"content\":\"\\\"\\\"\\\"lfx-paddle: PaddleOCR bundle.\\n\\nDistribution unit ``lfx-paddle``.  At runtime Langflow's loader discovers\\n``extension.json`` shipped alongside this ``__init__.py`` and registers the\\nbundle's component under the namespaced ID\\n``ext:paddle:PaddleOCRComponent@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_paddle.components.paddle.paddleocr import PaddleOCRComponent\\n\\n__all__ = [\\\"PaddleOCRComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/src/lfx_paddle/components/paddle/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73bdd91d14bdd2cce86f3e0002b8f797db6635e87be7d6587f46d165df9effc3\",\"content\":\"\\\"\\\"\\\"Component re-exports for the ``paddle`` bundle.\\n\\nSaved-flow migration entries that target ``lfx.components.paddle.<Class>``\\nresolve through this package, so the moved Component class(es) must be\\nimportable from here by name.\\n\\\"\\\"\\\"\\n\\nfrom .paddleocr import PaddleOCRComponent\\n\\n__all__ = [\\\"PaddleOCRComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/src/lfx_paddle/components/paddle/paddleocr.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cfb585d09d41abc7310e0ce165b00dfa153755c1b7e36cd0cd20d14dc74aef99\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nimport time\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport httpx\\nfrom lfx.base.data.base_file import BaseFileComponent\\nfrom lfx.inputs.inputs import BoolInput, DropdownInput, FloatInput, IntInput, MessageTextInput, SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.ssrf_protection import (\\n    is_ssrf_protection_enabled,\\n    validate_and_resolve_connector_url,\\n    validate_and_resolve_url,\\n)\\nfrom lfx.utils.ssrf_transport import create_ssrf_protected_sync_client\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\nclass PaddleOCRComponent(BaseFileComponent):\\n    display_name = \\\"PaddleOCR\\\"\\n    description = \\\"Use PaddleOCR for either layout-aware document parsing into Markdown or plain OCR text recognition.\\\"\\n    documentation = \\\"https://paddlepaddle.github.io/PaddleOCR/latest/en/version3.x/paddleocr_and_ppstructure.html\\\"\\n    icon = \\\"file-search\\\"\\n    name = \\\"PaddleOCR\\\"\\n\\n    VALID_EXTENSIONS = [\\\"png\\\", \\\"jpg\\\", \\\"jpeg\\\", \\\"bmp\\\", \\\"tiff\\\", \\\"webp\\\", \\\"pdf\\\"]\\n    DEFAULT_BASE_URL = \\\"https://paddleocr.aistudio-app.com\\\"\\n    API_PATH = \\\"/api/v2/ocr/jobs\\\"\\n    REQUEST_TIMEOUT = 300.0\\n    INITIAL_POLL_INTERVAL = 3.0\\n    POLL_MULTIPLIER = 1.5\\n    MAX_POLL_INTERVAL = 15.0\\n\\n    inputs = [\\n        *BaseFileComponent.get_base_inputs(),\\n        SecretStrInput(\\n            name=\\\"access_token\\\",\\n            display_name=\\\"AI Studio Access Token\\\",\\n            required=True,\\n            info=\\\"AI Studio access token. Get it from https://aistudio.baidu.com/account/accessToken.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Base URL\\\",\\n            required=False,\\n            value=\\\"\\\",\\n            info=\\\"Optional PaddleOCR service root URL. Leave empty to use the official default service.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"task_type\\\",\\n            display_name=\\\"Task Type\\\",\\n            options=[\\\"document_parsing\\\", \\\"ocr\\\"],\\n            value=\\\"document_parsing\\\",\\n            info=(\\n                \\\"document_parsing: preserves reading order and layout as Markdown \u2014 \\\"\\n                \\\"best when you need structure-aware text (PDFs, scanned documents, tables).\\\\n\\\"\\n                \\\"ocr: extracts text regions in scan order \u2014 best for images with simple text content.\\\"\\n            ),\\n            real_time_refresh=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            options=[\\\"PP-StructureV3\\\", \\\"PaddleOCR-VL-1.6\\\"],\\n            value=\\\"PP-StructureV3\\\",\\n            info=\\\"PaddleOCR model to use for the selected task type.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"poll_timeout\\\",\\n            display_name=\\\"Timeout (s)\\\",\\n            value=600,\\n            info=\\\"Maximum time to wait for the PaddleOCR job to complete.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"use_doc_orientation_classify\\\",\\n            display_name=\\\"Document Orientation Classification\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"OCR/document parsing option. Enable document orientation classification.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_doc_unwarping\\\",\\n            display_name=\\\"Document Unwarping\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"OCR/document parsing option. Enable document unwarping.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_textline_orientation\\\",\\n            display_name=\\\"Text Line Orientation\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"OCR option. Enable text line orientation detection.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"text_det_thresh\\\",\\n            display_name=\\\"Text Detection Threshold\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"OCR option. Text detection threshold.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"text_det_box_thresh\\\",\\n            display_name=\\\"Text Detection Box Threshold\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"OCR option. Text detection box threshold.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"text_det_unclip_ratio\\\",\\n            display_name=\\\"Text Detection Unclip Ratio\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"OCR option. Text detection unclip ratio.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"text_rec_score_thresh\\\",\\n            display_name=\\\"Text Recognition Score Threshold\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"OCR option. Text recognition score threshold.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_table_recognition\\\",\\n            display_name=\\\"Table Recognition\\\",\\n            value=True,\\n            advanced=True,\\n            info=\\\"Document parsing option. Enable table recognition.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_formula_recognition\\\",\\n            display_name=\\\"Formula Recognition\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"Document parsing option. Enable formula recognition.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_chart_recognition\\\",\\n            display_name=\\\"Chart Recognition\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"Document parsing option. Enable chart recognition.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"use_seal_recognition\\\",\\n            display_name=\\\"Seal Recognition\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"Document parsing option. Enable seal recognition.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"prettify_markdown\\\",\\n            display_name=\\\"Prettify Markdown\\\",\\n            value=True,\\n            advanced=True,\\n            info=\\\"Document parsing option. Return prettier Markdown when supported.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"PaddleOCR-VL option. Sampling temperature.\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"top_p\\\",\\n            display_name=\\\"Top P\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"PaddleOCR-VL option. Nucleus sampling top_p.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"visualize\\\",\\n            display_name=\\\"Visualize\\\",\\n            value=False,\\n            advanced=True,\\n            info=\\\"Document parsing option. Generate visualization outputs when supported.\\\",\\n        ),\\n    ]\\n\\n    outputs = [*BaseFileComponent.get_base_outputs()]\\n\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name == \\\"task_type\\\":\\n            if field_value == \\\"ocr\\\":\\n                build_config[\\\"model\\\"][\\\"options\\\"] = [\\\"PP-OCRv6\\\", \\\"PP-OCRv5\\\"]\\n                build_config[\\\"model\\\"][\\\"value\\\"] = \\\"PP-OCRv6\\\"\\n            else:\\n                build_config[\\\"model\\\"][\\\"options\\\"] = [\\\"PP-StructureV3\\\", \\\"PaddleOCR-VL-1.6\\\"]\\n                build_config[\\\"model\\\"][\\\"value\\\"] = \\\"PP-StructureV3\\\"\\n\\n        return build_config\\n\\n    def process_files(self, file_list: list[BaseFileComponent.BaseFile]) -> list[BaseFileComponent.BaseFile]:\\n        if not file_list:\\n            self.log(\\\"No files to process.\\\")\\n            return file_list\\n\\n        access_token = str(self.access_token or \\\"\\\").strip()\\n        if not access_token:\\n            msg = \\\"AI Studio Access Token is required.\\\"\\n            raise ValueError(msg)\\n\\n        base_url = (str(self.base_url or \\\"\\\").strip() or self.DEFAULT_BASE_URL).rstrip(\\\"/\\\")\\n        headers = {\\n            \\\"Authorization\\\": f\\\"Bearer {access_token}\\\",\\n            \\\"Client-Platform\\\": \\\"langflow\\\",\\n        }\\n        poll_timeout = int(self.poll_timeout or 600)\\n\\n        # ``base_url`` is configured by the flow author (a self-hosted PaddleOCR\\n        # service on localhost is a legitimate deployment), so the submit and\\n        # poll requests (which carry the bearer token and the uploaded file)\\n        # follow the connector SSRF policy: a literal loopback host is allowed\\n        # by default (``connector_ssrf_allow_loopback``) while RFC1918 /\\n        # link-local / cloud-metadata targets stay blocked; non-exempt hosts\\n        # are DNS-pinned for the rest of the run.  ``result_url`` in\\n        # ``_fetch_result`` comes from the remote response instead and keeps\\n        # the strict validator.\\n        _validated_url, base_ips = validate_and_resolve_connector_url(base_url)\\n\\n        try:\\n            for file in file_list:\\n                file.data = self._process_file(file.path, base_url, base_ips, headers, poll_timeout)\\n        except Exception as e:\\n            error_message = self._format_paddleocr_error(e)\\n            self.log(error_message)\\n            raise RuntimeError(error_message) from e\\n\\n        return file_list\\n\\n    def _process_file(\\n        self, file_path: Path, base_url: str, base_ips: list[str], headers: dict[str, str], poll_timeout: int\\n    ) -> Data:\\n        options = self._build_ocr_options() if self.task_type == \\\"ocr\\\" else self._build_document_parsing_options()\\n        job_id = self._submit_job(\\n            base_url=base_url, base_ips=base_ips, headers=headers, file_path=file_path, options=options\\n        )\\n        jsonl_data = self._poll_job(\\n            base_url=base_url, base_ips=base_ips, headers=headers, job_id=job_id, poll_timeout=poll_timeout\\n        )\\n\\n        if self.task_type == \\\"ocr\\\":\\n            return self._ocr_result_to_data(job_id, jsonl_data, file_path)\\n        return self._document_result_to_data(job_id, jsonl_data, file_path)\\n\\n    def _submit_job(\\n        self, *, base_url: str, base_ips: list[str], headers: dict[str, str], file_path: Path, options: dict[str, Any]\\n    ) -> str:\\n        url = f\\\"{base_url}{self.API_PATH}\\\"\\n        data = {\\\"model\\\": self.model, \\\"optionalPayload\\\": json.dumps(options)}\\n        with (\\n            file_path.open(\\\"rb\\\") as file_obj,\\n            self._build_client(url, base_ips) as client,\\n        ):\\n            response = client.post(\\n                url,\\n                data=data,\\n                files={\\\"file\\\": (file_path.name, file_obj)},\\n                headers=headers,\\n                timeout=self.REQUEST_TIMEOUT,\\n            )\\n        response.raise_for_status()\\n        payload = response.json()\\n        job_id = (payload.get(\\\"data\\\") or {}).get(\\\"jobId\\\") or payload.get(\\\"jobId\\\")\\n        if not job_id:\\n            msg = f\\\"PaddleOCR job ID not found in response: {payload}\\\"\\n            raise ValueError(msg)\\n        return job_id\\n\\n    def _poll_job(\\n        self,\\n        *,\\n        base_url: str,\\n        base_ips: list[str],\\n        headers: dict[str, str],\\n        job_id: str,\\n        poll_timeout: int,\\n    ) -> list[dict[str, Any]]:\\n        status_url = f\\\"{base_url}{self.API_PATH}/{job_id}\\\"\\n        deadline = time.monotonic() + poll_timeout\\n        interval = self.INITIAL_POLL_INTERVAL\\n\\n        with self._build_client(status_url, base_ips) as client:\\n            while True:\\n                remaining = deadline - time.monotonic()\\n                if remaining <= 0:\\n                    msg = f\\\"PaddleOCR job {job_id} timed out.\\\"\\n                    raise TimeoutError(msg)\\n\\n                # Bound each request by the remaining budget so a hung poll cannot\\n                # overrun ``poll_timeout`` by up to ``REQUEST_TIMEOUT``.\\n                response = client.get(status_url, headers=headers, timeout=min(self.REQUEST_TIMEOUT, remaining))\\n                response.raise_for_status()\\n                payload = response.json()\\n                data = payload.get(\\\"data\\\") or {}\\n                state = data.get(\\\"state\\\") or payload.get(\\\"state\\\")\\n\\n                if state == \\\"done\\\":\\n                    result_url = data.get(\\\"resultJsonUrl\\\") or (data.get(\\\"resultUrl\\\") or {}).get(\\\"jsonUrl\\\")\\n                    if not result_url:\\n                        msg = f\\\"PaddleOCR result URL not found in response: {payload}\\\"\\n                        raise ValueError(msg)\\n                    return self._fetch_result(result_url)\\n\\n                if state == \\\"failed\\\":\\n                    msg = f\\\"PaddleOCR job failed: {payload}\\\"\\n                    raise RuntimeError(msg)\\n\\n                time.sleep(min(interval, max(deadline - time.monotonic(), 0)))\\n                interval = min(interval * self.POLL_MULTIPLIER, self.MAX_POLL_INTERVAL)\\n\\n    def _fetch_result(self, result_url: str) -> list[dict[str, Any]]:\\n        # ``result_url`` comes from the remote job-status response, not from\\n        # operator input, so it is validated for SSRF before being fetched: a\\n        # compromised/rogue endpoint could otherwise point it at internal or\\n        # cloud-metadata addresses and have the worker fetch them server-side.\\n        # ``validate_and_resolve_url`` is a no-op (returns no pinned IPs) when\\n        # SSRF protection is disabled -- the default -- so behavior is unchanged\\n        # unless an operator opts in; when enabled it blocks internal targets\\n        # and pins DNS to the validated IPs.  This mirrors the shared pattern in\\n        # ``lfx.components.data_source.api_request``.\\n        _validated_url, validated_ips = validate_and_resolve_url(result_url)\\n        with self._build_client(result_url, validated_ips) as client:\\n            response = client.get(result_url)\\n        response.raise_for_status()\\n        text = response.text.strip()\\n        if not text:\\n            return []\\n\\n        try:\\n            payload = response.json()\\n        except ValueError:\\n            return [json.loads(line) for line in text.splitlines() if line.strip()]\\n\\n        if isinstance(payload, list):\\n            return payload\\n        if isinstance(payload, dict):\\n            return [payload]\\n        return []\\n\\n    def _build_client(self, url: str, validated_ips: list[str]) -> httpx.Client:\\n        \\\"\\\"\\\"Create the HTTP client for ``url``, pinning DNS when SSRF protection applies.\\n\\n        Used for the submit, poll, and result-fetch requests.  Returns a client\\n        that pins DNS to ``validated_ips`` (preventing rebinding) when SSRF\\n        protection is enabled and the host resolved to validated IPs; otherwise a\\n        standard client (protection disabled, allowlisted host, or hostname\\n        extraction failure).\\n        \\\"\\\"\\\"\\n        if is_ssrf_protection_enabled() and validated_ips:\\n            hostname = httpx.URL(url).host\\n            if hostname:\\n                return create_ssrf_protected_sync_client(\\n                    hostname=hostname, validated_ips=validated_ips, timeout=self.REQUEST_TIMEOUT\\n                )\\n        return httpx.Client(timeout=self.REQUEST_TIMEOUT)\\n\\n    def _build_ocr_options(self) -> dict[str, Any]:\\n        return self._collect_options(\\n            [\\n                \\\"use_doc_orientation_classify\\\",\\n                \\\"use_doc_unwarping\\\",\\n                \\\"use_textline_orientation\\\",\\n                \\\"text_det_thresh\\\",\\n                \\\"text_det_box_thresh\\\",\\n                \\\"text_det_unclip_ratio\\\",\\n                \\\"text_rec_score_thresh\\\",\\n            ]\\n        )\\n\\n    def _build_document_parsing_options(self) -> dict[str, Any]:\\n        return self._collect_options(\\n            [\\n                \\\"use_doc_orientation_classify\\\",\\n                \\\"use_doc_unwarping\\\",\\n                \\\"use_table_recognition\\\",\\n                \\\"use_formula_recognition\\\",\\n                \\\"use_chart_recognition\\\",\\n                \\\"use_seal_recognition\\\",\\n                \\\"prettify_markdown\\\",\\n                \\\"temperature\\\",\\n                \\\"top_p\\\",\\n                \\\"visualize\\\",\\n            ]\\n        )\\n\\n    def _collect_options(self, option_names: list[str]) -> dict[str, Any]:\\n        options: dict[str, Any] = {}\\n        for name in option_names:\\n            value = getattr(self, name, None)\\n            if value is not None:\\n                options[name] = value\\n        return options\\n\\n    def _ocr_result_to_data(self, job_id: str, jsonl_data: list[dict[str, Any]], file_path: Path) -> Data:\\n        pages_payload: list[dict[str, Any]] = []\\n        text_parts: list[str] = []\\n\\n        for line_obj in jsonl_data:\\n            result = line_obj.get(\\\"result\\\", line_obj)\\n            for item in result.get(\\\"ocrResults\\\", []) or []:\\n                pruned_result = item.get(\\\"prunedResult\\\", {}) or {}\\n                rec_texts = pruned_result.get(\\\"rec_texts\\\", []) or []\\n                if rec_texts:\\n                    text_parts.append(\\\"\\\\n\\\".join(str(text) for text in rec_texts))\\n                pages_payload.append(\\n                    {\\n                        \\\"pruned_result\\\": pruned_result,\\n                        \\\"ocr_image_url\\\": item.get(\\\"ocrImage\\\"),\\n                    }\\n                )\\n\\n        text = \\\"\\\\n\\\\n\\\".join(part for part in text_parts if part)\\n        return Data(\\n            text=text,\\n            data={\\n                self.SERVER_FILE_PATH_FIELDNAME: str(file_path),\\n                \\\"text\\\": text,\\n                \\\"task_type\\\": \\\"ocr\\\",\\n                \\\"output_format\\\": \\\"plain_text\\\",\\n                \\\"model\\\": self.model,\\n                \\\"job_id\\\": job_id,\\n                \\\"pages\\\": pages_payload,\\n            },\\n        )\\n\\n    def _document_result_to_data(self, job_id: str, jsonl_data: list[dict[str, Any]], file_path: Path) -> Data:\\n        pages_payload: list[dict[str, Any]] = []\\n        text_parts: list[str] = []\\n\\n        for line_obj in jsonl_data:\\n            result = line_obj.get(\\\"result\\\", line_obj)\\n            layout_results = result.get(\\\"layoutParsingResults\\\", []) or []\\n            if layout_results:\\n                self._append_layout_results(layout_results, pages_payload, text_parts)\\n                continue\\n            self._append_ocr_fallback_results(result.get(\\\"ocrResults\\\", []) or [], pages_payload, text_parts)\\n\\n        markdown_text = \\\"\\\\n\\\\n\\\".join(part for part in text_parts if part)\\n        return Data(\\n            text=markdown_text,\\n            data={\\n                self.SERVER_FILE_PATH_FIELDNAME: str(file_path),\\n                \\\"text\\\": markdown_text,\\n                \\\"task_type\\\": \\\"document_parsing\\\",\\n                \\\"output_format\\\": \\\"markdown\\\",\\n                \\\"model\\\": self.model,\\n                \\\"job_id\\\": job_id,\\n                \\\"pages\\\": pages_payload,\\n            },\\n        )\\n\\n    def _append_layout_results(\\n        self,\\n        layout_results: list[dict[str, Any]],\\n        pages_payload: list[dict[str, Any]],\\n        text_parts: list[str],\\n    ) -> None:\\n        for item in layout_results:\\n            markdown = item.get(\\\"markdown\\\", {}) or {}\\n            markdown_text = markdown.get(\\\"text\\\") or item.get(\\\"markdown_text\\\") or \\\"\\\"\\n            if markdown_text:\\n                text_parts.append(str(markdown_text))\\n            pages_payload.append(\\n                {\\n                    \\\"markdown_text\\\": markdown_text,\\n                    \\\"markdown_images\\\": markdown.get(\\\"images\\\", {}) or {},\\n                    \\\"output_images\\\": item.get(\\\"outputImages\\\", {}) or {},\\n                }\\n            )\\n\\n    def _append_ocr_fallback_results(\\n        self,\\n        ocr_results: list[dict[str, Any]],\\n        pages_payload: list[dict[str, Any]],\\n        text_parts: list[str],\\n    ) -> None:\\n        for item in ocr_results:\\n            pruned_result = item.get(\\\"prunedResult\\\", {}) or {}\\n            rec_texts = pruned_result.get(\\\"rec_texts\\\", []) or []\\n            text = \\\"\\\\n\\\".join(str(text) for text in rec_texts)\\n            if text:\\n                text_parts.append(text)\\n            pages_payload.append(\\n                {\\n                    \\\"markdown_text\\\": text,\\n                    \\\"markdown_images\\\": {},\\n                    \\\"output_images\\\": {},\\n                    \\\"pruned_result\\\": pruned_result,\\n                    \\\"ocr_image_url\\\": item.get(\\\"ocrImage\\\"),\\n                }\\n            )\\n\\n    def _format_paddleocr_error(self, error: Exception) -> str:\\n        if isinstance(error, httpx.HTTPStatusError):\\n            status_code = error.response.status_code\\n            if status_code in {401, 403}:\\n                return \\\"PaddleOCR authentication failed. Please check the AI Studio Access Token.\\\"\\n            return f\\\"PaddleOCR API error ({status_code}): {error.response.text}\\\"\\n        if isinstance(error, httpx.TimeoutException | TimeoutError):\\n            return \\\"PaddleOCR job timed out. Increase the timeout or try again later.\\\"\\n        if isinstance(error, httpx.HTTPError):\\n            return f\\\"PaddleOCR network error: {error}\\\"\\n        return f\\\"PaddleOCR failed: {error}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/src/lfx_paddle/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fdc822fe3ed8a12dc29ca63c8d1f884d7505fc5789a78abb526e3c806df56825\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-paddle\\\",\\n  \\\"version\\\": \\\"0.1.4\\\",\\n  \\\"name\\\": \\\"PaddleOCR\\\",\\n  \\\"description\\\": \\\"PaddleOCR component (OCR and layout-aware document parsing via the AI Studio async Job API) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"paddle\\\",\\n      \\\"path\\\": \\\"components/paddle\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/paddle/tests/test_paddleocr_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"120615b61b9611908fcd953e6853f45c3b55897148f3ad5e9c310d686f5e143c\",\"content\":\"\\\"\\\"\\\"Unit tests for the PaddleOCR extension bundle (``lfx-paddle``).\\n\\nThe component previously lived at ``lfx.components.baidu.paddleocr`` on the\\ncontributor branch; it now ships as a standalone bundle, so these tests travel\\nwith the bundle and import the public bundle entry point. They exercise the\\nserver-free surface (OCR / document-parsing result shaping, the\\ndocument-parsing OCR fallback, access-token validation, auth-error formatting,\\nand the task-type model-option switch) with ``_submit_job`` / ``_poll_job``\\nmonkeypatched -- no network access or PaddleOCR service is required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport httpx\\nimport pytest\\nfrom lfx.base.data.base_file import BaseFileComponent\\nfrom lfx.schema.data import Data\\nfrom lfx_paddle import PaddleOCRComponent\\n\\n\\ndef make_base_file(path):\\n    return BaseFileComponent.BaseFile(Data(data={\\\"file_path\\\": str(path)}), path)\\n\\n\\ndef test_bundle_entrypoint_export():\\n    assert PaddleOCRComponent.__name__ == \\\"PaddleOCRComponent\\\"\\n    assert PaddleOCRComponent.name == \\\"PaddleOCR\\\"\\n\\n\\ndef test_paddleocr_ocr_mode_processes_text(monkeypatch, tmp_path):\\n    file_path = tmp_path / \\\"sample.png\\\"\\n    file_path.write_bytes(b\\\"fake image\\\")\\n\\n    captured = {}\\n\\n    def fake_submit(_self, *, base_url, base_ips, headers, file_path, options):\\n        captured[\\\"submit\\\"] = {\\n            \\\"base_url\\\": base_url,\\n            \\\"base_ips\\\": base_ips,\\n            \\\"headers\\\": headers,\\n            \\\"file_path\\\": file_path,\\n            \\\"options\\\": options,\\n        }\\n        return \\\"ocr-job-id\\\"\\n\\n    def fake_poll(_self, *, base_url, base_ips, headers, job_id, poll_timeout):\\n        captured[\\\"poll\\\"] = {\\n            \\\"base_url\\\": base_url,\\n            \\\"base_ips\\\": base_ips,\\n            \\\"headers\\\": headers,\\n            \\\"job_id\\\": job_id,\\n            \\\"poll_timeout\\\": poll_timeout,\\n        }\\n        return [\\n            {\\n                \\\"result\\\": {\\n                    \\\"ocrResults\\\": [\\n                        {\\n                            \\\"prunedResult\\\": {\\\"rec_texts\\\": [\\\"hello\\\", \\\"world\\\"]},\\n                            \\\"ocrImage\\\": \\\"https://example.com/ocr.png\\\",\\n                        }\\n                    ]\\n                }\\n            }\\n        ]\\n\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_submit_job\\\", fake_submit)\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_poll_job\\\", fake_poll)\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes(\\n        {\\n            \\\"access_token\\\": \\\"token\\\",\\n            \\\"base_url\\\": \\\"\\\",\\n            \\\"task_type\\\": \\\"ocr\\\",\\n            \\\"model\\\": \\\"PP-OCRv6\\\",\\n            \\\"poll_timeout\\\": 123,\\n            \\\"use_doc_orientation_classify\\\": False,\\n            \\\"use_doc_unwarping\\\": False,\\n            \\\"use_textline_orientation\\\": False,\\n        }\\n    )\\n\\n    processed = component.process_files([make_base_file(file_path)])\\n\\n    data = processed[0].data[0].data\\n    assert data[\\\"text\\\"] == \\\"hello\\\\nworld\\\"\\n    assert data[\\\"task_type\\\"] == \\\"ocr\\\"\\n    assert data[\\\"output_format\\\"] == \\\"plain_text\\\"\\n    assert data[\\\"model\\\"] == \\\"PP-OCRv6\\\"\\n    assert data[\\\"job_id\\\"] == \\\"ocr-job-id\\\"\\n    assert data[\\\"pages\\\"][0][\\\"pruned_result\\\"] == {\\\"rec_texts\\\": [\\\"hello\\\", \\\"world\\\"]}\\n\\n    assert captured[\\\"submit\\\"][\\\"base_url\\\"] == PaddleOCRComponent.DEFAULT_BASE_URL\\n    assert captured[\\\"submit\\\"][\\\"headers\\\"] == {\\n        \\\"Authorization\\\": \\\"Bearer token\\\",\\n        \\\"Client-Platform\\\": \\\"langflow\\\",\\n    }\\n    assert captured[\\\"submit\\\"][\\\"file_path\\\"] == file_path\\n    assert captured[\\\"submit\\\"][\\\"options\\\"][\\\"use_doc_orientation_classify\\\"] is False\\n    assert captured[\\\"poll\\\"][\\\"poll_timeout\\\"] == 123\\n\\n\\ndef test_paddleocr_document_parsing_processes_markdown(monkeypatch, tmp_path):\\n    file_path = tmp_path / \\\"sample.pdf\\\"\\n    file_path.write_bytes(b\\\"fake pdf\\\")\\n\\n    captured = {}\\n\\n    def fake_submit(_self, *, base_url, base_ips, headers, file_path, options):\\n        captured[\\\"submit\\\"] = {\\n            \\\"base_url\\\": base_url,\\n            \\\"base_ips\\\": base_ips,\\n            \\\"headers\\\": headers,\\n            \\\"file_path\\\": file_path,\\n            \\\"options\\\": options,\\n        }\\n        return \\\"doc-job-id\\\"\\n\\n    def fake_poll(_self, **_kwargs):\\n        return [\\n            {\\n                \\\"result\\\": {\\n                    \\\"layoutParsingResults\\\": [\\n                        {\\n                            \\\"markdown\\\": {\\n                                \\\"text\\\": \\\"# Title\\\",\\n                                \\\"images\\\": {\\\"image.png\\\": \\\"https://example.com/image.png\\\"},\\n                            },\\n                            \\\"outputImages\\\": {},\\n                        }\\n                    ]\\n                }\\n            }\\n        ]\\n\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_submit_job\\\", fake_submit)\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_poll_job\\\", fake_poll)\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes(\\n        {\\n            \\\"access_token\\\": \\\"token\\\",\\n            \\\"base_url\\\": \\\"https://example.com/\\\",\\n            \\\"task_type\\\": \\\"document_parsing\\\",\\n            \\\"model\\\": \\\"PaddleOCR-VL-1.6\\\",\\n            \\\"poll_timeout\\\": 600,\\n            \\\"use_doc_orientation_classify\\\": False,\\n            \\\"use_doc_unwarping\\\": False,\\n            \\\"use_table_recognition\\\": True,\\n            \\\"use_formula_recognition\\\": False,\\n            \\\"use_chart_recognition\\\": False,\\n            \\\"use_seal_recognition\\\": False,\\n            \\\"prettify_markdown\\\": True,\\n            \\\"visualize\\\": False,\\n        }\\n    )\\n\\n    processed = component.process_files([make_base_file(file_path)])\\n\\n    data = processed[0].data[0].data\\n    assert data[\\\"text\\\"] == \\\"# Title\\\"\\n    assert data[\\\"task_type\\\"] == \\\"document_parsing\\\"\\n    assert data[\\\"output_format\\\"] == \\\"markdown\\\"\\n    assert data[\\\"model\\\"] == \\\"PaddleOCR-VL-1.6\\\"\\n    assert data[\\\"job_id\\\"] == \\\"doc-job-id\\\"\\n    assert data[\\\"pages\\\"][0][\\\"markdown_text\\\"] == \\\"# Title\\\"\\n    assert data[\\\"pages\\\"][0][\\\"markdown_images\\\"] == {\\\"image.png\\\": \\\"https://example.com/image.png\\\"}\\n\\n    assert captured[\\\"submit\\\"][\\\"base_url\\\"] == \\\"https://example.com\\\"\\n    assert captured[\\\"submit\\\"][\\\"file_path\\\"] == file_path\\n    assert captured[\\\"submit\\\"][\\\"options\\\"][\\\"use_table_recognition\\\"] is True\\n\\n\\ndef test_paddleocr_document_parsing_falls_back_to_ocr_results(tmp_path):\\n    file_path = tmp_path / \\\"sample.pdf\\\"\\n    file_path.write_bytes(b\\\"fake pdf\\\")\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes({\\\"task_type\\\": \\\"document_parsing\\\", \\\"model\\\": \\\"PP-OCRv6\\\"})\\n\\n    data = component._document_result_to_data(\\n        \\\"job-id\\\",\\n        [\\n            {\\n                \\\"result\\\": {\\n                    \\\"ocrResults\\\": [\\n                        {\\n                            \\\"prunedResult\\\": {\\\"rec_texts\\\": [\\\"fallback\\\", \\\"text\\\"]},\\n                            \\\"ocrImage\\\": \\\"https://example.com/ocr.png\\\",\\n                        }\\n                    ]\\n                }\\n            }\\n        ],\\n        file_path,\\n    ).data\\n\\n    assert data[\\\"text\\\"] == \\\"fallback\\\\ntext\\\"\\n    assert data[\\\"pages\\\"][0][\\\"pruned_result\\\"] == {\\\"rec_texts\\\": [\\\"fallback\\\", \\\"text\\\"]}\\n\\n\\ndef test_paddleocr_requires_access_token(tmp_path):\\n    file_path = tmp_path / \\\"sample.png\\\"\\n    file_path.write_bytes(b\\\"fake image\\\")\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes({\\\"access_token\\\": \\\"\\\", \\\"task_type\\\": \\\"ocr\\\", \\\"model\\\": \\\"PP-OCRv6\\\"})\\n\\n    with pytest.raises(ValueError, match=\\\"Access Token is required\\\"):\\n        component.process_files([make_base_file(file_path)])\\n\\n\\ndef test_paddleocr_formats_auth_error():\\n    component = PaddleOCRComponent()\\n    request = httpx.Request(\\\"GET\\\", \\\"https://example.com\\\")\\n    response = httpx.Response(401, request=request, text=\\\"unauthorized\\\")\\n    error = httpx.HTTPStatusError(\\\"unauthorized\\\", request=request, response=response)\\n\\n    assert component._format_paddleocr_error(error) == (\\n        \\\"PaddleOCR authentication failed. Please check the AI Studio Access Token.\\\"\\n    )\\n\\n\\ndef test_build_client_is_plain_when_ssrf_disabled():\\n    # SSRF protection is off by default, so requests use a standard client\\n    # (no DNS pinning) and behavior matches the pre-hardening port.\\n    component = PaddleOCRComponent()\\n    client = component._build_client(\\\"https://example.com/result.json\\\", [])\\n    try:\\n        assert isinstance(client, httpx.Client)\\n    finally:\\n        client.close()\\n\\n\\ndef test_build_client_pins_dns_when_ssrf_enabled(monkeypatch):\\n    # When SSRF protection is enabled and the host resolved to validated IPs,\\n    # the request goes through the DNS-pinned protected client.\\n    import lfx_paddle.components.paddle.paddleocr as mod\\n\\n    sentinel = httpx.Client()\\n    captured = {}\\n\\n    def fake_protected_client(*, hostname, validated_ips, **_kwargs):\\n        captured[\\\"hostname\\\"] = hostname\\n        captured[\\\"validated_ips\\\"] = validated_ips\\n        return sentinel\\n\\n    monkeypatch.setattr(mod, \\\"is_ssrf_protection_enabled\\\", lambda: True)\\n    monkeypatch.setattr(mod, \\\"create_ssrf_protected_sync_client\\\", fake_protected_client)\\n\\n    component = PaddleOCRComponent()\\n    try:\\n        client = component._build_client(\\\"https://example.com/result.json\\\", [\\\"93.184.216.34\\\"])\\n        assert client is sentinel\\n        assert captured[\\\"hostname\\\"] == \\\"example.com\\\"\\n        assert captured[\\\"validated_ips\\\"] == [\\\"93.184.216.34\\\"]\\n    finally:\\n        sentinel.close()\\n\\n\\ndef test_fetch_result_blocks_internal_url_when_ssrf_enabled(monkeypatch):\\n    # An internal/metadata result URL is rejected before any request is made\\n    # when SSRF protection is enabled.\\n    import lfx_paddle.components.paddle.paddleocr as mod\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    def fake_validate(url):\\n        msg = f\\\"Access to {url} is blocked by SSRF protection\\\"\\n        raise SSRFProtectionError(msg)\\n\\n    monkeypatch.setattr(mod, \\\"validate_and_resolve_url\\\", fake_validate)\\n\\n    component = PaddleOCRComponent()\\n    with pytest.raises(SSRFProtectionError):\\n        component._fetch_result(\\\"http://169.254.169.254/latest/meta-data/\\\")\\n\\n\\ndef test_paddleocr_loopback_base_url_allowed_by_default(monkeypatch, tmp_path):\\n    # SSRF protection on, no allowlist: a self-hosted PaddleOCR service on\\n    # localhost passes the connector policy (literal-loopback exemption), so\\n    # processing proceeds to the (stubbed) submit/poll calls. Regression guard\\n    # for the #14264 family (local services blocked at loopback by the raw\\n    # validator).\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n    monkeypatch.delenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", raising=False)\\n\\n    file_path = tmp_path / \\\"sample.png\\\"\\n    file_path.write_bytes(b\\\"fake image\\\")\\n\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_submit_job\\\", lambda _self, **_kwargs: \\\"job-id\\\")\\n    monkeypatch.setattr(\\n        PaddleOCRComponent,\\n        \\\"_poll_job\\\",\\n        lambda _self, **_kwargs: [{\\\"result\\\": {\\\"ocrResults\\\": [{\\\"prunedResult\\\": {\\\"rec_texts\\\": [\\\"ok\\\"]}}]}}],\\n    )\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes(\\n        {\\n            \\\"access_token\\\": \\\"token\\\",\\n            \\\"base_url\\\": \\\"http://127.0.0.1:8868\\\",\\n            \\\"task_type\\\": \\\"ocr\\\",\\n            \\\"model\\\": \\\"PP-OCRv6\\\",\\n            \\\"poll_timeout\\\": 60,\\n        }\\n    )\\n    result = component.process_files([make_base_file(file_path)])\\n    assert result[0].data[0].data[\\\"text\\\"] == \\\"ok\\\"\\n\\n\\ndef test_paddleocr_loopback_base_url_blocked_when_connector_loopback_disabled(monkeypatch, tmp_path):\\n    # Multi-tenant posture: connector_ssrf_allow_loopback=false blocks the\\n    # loopback base_url before any request is made.\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", \\\"false\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n    file_path = tmp_path / \\\"sample.png\\\"\\n    file_path.write_bytes(b\\\"fake image\\\")\\n\\n    component = PaddleOCRComponent()\\n    component.set_attributes(\\n        {\\n            \\\"access_token\\\": \\\"token\\\",\\n            \\\"base_url\\\": \\\"http://127.0.0.1:8868\\\",\\n            \\\"task_type\\\": \\\"ocr\\\",\\n            \\\"model\\\": \\\"PP-OCRv6\\\",\\n            \\\"poll_timeout\\\": 60,\\n        }\\n    )\\n    with pytest.raises(SSRFProtectionError, match=\\\"blocked\\\"):\\n        component.process_files([make_base_file(file_path)])\\n\\n\\ndef test_fetch_result_parses_json_list(monkeypatch):\\n    component = PaddleOCRComponent()\\n\\n    def handler(_request):\\n        return httpx.Response(200, json=[{\\\"x\\\": 1}])\\n\\n    def fake_build_client(_self, _url, _ips):\\n        return httpx.Client(transport=httpx.MockTransport(handler))\\n\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_build_client\\\", fake_build_client)\\n    assert component._fetch_result(\\\"https://example.com/result.json\\\") == [{\\\"x\\\": 1}]\\n\\n\\ndef test_fetch_result_parses_jsonl_fallback(monkeypatch):\\n    component = PaddleOCRComponent()\\n\\n    def handler(_request):\\n        return httpx.Response(200, text='{\\\"a\\\": 1}\\\\n{\\\"b\\\": 2}\\\\n')\\n\\n    def fake_build_client(_self, _url, _ips):\\n        return httpx.Client(transport=httpx.MockTransport(handler))\\n\\n    monkeypatch.setattr(PaddleOCRComponent, \\\"_build_client\\\", fake_build_client)\\n    assert component._fetch_result(\\\"https://example.com/result.jsonl\\\") == [{\\\"a\\\": 1}, {\\\"b\\\": 2}]\\n\\n\\ndef test_task_type_updates_model_options():\\n    component = PaddleOCRComponent()\\n    build_config = {\\n        \\\"model\\\": {\\\"options\\\": [\\\"PP-StructureV3\\\", \\\"PaddleOCR-VL-1.6\\\"], \\\"value\\\": \\\"PP-StructureV3\\\"},\\n    }\\n\\n    updated = component.update_build_config(build_config, \\\"ocr\\\", \\\"task_type\\\")\\n    assert updated[\\\"model\\\"][\\\"options\\\"] == [\\\"PP-OCRv6\\\", \\\"PP-OCRv5\\\"]\\n    assert updated[\\\"model\\\"][\\\"value\\\"] == \\\"PP-OCRv6\\\"\\n\\n    updated = component.update_build_config(build_config, \\\"document_parsing\\\", \\\"task_type\\\")\\n    assert updated[\\\"model\\\"][\\\"options\\\"] == [\\\"PP-StructureV3\\\", \\\"PaddleOCR-VL-1.6\\\"]\\n    assert updated[\\\"model\\\"][\\\"value\\\"] == \\\"PP-StructureV3\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"666f0f62bd3f1bc9431ed32b5fc62c535c6b79531e4a54fa73da68f8c4c0bb83\",\"content\":\"# lfx-toolguard\\n\\n`lfx-toolguard` is the standalone Langflow extension that provides the\\n`PoliciesComponent` and its ToolGuard runtime integration.\\n\\nIt is installed by the full `langflow` distribution. Users of `lfx` or\\n`langflow-base` can opt in with the compatibility extras:\\n\\n```bash\\nuv pip install \\\"lfx[toolguard]\\\"\\nuv pip install \\\"langflow-base[toolguard]\\\"\\n```\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a014262a48298eb2ffbf2d4eea3d11791fb91c6bfc7432e8dc206d4ae64a595f\",\"content\":\"[project]\\nname = \\\"lfx-toolguard\\\"\\nversion = \\\"0.1.2\\\"\\ndescription = \\\"Langflow Policies component powered by ToolGuard.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"policies\\\", \\\"toolguard\\\"]\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"toolguard>=0.2.20,<1.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-toolguard = \\\"lfx_toolguard\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"src/lfx_toolguard\\\"]\\ninclude = [\\n    \\\"src/lfx_toolguard/extension.json\\\",\\n    \\\"src/lfx_toolguard/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_toolguard\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aab786b4dcd94ae17a93b3289c6b4e0605ca6fd84bb686643274c53568ec6dbb\",\"content\":\"\\\"\\\"\\\"ToolGuard-powered Policies extension for Langflow.\\\"\\\"\\\"\\n\\nfrom lfx_toolguard.components.models_and_agents import PoliciesComponent\\n\\n__all__ = [\\\"PoliciesComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"581134c2210d386cbe6a452982eec222deb1634aab955e53a98dfaaaa63c678f\",\"content\":\"\\\"\\\"\\\"Component packages shipped by lfx-toolguard.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e9d90458cf9dba518d2d45ef10c9a8bc4097c7d93f5c21896059725bda8b03f9\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from .policies_component import PoliciesComponent\\n\\n__all__ = [\\\"PoliciesComponent\\\"]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in __all__:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    result = import_mod(attr_name, \\\"policies_component\\\", __spec__.parent)\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0a5f75f0361934c08436a992daf37d2a3acd13d6f4294facb0a2056f46ff533d\",\"content\":\"# Supporting utilities for the ToolGuard Policies extension.\\n\\n__all__ = []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/guard_sync_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c5cc73c1003e365af1e9ee73caf7767c67afcf78fbcfb55cf36fa01dad261917\",\"content\":\"\\\"\\\"\\\"Synchronize generated ToolGuard code with component inputs.\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nfrom lfx.io import CodeInput\\nfrom lfx.log.logger import logger\\nfrom toolguard.runtime.runtime import RESULTS_FILENAME\\n\\nGENERATED_GUARD_INFO_PREFIX = \\\"Auto-generated ToolGuard code for \\\"\\n\\n\\ndef is_generated_guard_field(field: dict) -> bool:\\n    \\\"\\\"\\\"Check if a field represents a generated guard code input.\\n\\n    Args:\\n        field: Dictionary representing a component field/input\\n\\n    Returns:\\n        True if the field is a generated guard code field, False otherwise\\n    \\\"\\\"\\\"\\n    if not isinstance(field, dict):\\n        return False\\n    return (\\n        field.get(\\\"type\\\") == \\\"code\\\"\\n        and field.get(\\\"dynamic\\\") is True\\n        and isinstance(field.get(\\\"info\\\"), str)\\n        and field.get(\\\"info\\\", \\\"\\\").startswith(GENERATED_GUARD_INFO_PREFIX)\\n    )\\n\\n\\ndef sync_generated_guard_code_inputs(\\n    build_config: dict,\\n    work_dir: Path,\\n    step2_subdir: str,\\n    project_name: str,\\n) -> dict:\\n    \\\"\\\"\\\"Synchronize generated guard code files with component code inputs.\\n\\n    Scans the generated guard code directory and creates/updates CodeInput fields\\n    in the build config for each Python file found. Removes stale fields for files\\n    that no longer exist when the directory is available; otherwise, preserves the\\n    generated fields already stored in the build config.\\n\\n    Args:\\n        build_config: The component's build configuration dictionary\\n        work_dir: Base working directory for the toolguard project\\n        step2_subdir: Subdirectory name containing generated code (e.g., \\\"Step_2\\\")\\n        project_name: Name of the project in snake_case format\\n\\n    Returns:\\n        Updated build_config dictionary with synchronized code inputs\\n    \\\"\\\"\\\"\\n    logger.debug(\\\"Syncing generated guard code files...\\\")\\n    generated_field_names = {key for key, value in build_config.items() if is_generated_guard_field(value)}\\n\\n    step2_dir = work_dir / step2_subdir\\n    logger.debug(f\\\"step2_dir = {step2_dir}\\\")\\n    logger.debug(f\\\"step2_dir.exists() = {step2_dir.exists()}\\\")\\n    logger.debug(f\\\"step2_dir.is_dir() = {step2_dir.is_dir()}\\\")\\n    if not step2_dir.exists() or not step2_dir.is_dir():\\n        return build_config\\n\\n    files = sorted(path for path in step2_dir.rglob(\\\"*\\\") if path.is_file())\\n\\n    def include_file(relative_name) -> bool:\\n        if relative_name.startswith(project_name) and relative_name.endswith(\\\".py\\\"):\\n            return True\\n        return relative_name == str(RESULTS_FILENAME)\\n\\n    next_generated_names: set[str] = set()\\n\\n    for file_path in files:\\n        relative_name = file_path.relative_to(step2_dir).as_posix()\\n        if not include_file(relative_name):\\n            continue\\n        logger.debug(f\\\"Processing generated file: {relative_name}\\\")\\n        next_generated_names.add(relative_name)\\n        try:\\n            code_value = file_path.read_text(encoding=\\\"utf-8\\\")\\n        except OSError:\\n            code_value = \\\"\\\"\\n\\n        code_input = CodeInput(\\n            name=relative_name,\\n            display_name=relative_name,\\n            value=code_value,\\n            info=f\\\"{GENERATED_GUARD_INFO_PREFIX}{relative_name}\\\",\\n            dynamic=True,\\n            advanced=True,\\n        )\\n        build_config[relative_name] = code_input.to_dict()\\n\\n    stale_field_names = generated_field_names - next_generated_names\\n    for field_name in stale_field_names:\\n        build_config.pop(field_name, None)\\n\\n    return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/guarded_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d100201a6d4ea7eb2d033653c7a6380a5a4c19f8a4f4cfc551e03243100055c7\",\"content\":\"from __future__ import annotations\\n\\nimport json\\nfrom collections.abc import Awaitable, Callable  # noqa: TC003\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.field_typing import Tool\\nfrom lfx.log.logger import logger\\nfrom pydantic import Field\\n\\nif TYPE_CHECKING:\\n    from langchain_core.messages import ToolCall\\n    from toolguard.runtime.runtime import ToolguardRuntime\\n\\n    from lfx_toolguard.components.models_and_agents.policies.tool_invoker import ToolInvoker\\n\\n\\ndef _is_policy_violation_exception(exc: Exception) -> bool:\\n    try:\\n        from toolguard.runtime import PolicyViolationException\\n    except ImportError:\\n        return False\\n\\n    return isinstance(exc, PolicyViolationException)\\n\\n\\nclass GuardedTool(Tool):\\n    \\\"\\\"\\\"A tool wrapper that applies ToolGuard policy validation before execution.\\n\\n    This component requires async execution as ToolGuard operates asynchronously.\\n    The synchronous `run()` method is not supported and will raise NotImplementedError.\\n    Always use `arun()` or async invocation methods.\\n    \\\"\\\"\\\"\\n\\n    _orig_tool: Tool\\n    _tool_invoker: ToolInvoker\\n    _toolguard: ToolguardRuntime\\n\\n    # These callables are bound to this instance, so including them in the model\\n    # representation would recursively render the GuardedTool itself.\\n    func: Callable[..., str] | None = Field(repr=False)\\n    coroutine: Callable[..., Awaitable[str]] | None = Field(default=None, repr=False)\\n\\n    def __init__(self, tool: Tool, all_tools: list[Tool], toolguard: ToolguardRuntime):\\n        from lfx_toolguard.components.models_and_agents.policies.tool_invoker import ToolInvoker\\n\\n        super().__init__(\\n            name=tool.name,\\n            description=tool.description,\\n            args_schema=getattr(tool, \\\"args_schema\\\", None),\\n            return_direct=getattr(tool, \\\"return_direct\\\", False),\\n            func=self.run,\\n            coroutine=self.arun,\\n            tags=tool.tags,\\n            metadata=tool.metadata,\\n            verbose=True,\\n        )\\n        self._orig_tool = tool\\n        self._tool_invoker = ToolInvoker(all_tools)\\n        self._toolguard = toolguard\\n\\n    @property\\n    def args(self) -> dict:\\n        return self._orig_tool.args\\n\\n    def _parse_string_to_dict(self, value: str) -> dict:\\n        \\\"\\\"\\\"Parse a string as JSON, or wrap it in a dict if parsing fails.\\\"\\\"\\\"\\n        try:\\n            return json.loads(value)\\n        except json.JSONDecodeError:\\n            return {\\\"input\\\": value}\\n\\n    def parse_input(self, tool_input: str | dict | ToolCall) -> dict:\\n        # Handle string input - try to parse as JSON, fallback to wrapped input\\n        if isinstance(tool_input, str):\\n            return self._parse_string_to_dict(tool_input)\\n\\n        # Handle ToolCall dict format - extract and parse args\\n        if isinstance(tool_input, dict) and \\\"args\\\" in tool_input:\\n            args = tool_input[\\\"args\\\"]\\n            if isinstance(args, str):\\n                return self._parse_string_to_dict(args)\\n            return args if isinstance(args, dict) else {}\\n\\n        # Return dict as-is or empty dict for None/other types\\n        return tool_input if isinstance(tool_input, dict) else {}\\n\\n    def run(self, tool_input: str | dict | ToolCall, config=None, **kwargs):\\n        \\\"\\\"\\\"Synchronous execution is not supported for GuardedTool.\\n\\n        ToolGuard requires async execution for policy validation. Please use the\\n        async version `arun()` instead, or ensure your execution context supports\\n        async tool invocation.\\n\\n        Raises:\\n            NotImplementedError: Always raised as sync execution is not supported.\\n        \\\"\\\"\\\"\\n        msg = (\\n            \\\"GuardedTool does not support synchronous execution. \\\"\\n            \\\"ToolGuard requires async execution for policy validation. \\\"\\n            \\\"Please use `arun()` instead or ensure your execution context supports async tool invocation.\\\"\\n        )\\n        raise NotImplementedError(msg)\\n\\n    async def arun(self, tool_input: str | dict | ToolCall, config=None, **kwargs):\\n        args = self.parse_input(tool_input)\\n        logger.debug(f\\\"running toolguard for {self.name}\\\")\\n\\n        with self._toolguard:\\n            try:\\n                await self._toolguard.guard_toolcall(self.name, args=args, delegate=self._tool_invoker)\\n                return await self._orig_tool.arun(tool_input=args, config=config, **kwargs)\\n            except Exception as ex:\\n                if not _is_policy_violation_exception(ex):\\n                    logger.exception(\\\"Unhandled exception in class GuardedTool.arun()\\\")\\n                    raise\\n\\n                message = getattr(ex, \\\"message\\\", str(ex))\\n                logger.debug(f\\\"exception: {message}\\\")\\n                return {\\n                    \\\"ok\\\": False,\\n                    \\\"error\\\": {\\n                        \\\"type\\\": \\\"PolicyViolationException\\\",\\n                        \\\"code\\\": \\\"FAILURE\\\",\\n                        \\\"message\\\": message,\\n                        \\\"retryable\\\": True,\\n                    },\\n                }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/llm_wrapper.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f6f6d86476c2817cc1b3608f48b39b6de6e805e9a410645465340c1da0cb46b6\",\"content\":\"\\\"\\\"\\\"Language-model adapter used by the ToolGuard Policies extension.\\\"\\\"\\\"\\n\\nfrom typing import Any\\n\\nfrom langchain_core.language_models.chat_models import BaseChatModel\\nfrom langchain_core.messages import messages_from_dict\\nfrom toolguard.buildtime.llm import LanguageModelBase\\n\\n\\nclass LangchainModelWrapper(LanguageModelBase):\\n    \\\"\\\"\\\"Wrapper for Langchain chat models to work with ToolGuard.\\n\\n    This wrapper handles:\\n    - Message format conversion between ToolGuard and Langchain\\n    - Automatic continuation when max tokens are reached\\n    - Safe error handling and validation\\n    \\\"\\\"\\\"\\n\\n    MAX_CONTINUATIONS = 5  # Prevent infinite recursion\\n    DEFAULT_MAX_OUT_TOKENS = 16000\\n\\n    def __init__(self, langchain_model: BaseChatModel):\\n        \\\"\\\"\\\"Initialize the wrapper with a Langchain chat model.\\n\\n        Args:\\n            langchain_model: A Langchain BaseChatModel instance\\n        \\\"\\\"\\\"\\n        self.langchain_model = langchain_model\\n        if hasattr(self.langchain_model, \\\"max_tokens\\\") and getattr(self.langchain_model, \\\"max_tokens\\\", None) is None:\\n            self.langchain_model.max_tokens = self.DEFAULT_MAX_OUT_TOKENS\\n\\n    def _convert_role(self, role: str) -> str:\\n        \\\"\\\"\\\"Convert ToolGuard role to Langchain message type.\\n\\n        Args:\\n            role: The role from ToolGuard format (\\\"user\\\", \\\"assistant\\\", \\\"system\\\")\\n\\n        Returns:\\n            Langchain message type (\\\"human\\\", \\\"ai\\\", \\\"system\\\")\\n        \\\"\\\"\\\"\\n        role_mapping = {\\n            \\\"user\\\": \\\"human\\\",\\n            \\\"assistant\\\": \\\"ai\\\",\\n            \\\"system\\\": \\\"system\\\",\\n        }\\n        return role_mapping.get(role, \\\"system\\\")\\n\\n    def _validate_messages(self, messages: list[dict]) -> None:\\n        \\\"\\\"\\\"Validate message format.\\n\\n        Args:\\n            messages: List of message dictionaries\\n\\n        Raises:\\n            ValueError: If messages are invalid\\n        \\\"\\\"\\\"\\n        if not isinstance(messages, list):\\n            msg = f\\\"Messages must be a list, got {type(messages)}\\\"\\n            raise TypeError(msg)\\n\\n        for i, msg in enumerate(messages):\\n            if not isinstance(msg, dict):\\n                error_msg = f\\\"Message at index {i} must be a dict, got {type(msg)}\\\"\\n                raise TypeError(error_msg)\\n\\n            if \\\"role\\\" not in msg:\\n                error_msg = f\\\"Message at index {i} missing 'role' field\\\"\\n                raise ValueError(error_msg)\\n\\n            if \\\"content\\\" not in msg:\\n                error_msg = f\\\"Message at index {i} missing 'content' field\\\"\\n                raise ValueError(error_msg)\\n\\n    def _extract_content(self, content: Any) -> str:\\n        \\\"\\\"\\\"Safely extract string content from various types.\\n\\n        Args:\\n            content: Content that could be str, list, tuple, or None\\n\\n        Returns:\\n            String representation of the content\\n        \\\"\\\"\\\"\\n        if content is None:\\n            return \\\"\\\"\\n\\n        if isinstance(content, str):\\n            return content\\n\\n        if isinstance(content, (list, tuple)):\\n            # Join list/tuple elements with space\\n            return \\\" \\\".join(str(item) for item in content)\\n\\n        return str(content)\\n\\n    async def generate(self, messages: list[dict], _recursion_depth: int = 0) -> str:\\n        \\\"\\\"\\\"Generate a response from the language model.\\n\\n        Args:\\n            messages: List of message dicts with 'role' and 'content' keys\\n            _recursion_depth: Internal counter to prevent infinite recursion\\n\\n        Returns:\\n            Generated text response\\n\\n        Raises:\\n            ValueError: If messages are invalid or response is malformed\\n            RuntimeError: If max continuations exceeded or API call fails\\n        \\\"\\\"\\\"\\n        # Validate inputs\\n        self._validate_messages(messages)\\n\\n        # Check recursion depth\\n        if _recursion_depth >= self.MAX_CONTINUATIONS:\\n            msg = f\\\"Maximum continuation depth ({self.MAX_CONTINUATIONS}) exceeded\\\"\\n            raise RuntimeError(msg)\\n\\n        # Convert messages to Langchain format\\n        converted_messages = [\\n            {\\n                \\\"type\\\": self._convert_role(msg.get(\\\"role\\\", \\\"system\\\")),\\n                \\\"data\\\": {\\\"content\\\": self._extract_content(msg.get(\\\"content\\\"))},\\n            }\\n            for msg in messages\\n        ]\\n\\n        try:\\n            lc_messages = messages_from_dict(converted_messages)\\n        except Exception as exc:\\n            msg = f\\\"Failed to convert messages to Langchain format: {exc}\\\"\\n            raise ValueError(msg) from exc\\n\\n        # Call the language model\\n        try:\\n            response = await self.langchain_model.agenerate(\\n                messages=[lc_messages],\\n            )\\n        except Exception as exc:\\n            msg = f\\\"Language model API call failed: {exc}\\\"\\n            raise RuntimeError(msg) from exc\\n\\n        # Safely extract response\\n        if not response.generations or not response.generations[0]:\\n            msg = \\\"Empty response from language model\\\"\\n            raise ValueError(msg)\\n\\n        choice0 = response.generations[0][0]\\n\\n        if not hasattr(choice0, \\\"message\\\") or not hasattr(choice0.message, \\\"content\\\"):\\n            msg = \\\"Malformed response from language model\\\"\\n            raise ValueError(msg)\\n\\n        chunk = self._extract_content(choice0.text)\\n\\n        # Check if we need to continue due to max tokens\\n        generation_info = getattr(choice0, \\\"generation_info\\\", None)\\n        if generation_info and isinstance(generation_info, dict):\\n            finish_reason = generation_info.get(\\\"finish_reason\\\")\\n\\n            if finish_reason == \\\"length\\\":  # max tokens reached\\n                resp_msg = {\\n                    \\\"role\\\": \\\"assistant\\\",\\n                    \\\"content\\\": chunk,\\n                }\\n                continue_msg = {\\n                    \\\"role\\\": \\\"user\\\",\\n                    \\\"content\\\": (\\n                        \\\"Continue the previous answer starting exactly from the last incomplete sentence. \\\"\\n                        \\\"Do not repeat anything. Do not add any prefix.\\\"\\n                    ),\\n                }\\n                next_messages = [\\n                    *messages,\\n                    resp_msg,\\n                    continue_msg,\\n                ]\\n\\n                # Recursive call with depth tracking\\n                continuation = await self.generate(next_messages, _recursion_depth + 1)\\n                return chunk + continuation\\n\\n        return chunk\\n\\n\\n# Made with Bob\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/module_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bbb4435cb90795369f055c760e4c97cf5beb2a7cf88f46fc0343cbfedac69924\",\"content\":\"\\\"\\\"\\\"Module-management helpers for the ToolGuard Policies extension.\\\"\\\"\\\"\\n\\nimport sys\\nfrom pathlib import Path\\nfrom types import ModuleType\\n\\n\\ndef ensure_toolguard_module_path_compat(runtime_module: ModuleType) -> None:\\n    \\\"\\\"\\\"Backport Windows module-path handling for ToolGuard's in-memory loader.\\n\\n    ToolGuard 0.2.21 converts forward slashes in generated ``FileTwin`` paths to\\n    Python module dots but leaves Windows backslashes untouched. Runtime methods\\n    resolve this module-global helper when guards are entered, so replacing it\\n    once is enough to make Windows-generated guards importable. The behavior\\n    probe leaves future fixed ToolGuard releases unchanged.\\n    \\\"\\\"\\\"\\n    converter = getattr(runtime_module, \\\"_file_to_module_name\\\", None)\\n    if not callable(converter):\\n        return\\n\\n    windows_probe = r\\\"policies\\\\guard.py\\\"\\n    posix_probe = \\\"policies/guard.py\\\"\\n    try:\\n        windows_result = converter(windows_probe)\\n        posix_result = converter(posix_probe)\\n    except Exception:  # noqa: BLE001\\n        # This is a private third-party helper; an unsupported future contract\\n        # must not prevent ToolGuard itself from importing.\\n        return\\n\\n    if (windows_result, posix_result) != (r\\\"policies\\\\guard\\\", \\\"policies.guard\\\"):\\n        # Patch only the exact ToolGuard 0.2.21 behavior. Fixed and unknown\\n        # future implementations keep their own converter.\\n        return\\n\\n    def file_to_module_name(file_path: str | Path) -> str:\\n        return str(file_path).removesuffix(\\\".py\\\").replace(\\\"\\\\\\\\\\\", \\\".\\\").replace(\\\"/\\\", \\\".\\\")\\n\\n    runtime_module.__dict__[\\\"_file_to_module_name\\\"] = file_to_module_name\\n\\n\\ndef unload_module(name: str) -> None:\\n    \\\"\\\"\\\"Remove a module and all its submodules from sys.modules.\\n\\n    This ensures complete cleanup of dynamically generated modules,\\n    including any nested imports that may have been created.\\n\\n    Args:\\n        name: The name of the module to unload\\n    \\\"\\\"\\\"\\n    # Remove the main module\\n    if name in sys.modules:\\n        del sys.modules[name]\\n\\n    # Remove all submodules (e.g., module.submodule)\\n    modules_to_remove = [mod_name for mod_name in sys.modules if mod_name.startswith(f\\\"{name}.\\\")]\\n    for mod_name in modules_to_remove:\\n        del sys.modules[mod_name]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies/tool_invoker.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"72ae3b12de6e370722aa78ff1df09b38e51a3cf048476e9d97cf0ed446c4ad63\",\"content\":\"\\\"\\\"\\\"Tool invocation adapters for the ToolGuard Policies extension.\\\"\\\"\\\"\\n\\nfrom typing import Any, TypeVar\\n\\nfrom langchain_core.messages import ToolMessage\\nfrom lfx.field_typing.constants import BaseTool\\nfrom lfx.log.logger import logger\\nfrom mcp.types import CallToolResult\\nfrom pydantic import BaseModel\\nfrom toolguard.runtime import IToolInvoker\\n\\nT = TypeVar(\\\"T\\\")\\n\\n\\nclass ToolInvoker(IToolInvoker):\\n    _tools: dict[str, BaseTool]\\n\\n    def __init__(self, tools: list[BaseTool]) -> None:\\n        self._tools = {tool.name: tool for tool in tools}\\n\\n    async def invoke(self, toolname: str, arguments: dict[str, Any], return_type: type[T]) -> T:\\n        tool = self._tools.get(toolname)\\n        if tool:\\n            logger.info(f\\\"invoking {toolname} internally\\\")\\n            res = await tool.ainvoke(input=arguments)\\n\\n            # ToolInvoker calls ainvoke without tool_call_id, so MCPStructuredTool\\n            # returns the raw CallToolResult. The ToolMessage branch below is a\\n            # defensive fallback in case that ever changes.\\n            if isinstance(res, ToolMessage) and isinstance(res.artifact, CallToolResult):\\n                res_dict = res.artifact.structuredContent\\n            elif isinstance(res, CallToolResult):\\n                res_dict = res.structuredContent\\n            elif isinstance(res, list):\\n                # Multimodal content (e.g. images) \u2014 no structured extraction applies.\\n                return res  # type: ignore[return-value]\\n            elif isinstance(res, dict) and \\\"value\\\" in res:\\n                res_dict = res[\\\"value\\\"]\\n            else:\\n                res_dict = res\\n\\n            # Only try to extract \\\"result\\\" key if res_dict is a dictionary\\n            if isinstance(res_dict, dict):\\n                res_dict = res_dict.get(\\\"result\\\", res_dict)\\n\\n            if isinstance(res_dict, BaseModel):\\n                res_dict = res_dict.model_dump()\\n\\n            if issubclass(return_type, BaseModel):\\n                return return_type.model_validate(res_dict)\\n            if return_type in (int, float, str, bool):\\n                return return_type(res_dict)\\n            return res_dict\\n\\n        msg = f\\\"unknown tool {toolname}\\\"\\n        raise ValueError(msg)\\n\\n\\n# Made with Bob\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/components/models_and_agents/policies_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"257de633d3ab517c52dd7bb113ba0da4860c11857d8c4b88f3531341f8b34873\",\"content\":\"from __future__ import annotations\\n\\nimport os\\nimport re\\nimport shutil\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, cast\\nfrom uuid import uuid4\\n\\nfrom lfx.base.models import LCModelComponent\\nfrom lfx.base.models.unified_models import (\\n    get_language_model_options,\\n    get_llm,\\n    update_model_options_in_build_config,\\n)\\nfrom lfx.field_typing import LanguageModel, Tool\\nfrom lfx.io import (\\n    BoolInput,\\n    HandleInput,\\n    ModelInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n    TabInput,\\n)\\nfrom lfx.log.logger import logger\\n\\nfrom lfx_toolguard.components.models_and_agents.policies.module_utils import (\\n    ensure_toolguard_module_path_compat,\\n    unload_module,\\n)\\n\\nif TYPE_CHECKING:\\n    from lfx.inputs.inputs import InputTypes\\n    from toolguard.buildtime import ToolGuardsCodeGenerationResult, ToolGuardSpec\\n\\n\\ndef _resolve_toolguard_work_dir() -> Path:\\n    configured_work_dir = os.getenv(\\\"TOOLGUARD_WORK_DIR\\\")\\n    if configured_work_dir:\\n        return Path(configured_work_dir)\\n    return Path(tempfile.gettempdir()) / \\\"tmp_toolguard\\\"\\n\\n\\nTOOLGUARD_WORK_DIR = _resolve_toolguard_work_dir()\\nBUILDTIME_MODELS = [\\\"gpt-5\\\", \\\"claude-sonnet\\\"]  # currently inactive, we recommend but do not enforce\\nSTEP1 = \\\"Step_1\\\"\\nSTEP2 = \\\"Step_2\\\"\\nMODE_GENERATE = \\\"\ud83d\udee0\ufe0f Generate\\\"\\nMODE_GUARD = \\\"\ud83d\udee1\ufe0f Guard\\\"\\nGENERATED_GUARD_INFO_PREFIX = \\\"Auto-generated ToolGuard code for \\\"\\n\\n_TOOLGUARD_INSTALL_HINT = (\\n    \\\"The 'toolguard' package is required to use PoliciesComponent. \\\"\\n    \\\"Install the extension extra: `pip install 'lfx[toolguard]'`.\\\"\\n)\\n\\n\\nclass PoliciesComponent(LCModelComponent):\\n    \\\"\\\"\\\"Component for building tool protection code from textual business policies and instructions.\\n\\n    This component uses ToolGuard to generate and apply policy-based guards to tools,\\n    ensuring that tool execution complies with defined business policies.\\n    Powered by ALTK ToolGuard (https://github.com/AgentToolkit/toolguard).\\n\\n    `toolguard` is supplied by the `lfx-toolguard` extension; imports happen\\n    lazily inside methods so this component can be discovered and inspected even\\n    when the extra isn't installed.\\n    \\\"\\\"\\\"\\n\\n    model_provider_policy_mode = \\\"delegate\\\"\\n    display_name = \\\"Policies\\\"\\n    description = \\\"\\\"\\\"Component for building tool protection code from textual business policies and instructions.\\nPowered by [ALTK ToolGuard](https://github.com/AgentToolkit/toolguard )\\\"\\\"\\\"\\n    documentation: str = \\\"https://github.com/AgentToolkit/toolguard\\\"\\n    icon = \\\"shield-check\\\"\\n    name = \\\"policies\\\"\\n    beta = True\\n\\n    inputs = cast(\\n        \\\"list[InputTypes]\\\",\\n        [\\n            BoolInput(\\n                name=\\\"enabled\\\",\\n                display_name=\\\"Enabled\\\",\\n                info=\\\"If `true` - guards tool calls. If `false`, skip policy validation.\\\",\\n                value=True,\\n            ),\\n            TabInput(\\n                name=\\\"mode\\\",\\n                display_name=\\\"Activity\\\",\\n                options=[MODE_GENERATE, MODE_GUARD],\\n                info=(\\n                    \\\"Generate new guard code or apply existing guard. \\\"\\n                    \\\"Review generated files in the details panel on the right.\\\"\\n                ),\\n                value=MODE_GENERATE,\\n                real_time_refresh=True,\\n                tool_mode=True,\\n            ),\\n            MultilineInput(\\n                name=\\\"project\\\",\\n                display_name=\\\"Policies Project\\\",\\n                info=\\\"Folder name of the generated code\\\",\\n                value=\\\"my_project\\\",\\n                # required=True,\\n            ),\\n            HandleInput(\\n                name=\\\"in_tools\\\",\\n                display_name=\\\"Tools\\\",\\n                input_types=[\\\"Tool\\\"],\\n                is_list=True,\\n                required=True,\\n                info=\\\"These are the tools that the agent can use to help with tasks.\\\",\\n            ),\\n            StrInput(\\n                name=\\\"policies\\\",\\n                display_name=\\\"Policies\\\",\\n                info=\\\"One or more clear, well-defined and self-contained business policies\\\",\\n                is_list=True,\\n                tool_mode=True,\\n                placeholder=\\\"Add business policy...\\\",\\n                list_add_label=\\\"Add Policy\\\",\\n                # input_types=[],\\n            ),\\n            ModelInput(\\n                name=\\\"model\\\",\\n                display_name=\\\"Language Model\\\",\\n                info=(\\n                    \\\"Select LLM for Policies buildtime. We recommend using \\\"\\n                    \\\"Anthropic Claude-Sonnet series for this task.\\\"\\n                ),\\n                real_time_refresh=True,\\n                required=True,\\n            ),\\n            SecretStrInput(\\n                name=\\\"api_key\\\",\\n                display_name=\\\"API Key\\\",\\n                info=\\\"Model Provider API key\\\",\\n                required=False,\\n                advanced=True,\\n            ),\\n        ],\\n    )\\n    outputs = [\\n        Output(\\n            display_name=\\\"Guarded Tools\\\",\\n            type_=Tool,\\n            name=\\\"guarded_tools\\\",\\n            method=\\\"guard_tools\\\",\\n            # group_outputs=True,\\n        ),\\n    ]\\n\\n    @staticmethod\\n    def _import_toolguard():\\n        \\\"\\\"\\\"Lazily import `toolguard` and the sibling helpers that depend on it.\\n\\n        Defined as a static method so it survives custom-component re-execution\\n        via `create_class`, which only re-executes the class body, not arbitrary\\n        module-level statements such as `try/except` import guards.\\n        \\\"\\\"\\\"\\n        try:\\n            import toolguard.runtime.runtime as toolguard_runtime\\n            from toolguard.buildtime import (\\n                PolicySpecOptions,\\n                ToolGuardsCodeGenerationResult,\\n                generate_guard_specs,\\n                generate_guards_code,\\n            )\\n            from toolguard.extra.langchain_to_oas import langchain_tools_to_openapi\\n            from toolguard.runtime import load_toolguards, load_toolguards_from_memory\\n            from toolguard.runtime.runtime import RESULTS_FILENAME\\n\\n            from lfx_toolguard.components.models_and_agents.policies.guard_sync_utils import (\\n                sync_generated_guard_code_inputs,\\n            )\\n            from lfx_toolguard.components.models_and_agents.policies.guarded_tool import GuardedTool\\n            from lfx_toolguard.components.models_and_agents.policies.llm_wrapper import LangchainModelWrapper\\n        except ModuleNotFoundError as e:\\n            raise ImportError(_TOOLGUARD_INSTALL_HINT) from e\\n        ensure_toolguard_module_path_compat(toolguard_runtime)\\n        return {\\n            \\\"PolicySpecOptions\\\": PolicySpecOptions,\\n            \\\"ToolGuardsCodeGenerationResult\\\": ToolGuardsCodeGenerationResult,\\n            \\\"generate_guard_specs\\\": generate_guard_specs,\\n            \\\"generate_guards_code\\\": generate_guards_code,\\n            \\\"langchain_tools_to_openapi\\\": langchain_tools_to_openapi,\\n            \\\"load_toolguards\\\": load_toolguards,\\n            \\\"load_toolguards_from_memory\\\": load_toolguards_from_memory,\\n            \\\"RESULTS_FILENAME\\\": RESULTS_FILENAME,\\n            \\\"sync_generated_guard_code_inputs\\\": sync_generated_guard_code_inputs,\\n            \\\"GuardedTool\\\": GuardedTool,\\n            \\\"LangchainModelWrapper\\\": LangchainModelWrapper,\\n        }\\n\\n    @property\\n    def work_dir(self) -> Path:\\n        \\\"\\\"\\\"Return a path isolated by user, flow, component, and project.\\\"\\\"\\\"\\n        try:\\n            user_id = self.user_id\\n        except (AttributeError, ValueError):\\n            user_id = None\\n        try:\\n            flow_id = self.flow_id\\n        except (AttributeError, ValueError):\\n            flow_id = None\\n\\n        vertex = getattr(self, \\\"_vertex\\\", None)\\n        component_id = getattr(self, \\\"_id\\\", None) or getattr(vertex, \\\"id\\\", None)\\n\\n        user_namespace = self._to_snake_case(str(user_id)) if user_id and str(user_id) != \\\"None\\\" else \\\"anonymous\\\"\\n        flow_namespace = self._to_snake_case(str(flow_id)) if flow_id else \\\"standalone\\\"\\n        if component_id:\\n            component_namespace = self._to_snake_case(str(component_id))\\n        else:\\n            instance_id = getattr(self, \\\"_toolguard_instance_id\\\", None)\\n            if instance_id is None:\\n                instance_id = uuid4().hex\\n                self._toolguard_instance_id = instance_id\\n            component_namespace = f\\\"component_{instance_id}\\\"\\n        project_namespace = self._to_snake_case(self.project)\\n        return TOOLGUARD_WORK_DIR / user_namespace / flow_namespace / component_namespace / project_namespace\\n\\n    def build_model(self) -> LanguageModel:\\n        llm_model = get_llm(\\n            model=self.model,\\n            user_id=self.user_id,\\n            api_key=self.api_key,\\n            stream=False,\\n        )\\n        if llm_model is None:\\n            msg = \\\"No language model selected. Please choose a model to proceed.\\\"\\n            raise ValueError(msg)\\n        return llm_model\\n\\n    @staticmethod\\n    def _sync_model_requirement(build_config: dict, mode: str) -> None:\\n        \\\"\\\"\\\"Require a model only when the selected activity generates guard code.\\\"\\\"\\\"\\n        if mode not in (MODE_GENERATE, MODE_GUARD):\\n            msg = f\\\"Policies: unsupported activity mode: {mode!r}\\\"\\n            raise ValueError(msg)\\n        model_config = build_config.get(\\\"model\\\")\\n        if isinstance(model_config, dict):\\n            model_config[\\\"required\\\"] = mode == MODE_GENERATE\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None):\\n        \\\"\\\"\\\"Dynamically update model options and the activity-specific requirement.\\\"\\\"\\\"\\n        updated_build_config = update_model_options_in_build_config(\\n            component=self,\\n            build_config=build_config,\\n            cache_key_prefix=\\\"language_model_options\\\",\\n            get_options_func=get_language_model_options,\\n            field_name=field_name,\\n            field_value=field_value,\\n        )\\n        selected_mode = (\\n            field_value if field_name == \\\"mode\\\" else updated_build_config.get(\\\"mode\\\", {}).get(\\\"value\\\", MODE_GENERATE)\\n        )\\n        self._sync_model_requirement(updated_build_config, selected_mode)\\n        tg = self._import_toolguard()\\n        py_module = self._to_snake_case(self.project)\\n        return tg[\\\"sync_generated_guard_code_inputs\\\"](\\n            build_config=updated_build_config,\\n            work_dir=self.work_dir,\\n            step2_subdir=STEP2,\\n            project_name=py_module,\\n        )\\n\\n    @staticmethod\\n    def _is_generated_guard_field(field: dict) -> bool:\\n        \\\"\\\"\\\"Return whether a template field contains generated ToolGuard code.\\\"\\\"\\\"\\n        return (\\n            isinstance(field, dict)\\n            and field.get(\\\"type\\\") == \\\"code\\\"\\n            and field.get(\\\"dynamic\\\") is True\\n            and isinstance(field.get(\\\"info\\\"), str)\\n            and field[\\\"info\\\"].startswith(GENERATED_GUARD_INFO_PREFIX)\\n        )\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict) -> dict:\\n        \\\"\\\"\\\"Update the static component template without dropping persisted guard code.\\\"\\\"\\\"\\n        updated_frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        updated_template = updated_frontend_node.get(\\\"template\\\")\\n        current_template = current_frontend_node.get(\\\"template\\\")\\n        if isinstance(updated_template, dict) and isinstance(current_template, dict):\\n            for field_name, field in current_template.items():\\n                if self._is_generated_guard_field(field):\\n                    updated_template[field_name] = field\\n            selected_mode = updated_template.get(\\\"mode\\\", {}).get(\\\"value\\\", MODE_GENERATE)\\n            self._sync_model_requirement(updated_template, selected_mode)\\n        return updated_frontend_node\\n\\n    async def _generate_guard_specs(self) -> list[ToolGuardSpec]:\\n        tg = self._import_toolguard()\\n        logger.debug(\\\"Starting step 1\\\")\\n        logger.debug(f\\\"model = {self.model}\\\")\\n        llm = tg[\\\"LangchainModelWrapper\\\"](self.build_model())\\n        out_dir = self.work_dir / STEP1\\n        if out_dir.exists():\\n            shutil.rmtree(out_dir)\\n        policy_text = \\\"\\\\n * \\\".join(self.policies)\\n        open_api = tg[\\\"langchain_tools_to_openapi\\\"](self.in_tools)\\n\\n        options = tg[\\\"PolicySpecOptions\\\"](example_number=4)\\n        specs = await tg[\\\"generate_guard_specs\\\"](\\n            policy_text=policy_text, tools=open_api, llm=llm, work_dir=out_dir, options=options\\n        )\\n        logger.debug(\\\"Step 1 Done\\\")\\n        return specs\\n\\n    async def _generate_guard_code(self, specs: list[ToolGuardSpec]) -> ToolGuardsCodeGenerationResult:\\n        tg = self._import_toolguard()\\n        logger.debug(\\\"Starting step 2\\\")\\n        out_dir = self.work_dir / STEP2\\n        if out_dir.exists():\\n            shutil.rmtree(out_dir)\\n        llm = tg[\\\"LangchainModelWrapper\\\"](self.build_model())\\n        app_name = self._to_snake_case(self.project)\\n        open_api = tg[\\\"langchain_tools_to_openapi\\\"](self.in_tools)\\n\\n        gen_result = await tg[\\\"generate_guards_code\\\"](\\n            tools=open_api, tool_specs=specs, work_dir=out_dir, llm=llm, app_name=app_name\\n        )\\n        logger.debug(\\\"Step 2 Done\\\")\\n        return gen_result\\n\\n    def in_recommended_models(self, model_name: str):\\n        return any(recommended in model_name for recommended in BUILDTIME_MODELS)\\n\\n    def validate_before_generate(self) -> None:\\n        \\\"\\\"\\\"Validate required inputs before generating guard code.\\\"\\\"\\\"\\n        if not self.project:\\n            msg = \\\"Policies: project cannot be empty!\\\"\\n            raise ValueError(msg)\\n\\n        if not any(self.policies):\\n            msg = \\\"Policies: policies cannot be empty!\\\"\\n            raise ValueError(msg)\\n\\n        if not self.in_tools:\\n            msg = \\\"Policies: in_tools cannot be empty!\\\"\\n            raise ValueError(msg)\\n\\n        # Only the model selection is mandatory. ``api_key`` is declared optional\\n        # (required=False, advanced=True) and is frequently supplied by the model\\n        # connection, an environment variable, or a global variable rather than by\\n        # this field \u2014 requiring it here wrongly blocked valid setups with\\n        # \\\"model or api_key cannot be empty!\\\". When credentials really are missing,\\n        # ``build_model`` -> ``get_llm`` raises a clear provider-specific error.\\n        if not self.model:\\n            msg = \\\"Policies: model cannot be empty!\\\"\\n            raise ValueError(msg)\\n\\n        # uncomment if willing to enforce certain models for buildtime\\n        # if not self.in_recommended_models(self.model[0][\\\"name\\\"]):\\n        #     msg = f\\\"Policies: model {self.model[0]['name']} is not in recommended models: {BUILDTIME_MODELS}\\\"\\n        #     raise ValueError(msg)\\n\\n    async def generate(self):\\n        specs = await self._generate_guard_specs()\\n        res = await self._generate_guard_code(specs)\\n\\n        # if there was a previous version of the guard, remove it from python cache\\n        unload_module(res.domain.app_name)\\n\\n    def _verify_cached_guards(self, code_dir: Path) -> None:\\n        tg = self._import_toolguard()\\n        # Validate cache exists before attempting to load\\n        if not code_dir.exists():\\n            msg = (\\n                f\\\"Policies: Cache directory not found at '{code_dir}'. \\\"\\n                f\\\"Please run in 'Generate' mode first to create the guard code, \\\"\\n                f\\\"or verify the project name is correct.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        try:\\n            tg[\\\"load_toolguards\\\"](code_dir)\\n        except FileNotFoundError as exc:\\n            msg = (\\n                f\\\"Policies: Required guard code files missing in '{code_dir}'. \\\"\\n                f\\\"Please run in 'Generate' mode to create the guard code.\\\"\\n            )\\n            raise ValueError(msg) from exc\\n        except Exception as exc:\\n            msg = (\\n                f\\\"Policies: Failed to load guard code from '{code_dir}'. \\\"\\n                f\\\"The cached code may be invalid or corrupted. \\\"\\n                f\\\"Try running in 'Generate' mode to rebuild the guard code. \\\"\\n                f\\\"Error: {exc!s}\\\"\\n            )\\n            raise ValueError(msg) from exc\\n\\n    def _validate_before_using_cache(self, code_dir: Path) -> None:\\n        if not self.in_tools:\\n            msg = \\\"Policies: in_tools cannot be empty!\\\"\\n            raise ValueError(msg)\\n\\n        self._verify_cached_guards(code_dir)\\n\\n    @staticmethod\\n    def _template_field_key(file_name: str | Path) -> str:\\n        r\\\"\\\"\\\"Normalize a generated file name to its node-template field key.\\n\\n        ``sync_generated_guard_code_inputs`` keys every generated CodeInput by the\\n        file's POSIX relative path (``Path.relative_to(...).as_posix()``), so the\\n        keys always use forward slashes. The toolguard result model stores\\n        ``file_name`` as a :class:`pathlib.Path`, whose ``str()`` uses the OS\\n        separator \u2014 backslashes on Windows. Reading back with ``str(file_name)``\\n        therefore misses every key on Windows, ``attrs.get(...)`` returns ``None``\\n        and the subsequent ``[\\\"value\\\"]`` raised the cryptic\\n        ``'NoneType' object is not subscriptable`` (issue #13727).\\n\\n        Normalizing through ``as_posix()`` is the exact inverse of how the keys are\\n        written, so lookups match on every platform. ``replace(\\\"\\\\\\\\\\\", \\\"/\\\")`` is a\\n        belt-and-suspenders guard for the rare case where ``file_name`` is already a\\n        string carrying Windows separators (e.g. a flow generated on Windows and\\n        opened on POSIX, where ``PurePosixPath`` would not split on backslashes).\\n        \\\"\\\"\\\"\\n        return Path(str(file_name).replace(\\\"\\\\\\\\\\\", \\\"/\\\")).as_posix()\\n\\n    def make_toolguard_result(self) -> ToolGuardsCodeGenerationResult:\\n        tg = self._import_toolguard()\\n        attrs = self.get_vertex().data[\\\"node\\\"][\\\"template\\\"]\\n        if not attrs:\\n            msg = \\\"Policies: component template data is missing. This may indicate a corrupted flow state.\\\"\\n            raise ValueError(msg)\\n\\n        def read_content(file_name: str | Path) -> str:\\n            \\\"\\\"\\\"Fetch a generated file's stored source from the node template.\\n\\n            Raises a clear, actionable error when the field is absent instead of\\n            letting a missing key surface as ``'NoneType' object is not\\n            subscriptable``. A missing field means the guard code was never\\n            generated (or only the ``pass  # FIXME`` scaffold was produced), so the\\n            fix is to re-run Generate.\\n            \\\"\\\"\\\"\\n            key = self._template_field_key(file_name)\\n            field = attrs.get(key)\\n            if field is None:\\n                msg = (\\n                    f\\\"Policies: generated guard file '{key}' is missing from the component. \\\"\\n                    f\\\"Re-run in 'Generate' mode to (re)build the guard code before guarding.\\\"\\n                )\\n                raise ValueError(msg)\\n            return field[\\\"value\\\"]\\n\\n        result_str = read_content(tg[\\\"RESULTS_FILENAME\\\"])\\n        result = tg[\\\"ToolGuardsCodeGenerationResult\\\"].model_validate_json(result_str)\\n\\n        result.domain.app_types.content = read_content(result.domain.app_types.file_name)\\n        result.domain.app_api.content = read_content(result.domain.app_api.file_name)\\n        result.domain.app_api_impl.content = read_content(result.domain.app_api_impl.file_name)\\n\\n        for tool in result.tools.values():\\n            tool.guard_file.content = read_content(tool.guard_file.file_name)\\n            for tool_item in tool.item_guard_files:\\n                tool_item.content = read_content(tool_item.file_name)\\n\\n        return result\\n\\n    @staticmethod\\n    def _code_execution_allowed() -> bool:\\n        \\\"\\\"\\\"Whether executing guard code is permitted by the deployment policy.\\n\\n        ToolGuard runs guard Python whose source comes from the component's\\n        client-editable CodeInput template values (make_toolguard_result reads\\n        attrs[...][\\\"value\\\"]) \u2014 these are NOT covered by the custom-component hash\\n        gate. So when an operator locks the deployment down with\\n        allow_custom_components=False, running that code must be refused too.\\n\\n        Fails closed to match validate_flow_for_current_settings: when the\\n        settings layer is present but the service is unavailable (returns None),\\n        execution is denied. Fail-open is reserved for the truly standalone case\\n        where the settings layer cannot be imported at all (lfx used as a bare\\n        library), which is a local/trusted context.\\n        \\\"\\\"\\\"\\n        try:\\n            from lfx.services.deps import get_settings_service\\n        except ModuleNotFoundError as exc:\\n            if exc.name not in {\\\"lfx.services\\\", \\\"lfx.services.deps\\\"}:\\n                raise\\n            return True\\n\\n        settings_service = get_settings_service()\\n        settings = getattr(settings_service, \\\"settings\\\", None) if settings_service else None\\n        if settings is None:\\n            return False\\n        return bool(getattr(settings, \\\"allow_custom_components\\\", False))\\n\\n    async def guard_tools(self) -> list[Tool]:\\n        if self.enabled:\\n            mode = getattr(self, \\\"mode\\\", MODE_GENERATE)\\n            if mode not in (MODE_GENERATE, MODE_GUARD):\\n                msg = f\\\"Policies: unsupported activity mode: {mode!r}\\\"\\n                raise ValueError(msg)\\n\\n            # Refuse to execute guard code when allow_custom_components is disabled.\\n            # Checked before importing/loading any toolguard runtime so\\n            # the client-supplied CodeInput guard values are never exec'd.\\n            if not self._code_execution_allowed():\\n                msg = (\\n                    \\\"Policies/ToolGuard executes guard code, which is disabled because \\\"\\n                    \\\"allow_custom_components is False. Set LANGFLOW_ALLOW_CUSTOM_COMPONENTS=true \\\"\\n                    \\\"to enable this component.\\\"\\n                )\\n                raise ValueError(msg)\\n            tg = self._import_toolguard()\\n            if mode == MODE_GENERATE:\\n                self.log(f\\\"Start generating guard code at {self.work_dir}\\\", name=\\\"info\\\")\\n                self.validate_before_generate()\\n                await self.generate()\\n                self.log(f\\\"Policies code generation saved to {self.work_dir}\\\", name=\\\"info\\\")\\n                self.log(\\\"Review the generated files in the details panel on the right.\\\", name=\\\"info\\\")\\n\\n            else:  # mode == MODE_GUARD\\n                if not self.in_tools:\\n                    msg = \\\"Policies: in_tools cannot be empty!\\\"\\n                    raise ValueError(msg)\\n                self.log(\\\"Using guard code stored in the component template\\\", name=\\\"info\\\")\\n                try:\\n                    tg_result = self.make_toolguard_result()\\n                    tg_runtime = tg[\\\"load_toolguards_from_memory\\\"](tg_result)\\n                    guarded_tools = [tg[\\\"GuardedTool\\\"](tool, self.in_tools, tg_runtime) for tool in self.in_tools]\\n                    return cast(\\\"list[Tool]\\\", guarded_tools)\\n                except Exception as e:\\n                    logger.exception(e)\\n                    raise\\n\\n        return self.in_tools\\n\\n    @staticmethod\\n    def _to_snake_case(human_name: str) -> str:\\n        \\\"\\\"\\\"Convert human-readable name to snake_case, sanitizing path traversal attempts.\\\"\\\"\\\"\\n        # Convert to lowercase\\n        result = human_name.lower()\\n\\n        # Replace any non-alphanumeric character (including path traversal chars) with underscore\\n        result = re.sub(r\\\"[^a-z0-9]+\\\", \\\"_\\\", result)\\n\\n        # Strip leading/trailing underscores\\n        result = result.strip(\\\"_\\\")\\n\\n        # Ensure the result contains at least one alphanumeric character\\n        if not result or not re.search(r\\\"[a-z0-9]\\\", result):\\n            msg = \\\"Project name must contain at least one alphanumeric character\\\"\\n            raise ValueError(msg)\\n\\n        return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/src/lfx_toolguard/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a1db516b4d639e949f6a75450b0e65403ad096b84a1eee69b05ced0c9c2103ee\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-toolguard\\\",\\n  \\\"version\\\": \\\"0.1.2\\\",\\n  \\\"name\\\": \\\"ToolGuard\\\",\\n  \\\"description\\\": \\\"Langflow Policies component powered by ToolGuard.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"toolguard\\\",\\n      \\\"path\\\": \\\"components/models_and_agents\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/tests/test_policies_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0f8702c611d23778a80cfa42619d6e2a8d1882adf751484c3cf438c15e4ec274\",\"content\":\"import json\\nfrom importlib.metadata import version\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nfrom lfx.components.models_and_agents import PoliciesComponent as PackagePoliciesComponent\\nfrom lfx.components.models_and_agents.policies_component import PoliciesComponent as CompatibilityPoliciesComponent\\nfrom lfx_toolguard.components.models_and_agents.policies_component import PoliciesComponent\\n\\n\\ndef test_compatibility_import_preserves_class_identity():\\n    assert CompatibilityPoliciesComponent is PoliciesComponent\\n    assert PackagePoliciesComponent is PoliciesComponent\\n    assert PoliciesComponent.__name__ == \\\"PoliciesComponent\\\"\\n\\n\\ndef test_toolguard_manifest_contract():\\n    manifest_path = Path(__file__).parents[1] / \\\"src\\\" / \\\"lfx_toolguard\\\" / \\\"extension.json\\\"\\n    manifest = json.loads(manifest_path.read_text(encoding=\\\"utf-8\\\"))\\n\\n    assert manifest[\\\"version\\\"] == version(\\\"lfx-toolguard\\\")\\n    assert manifest[\\\"bundles\\\"] == [\\n        {\\\"name\\\": \\\"toolguard\\\", \\\"path\\\": \\\"components/models_and_agents\\\"},\\n    ]\\n\\n\\ndef test_code_execution_denied_when_allow_custom_components_setting_is_missing(monkeypatch):\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: settings_service)\\n\\n    assert PoliciesComponent._code_execution_allowed() is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/toolguard/tests/test_policies_component_full.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"42320acd30b259a29632dc1db8baae9641390660864a63cc2981f12fd766e660\",\"content\":\"import tempfile\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx_toolguard.components.models_and_agents import policies_component as policies_component_module\\nfrom lfx_toolguard.components.models_and_agents.policies_component import (\\n    MODE_GENERATE,\\n    MODE_GUARD,\\n    STEP2,\\n    PoliciesComponent,\\n)\\n\\n\\n@pytest.fixture\\ndef mock_tool():\\n    \\\"\\\"\\\"Create a mock tool for testing.\\\"\\\"\\\"\\n    tool = MagicMock()\\n    tool.name = \\\"test_tool\\\"\\n    tool.description = \\\"A test tool\\\"\\n    tool.tags = []\\n    tool.metadata = {}\\n    return tool\\n\\n\\n@pytest.fixture\\ndef mock_component(mock_tool):\\n    \\\"\\\"\\\"Create a PoliciesComponent instance with mocked dependencies.\\\"\\\"\\\"\\n    with patch.object(PoliciesComponent, \\\"user_id\\\", new_callable=lambda: property(lambda _: \\\"test_user_123\\\")):\\n        component = PoliciesComponent()\\n        component.project = \\\"test_project\\\"\\n        component.in_tools = [mock_tool]\\n        component.policies = [\\\"Policy 1: Do not allow negative numbers\\\", \\\"Policy 2: Validate input\\\"]\\n        component.model = [{\\\"name\\\": \\\"gpt-5.1\\\", \\\"provider\\\": \\\"OpenAI\\\"}]\\n        component.api_key = \\\"test_api_key\\\"  # pragma: allowlist secret\\n        component.enabled = True\\n        component.mode = MODE_GUARD\\n        return component\\n\\n\\ndef _make_fake_tg(**overrides):\\n    \\\"\\\"\\\"Build a fake toolguard-imports dict for use with `_import_toolguard` patching.\\n\\n    Mirrors the keys returned by `PoliciesComponent._import_toolguard()`; tests\\n    can override individual entries to assert specific call wiring.\\n    \\\"\\\"\\\"\\n    fake = {\\n        \\\"PolicySpecOptions\\\": MagicMock(),\\n        \\\"ToolGuardsCodeGenerationResult\\\": MagicMock(),\\n        \\\"generate_guard_specs\\\": MagicMock(),\\n        \\\"generate_guards_code\\\": MagicMock(),\\n        \\\"langchain_tools_to_openapi\\\": MagicMock(),\\n        \\\"load_toolguards\\\": MagicMock(),\\n        \\\"load_toolguards_from_memory\\\": MagicMock(),\\n        \\\"RESULTS_FILENAME\\\": \\\"results.json\\\",\\n        \\\"sync_generated_guard_code_inputs\\\": MagicMock(),\\n        \\\"GuardedTool\\\": MagicMock(),\\n        \\\"LangchainModelWrapper\\\": MagicMock(),\\n    }\\n    fake.update(overrides)\\n    return fake\\n\\n\\n@pytest.fixture\\ndef custom_component_execution_enabled(monkeypatch):\\n    \\\"\\\"\\\"Enable ToolGuard code execution for tests that exercise cache behavior.\\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=True)),\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_guard_tools_blocked_when_custom_components_disabled(mock_component, monkeypatch):\\n    \\\"\\\"\\\"ToolGuard guard execution must be refused under allow_custom_components=False.\\n\\n    Regression test: the guard code comes from client-editable CodeInput\\n    template values that bypass the custom-component hash gate, so a locked-down\\n    deployment must refuse to execute it. The refusal happens before any toolguard\\n    import/exec.\\n    \\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False)),\\n    )\\n\\n    # The refusal must happen before any toolguard runtime is imported/exec'd.\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\") as mock_import,\\n        pytest.raises(ValueError, match=\\\"allow_custom_components\\\"),\\n    ):\\n        await mock_component.guard_tools()\\n    mock_import.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_guard_tools_allowed_when_custom_components_enabled(mock_component, monkeypatch):\\n    \\\"\\\"\\\"ToolGuard guard execution must reach the runtime when allow_custom_components=True.\\n\\n    Pins the allow side of the gate: with the flag enabled, guard_tools() must get\\n    past _code_execution_allowed() and import the toolguard runtime. Without this,\\n    a future flip of the default would silently bypass the security gate and only\\n    the blocked path would be covered.\\n    \\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=True)),\\n    )\\n\\n    fake_tg = _make_fake_tg()\\n    fake_tg[\\\"load_toolguards_from_memory\\\"].return_value = MagicMock()\\n    fake_tg[\\\"GuardedTool\\\"].return_value = MagicMock()\\n\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg) as mock_import,\\n        patch.object(mock_component, \\\"make_toolguard_result\\\", return_value=MagicMock()),\\n    ):\\n        await mock_component.guard_tools()\\n\\n    mock_import.assert_called()\\n    fake_tg[\\\"load_toolguards\\\"].assert_not_called()\\n\\n\\n@pytest.mark.usefixtures(\\\"custom_component_execution_enabled\\\")\\nasync def test_guard_mode_loads_persisted_template_without_cache_directory(mock_component, mock_tool):\\n    \\\"\\\"\\\"Guard mode reconstructs generated guards from the flow template.\\\"\\\"\\\"\\n    fake_tg = _make_fake_tg()\\n    mock_tg_result = MagicMock()\\n    mock_tg_runtime = MagicMock()\\n    fake_tg[\\\"load_toolguards_from_memory\\\"].return_value = mock_tg_runtime\\n    mock_guarded_instance = MagicMock()\\n    fake_tg[\\\"GuardedTool\\\"].return_value = mock_guarded_instance\\n\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n        patch.object(mock_component, \\\"make_toolguard_result\\\") as mock_make_result,\\n    ):\\n        mock_make_result.return_value = mock_tg_result\\n\\n        result = await mock_component.guard_tools()\\n\\n        mock_make_result.assert_called_once()\\n        fake_tg[\\\"load_toolguards_from_memory\\\"].assert_called_once_with(mock_tg_result)\\n        assert fake_tg[\\\"GuardedTool\\\"].call_count == len(mock_component.in_tools)\\n        fake_tg[\\\"GuardedTool\\\"].assert_called_with(mock_tool, mock_component.in_tools, mock_tg_runtime)\\n        assert len(result) == 1\\n        assert result[0] == mock_guarded_instance\\n        fake_tg[\\\"load_toolguards\\\"].assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"custom_component_execution_enabled\\\")\\nasync def test_guard_mode_requires_tools(mock_component):\\n    \\\"\\\"\\\"Guard mode rejects an empty tool list before loading persisted code.\\\"\\\"\\\"\\n    mock_component.in_tools = []\\n    fake_tg = _make_fake_tg()\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n        pytest.raises(ValueError, match=\\\"in_tools cannot be empty\\\"),\\n    ):\\n        await mock_component.guard_tools()\\n    fake_tg[\\\"load_toolguards_from_memory\\\"].assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.usefixtures(\\\"custom_component_execution_enabled\\\")\\nasync def test_guard_tools_rejects_unsupported_mode(mock_component):\\n    mock_component.mode = \\\"unsupported\\\"\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\") as mock_import,\\n        pytest.raises(ValueError, match=\\\"unsupported activity mode\\\"),\\n    ):\\n        await mock_component.guard_tools()\\n    mock_import.assert_not_called()\\n\\n\\n# @pytest.mark.asyncio\\n# async def test_cache_mode_multiple_tools(mock_component):\\n#     \\\"\\\"\\\"Test PoliciesComponent in cache mode with multiple tools.\\\"\\\"\\\"\\n#     # Add more tools\\n#     tool2 = MagicMock()\\n#     tool2.name = \\\"tool2\\\"\\n#     tool3 = MagicMock()\\n#     tool3.name = \\\"tool3\\\"\\n#     mock_component.in_tools = [mock_component.in_tools[0], tool2, tool3]\\n\\n#     with (\\n#         patch.object(Path, \\\"exists\\\", return_value=True),\\n#         patch.object(mock_component, \\\"make_toolguard_result\\\") as mock_make_result,\\n#         patch(\\\"lfx.components.models_and_agents.policies_component.load_toolguards_from_memory\\\") as mock_load_memory,\\n#         patch(\\\"lfx.components.models_and_agents.policies_component.GuardedTool\\\") as mock_guarded_tool,\\n#     ):\\n#         mock_tg_result = MagicMock()\\n#         mock_make_result.return_value = mock_tg_result\\n#         mock_tg_runtime = MagicMock()\\n#         mock_load_memory.return_value = mock_tg_runtime\\n#         mock_guarded_instances = [MagicMock(), MagicMock(), MagicMock()]\\n#         mock_guarded_tool.side_effect = mock_guarded_instances\\n\\n#         result = await mock_component.guard_tools()\\n\\n#         # Verify GuardedTool was created for each tool\\n#         assert mock_guarded_tool.call_count == 3\\n#         assert len(result) == 3\\n#         assert result == mock_guarded_instances\\n\\n\\n@pytest.mark.asyncio\\nasync def test_inenabled_returns_original_tools(mock_component, mock_tool):\\n    \\\"\\\"\\\"Test PoliciesComponent when enabled=False returns original tools.\\\"\\\"\\\"\\n    mock_component.enabled = False\\n\\n    result = await mock_component.guard_tools()\\n\\n    # Should return original tools without wrapping\\n    assert result == mock_component.in_tools\\n    assert len(result) == 1\\n    assert result[0] == mock_tool\\n\\n\\n@pytest.mark.asyncio\\nasync def test_generate_mode_validation_errors(mock_component):\\n    \\\"\\\"\\\"Test PoliciesComponent in generate mode with validation errors.\\\"\\\"\\\"\\n    mock_component.mode = MODE_GENERATE\\n    fake_tg = _make_fake_tg()\\n\\n    with patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg):\\n        # Test empty project\\n        mock_component.project = \\\"\\\"\\n        with pytest.raises(ValueError):  # noqa: PT011\\n            await mock_component.guard_tools()\\n\\n        # Test empty policies\\n        mock_component.project = \\\"test_project\\\"\\n        mock_component.policies = []\\n        with pytest.raises(ValueError, match=\\\"policies cannot be empty\\\"):\\n            await mock_component.guard_tools()\\n\\n        # Test empty tools\\n        mock_component.policies = [\\\"Policy 1\\\"]\\n        mock_component.in_tools = []\\n        with pytest.raises(ValueError, match=\\\"in_tools cannot be empty\\\"):\\n            await mock_component.guard_tools()\\n\\n        # Test missing model\\n        mock_component.in_tools = [MagicMock()]\\n        mock_component.model = None\\n        with pytest.raises(ValueError, match=\\\"model cannot be empty\\\"):\\n            await mock_component.guard_tools()\\n\\n    # # Test non-recommended model\\n    # mock_component.model = [{\\\"name\\\": \\\"gpt-3.5-turbo\\\", \\\"provider\\\": \\\"OpenAI\\\"}]\\n    # mock_component.api_key = \\\"test_key\\\"  # pragma: allowlist secret\\n    # with pytest.raises(ValueError, match=\\\"is not in recommended models\\\"):\\n    #     await mock_component.guard_tools()\\n\\n\\ndef test_work_dir_property(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"Test work_dir property generates correct path.\\\"\\\"\\\"\\n    monkeypatch.setattr(policies_component_module, \\\"TOOLGUARD_WORK_DIR\\\", tmp_path)\\n    component = PoliciesComponent()\\n    component.project = \\\"test project\\\"\\n    work_dir = component.work_dir\\n\\n    assert work_dir.is_relative_to(tmp_path)\\n    assert work_dir.is_absolute()\\n    assert \\\"test_project\\\" in str(work_dir)\\n    assert work_dir.name == \\\"test_project\\\"\\n\\n\\ndef test_resolve_work_dir_uses_temp_directory_by_default(monkeypatch):\\n    \\\"\\\"\\\"The default work directory is writable and independent of the current directory.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"TOOLGUARD_WORK_DIR\\\", raising=False)\\n\\n    assert policies_component_module._resolve_toolguard_work_dir() == Path(tempfile.gettempdir()) / \\\"tmp_toolguard\\\"\\n\\n\\ndef test_resolve_work_dir_honors_environment_override(monkeypatch, tmp_path):\\n    \\\"\\\"\\\"Deployments can configure a dedicated ToolGuard work directory.\\\"\\\"\\\"\\n    configured_work_dir = tmp_path / \\\"toolguard\\\"\\n    monkeypatch.setenv(\\\"TOOLGUARD_WORK_DIR\\\", str(configured_work_dir))\\n\\n    assert policies_component_module._resolve_toolguard_work_dir() == configured_work_dir\\n\\n\\ndef test_work_dir_reuses_standalone_component_identity():\\n    \\\"\\\"\\\"Recreated standalone components with the same ID reuse generated guards.\\\"\\\"\\\"\\n\\n    def _component() -> PoliciesComponent:\\n        component = PoliciesComponent()\\n        component.project = \\\"shared project\\\"\\n        component._id = \\\"policies-node\\\"\\n        return component\\n\\n    first = _component()\\n    recreated = _component()\\n\\n    assert first.work_dir == recreated.work_dir\\n    assert first.work_dir.parts[-4:] == (\\\"anonymous\\\", \\\"standalone\\\", \\\"policies_node\\\", \\\"shared_project\\\")\\n\\n\\ndef test_work_dir_isolates_flows_and_components_with_the_same_project():\\n    \\\"\\\"\\\"Identical project names cannot share generated guards across runtime identities.\\\"\\\"\\\"\\n\\n    def _component(flow_id: str, component_id: str) -> PoliciesComponent:\\n        component = PoliciesComponent()\\n        component.project = \\\"shared project\\\"\\n        component._vertex = SimpleNamespace(\\n            id=component_id,\\n            graph=SimpleNamespace(flow_id=flow_id, user_id=\\\"shared-user\\\"),\\n        )\\n        return component\\n\\n    flow_a_node_a = _component(\\\"flow-a\\\", \\\"policies-a\\\")\\n    flow_b_node_a = _component(\\\"flow-b\\\", \\\"policies-a\\\")\\n    flow_a_node_b = _component(\\\"flow-a\\\", \\\"policies-b\\\")\\n\\n    work_dirs = {\\n        flow_a_node_a.work_dir,\\n        flow_b_node_a.work_dir,\\n        flow_a_node_b.work_dir,\\n    }\\n    assert len(work_dirs) == 3\\n    assert all(work_dir.name == \\\"shared_project\\\" for work_dir in work_dirs)\\n\\n\\ndef test_to_snake_case():\\n    \\\"\\\"\\\"Test _to_snake_case static method.\\\"\\\"\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"My Project\\\") == \\\"my_project\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"Test-Project\\\") == \\\"test_project\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"User's Project\\\") == \\\"user_s_project\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"Project, Name\\\") == \\\"project_name\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"UPPERCASE\\\") == \\\"uppercase\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"Mixed-Case Project's Name\\\") == \\\"mixed_case_project_s_name\\\"\\n\\n    # Test path traversal prevention\\n    assert PoliciesComponent._to_snake_case(\\\"../../etc/passwd\\\") == \\\"etc_passwd\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"../../../root\\\") == \\\"root\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"./hidden\\\") == \\\"hidden\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"path/to/file\\\") == \\\"path_to_file\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"back\\\\\\\\slash\\\\\\\\path\\\") == \\\"back_slash_path\\\"\\n\\n    # Test special characters are sanitized\\n    assert PoliciesComponent._to_snake_case(\\\"test@#$%project\\\") == \\\"test_project\\\"\\n    assert PoliciesComponent._to_snake_case(\\\"___multiple___underscores___\\\") == \\\"multiple_underscores\\\"\\n\\n    # Test empty/invalid input\\n    with pytest.raises(ValueError, match=\\\"must contain at least one alphanumeric character\\\"):\\n        PoliciesComponent._to_snake_case(\\\"...\\\")\\n    with pytest.raises(ValueError, match=\\\"must contain at least one alphanumeric character\\\"):\\n        PoliciesComponent._to_snake_case(\\\"___\\\")\\n    with pytest.raises(ValueError, match=\\\"must contain at least one alphanumeric character\\\"):\\n        PoliciesComponent._to_snake_case(\\\"@#$%\\\")\\n\\n\\ndef test_in_recommended_models(mock_component):\\n    \\\"\\\"\\\"Test in_recommended_models method.\\\"\\\"\\\"\\n    assert mock_component.in_recommended_models(\\\"gpt-5.1\\\") is True\\n    assert mock_component.in_recommended_models(\\\"claude-sonnet-4\\\") is True\\n    assert mock_component.in_recommended_models(\\\"gpt-5.1-turbo\\\") is True\\n    assert mock_component.in_recommended_models(\\\"claude-sonnet-4-preview\\\") is True\\n    assert mock_component.in_recommended_models(\\\"gpt-4\\\") is False\\n    assert mock_component.in_recommended_models(\\\"gpt-3.5-turbo\\\") is False\\n    assert mock_component.in_recommended_models(\\\"claude-3\\\") is False\\n\\n\\n@pytest.mark.asyncio\\nasync def test_verify_cached_guards_error_messages(mock_component):\\n    \\\"\\\"\\\"Test that _verify_cached_guards provides helpful error messages.\\\"\\\"\\\"\\n    code_dir = mock_component.work_dir / STEP2\\n\\n    # Test directory not found error message\\n    fake_tg = _make_fake_tg()\\n    with (\\n        patch.object(Path, \\\"exists\\\", return_value=False),\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n    ):\\n        with pytest.raises(ValueError, match=\\\"Cache directory not found\\\") as exc_info:\\n            mock_component._verify_cached_guards(code_dir)\\n\\n        assert \\\"Generate\\\" in str(exc_info.value)\\n        assert str(code_dir) in str(exc_info.value)\\n\\n    # Test file not found error message\\n    fake_tg = _make_fake_tg()\\n    fake_tg[\\\"load_toolguards\\\"].side_effect = FileNotFoundError(\\\"Missing file\\\")\\n    with (\\n        patch.object(Path, \\\"exists\\\", return_value=True),\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n    ):\\n        with pytest.raises(ValueError, match=\\\"Required guard code files missing\\\") as exc_info:\\n            mock_component._verify_cached_guards(code_dir)\\n\\n        assert \\\"Generate\\\" in str(exc_info.value)\\n\\n    # Test general error message\\n    fake_tg = _make_fake_tg()\\n    fake_tg[\\\"load_toolguards\\\"].side_effect = RuntimeError(\\\"Unexpected error\\\")\\n    with (\\n        patch.object(Path, \\\"exists\\\", return_value=True),\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n    ):\\n        with pytest.raises(ValueError, match=\\\"Failed to load guard code\\\") as exc_info:\\n            mock_component._verify_cached_guards(code_dir)\\n\\n        assert \\\"corrupted\\\" in str(exc_info.value)\\n        assert \\\"Unexpected error\\\" in str(exc_info.value)\\n\\n\\ndef test_template_field_key_normalizes_separators():\\n    \\\"\\\"\\\"Node-template keys are POSIX; OS-separator file names must normalize to match.\\n\\n    Regression for #13727: on Windows the toolguard result stores ``file_name`` as\\n    a Path whose ``str()`` uses backslashes, while ``sync_generated_guard_code_inputs``\\n    keys the template by ``Path.as_posix()`` (forward slashes). The lookup must\\n    normalize so it matches on every platform.\\n    \\\"\\\"\\\"\\n    # Forward-slash input is unchanged.\\n    assert PoliciesComponent._template_field_key(\\\"proj/fetch_content/guard.py\\\") == \\\"proj/fetch_content/guard.py\\\"\\n    # Backslash input (what str(WindowsPath(...)) yields) normalizes to forward slashes.\\n    assert PoliciesComponent._template_field_key(\\\"proj\\\\\\\\fetch_content\\\\\\\\guard.py\\\") == \\\"proj/fetch_content/guard.py\\\"\\n    # Path inputs normalize too.\\n    assert PoliciesComponent._template_field_key(Path(\\\"proj/fetch_content/guard.py\\\")) == \\\"proj/fetch_content/guard.py\\\"\\n    # Single-segment names (e.g. result.json) are unaffected.\\n    assert PoliciesComponent._template_field_key(\\\"result.json\\\") == \\\"result.json\\\"\\n\\n\\ndef _fake_file_twin(file_name):\\n    \\\"\\\"\\\"A stand-in for toolguard's FileTwin: a ``file_name`` plus assignable ``content``.\\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    return SimpleNamespace(file_name=file_name, content=None)\\n\\n\\ndef test_make_toolguard_result_reads_posix_keyed_fields(mock_component):\\n    \\\"\\\"\\\"make_toolguard_result must read fields the sync step keyed by POSIX path.\\n\\n    Regression for #13727 (the 'NoneType' object is not subscriptable crash on\\n    Windows). The toolguard result hands back ``file_name`` values using OS\\n    separators (here simulated with backslashes, exactly as ``str(WindowsPath)``\\n    produces), while the node template is keyed by forward-slash POSIX paths. The\\n    read path must normalize and match instead of returning ``None``.\\n    \\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    # file_name values as they arrive from the result model on Windows (backslashes).\\n    types_fn = \\\"proj\\\\\\\\proj_types.py\\\"\\n    api_fn = \\\"proj\\\\\\\\proj_api.py\\\"\\n    impl_fn = \\\"proj\\\\\\\\proj_api_impl.py\\\"\\n    guard_fn = \\\"proj\\\\\\\\fetch_content\\\\\\\\guard.py\\\"\\n    item_fn = \\\"proj\\\\\\\\fetch_content\\\\\\\\guard_allowed_url_domains.py\\\"\\n\\n    fake_result = SimpleNamespace(\\n        domain=SimpleNamespace(\\n            app_types=_fake_file_twin(types_fn),\\n            app_api=_fake_file_twin(api_fn),\\n            app_api_impl=_fake_file_twin(impl_fn),\\n        ),\\n        tools={\\n            \\\"fetch_content\\\": SimpleNamespace(\\n                guard_file=_fake_file_twin(guard_fn),\\n                item_guard_files=[_fake_file_twin(item_fn)],\\n            )\\n        },\\n    )\\n\\n    # Template keyed by POSIX paths, exactly as sync_generated_guard_code_inputs writes them.\\n    attrs = {\\n        \\\"result.json\\\": {\\\"value\\\": \\\"{}\\\"},\\n        \\\"proj/proj_types.py\\\": {\\\"value\\\": \\\"types-content\\\"},\\n        \\\"proj/proj_api.py\\\": {\\\"value\\\": \\\"api-content\\\"},\\n        \\\"proj/proj_api_impl.py\\\": {\\\"value\\\": \\\"impl-content\\\"},\\n        \\\"proj/fetch_content/guard.py\\\": {\\\"value\\\": \\\"guard-content\\\"},\\n        \\\"proj/fetch_content/guard_allowed_url_domains.py\\\": {\\\"value\\\": \\\"item-content\\\"},\\n    }\\n\\n    fake_tg = _make_fake_tg(RESULTS_FILENAME=\\\"result.json\\\")\\n    fake_tg[\\\"ToolGuardsCodeGenerationResult\\\"].model_validate_json.return_value = fake_result\\n\\n    mock_component.get_vertex = MagicMock(return_value=SimpleNamespace(data={\\\"node\\\": {\\\"template\\\": attrs}}))\\n\\n    with patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg):\\n        result = mock_component.make_toolguard_result()\\n\\n    assert result is fake_result\\n    assert result.domain.app_types.content == \\\"types-content\\\"\\n    assert result.domain.app_api.content == \\\"api-content\\\"\\n    assert result.domain.app_api_impl.content == \\\"impl-content\\\"\\n    assert result.tools[\\\"fetch_content\\\"].guard_file.content == \\\"guard-content\\\"\\n    assert result.tools[\\\"fetch_content\\\"].item_guard_files[0].content == \\\"item-content\\\"\\n\\n\\ndef test_make_toolguard_result_missing_field_raises_clear_error(mock_component):\\n    \\\"\\\"\\\"A missing generated field yields a clear ValueError, not a NoneType subscript.\\n\\n    Before #13727's fix a missing key surfaced as\\n    ``'NoneType' object is not subscriptable``; it must now point the user at\\n    Generate mode instead.\\n    \\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    fake_result = SimpleNamespace(\\n        domain=SimpleNamespace(\\n            app_types=_fake_file_twin(\\\"proj/proj_types.py\\\"),\\n            app_api=_fake_file_twin(\\\"proj/proj_api.py\\\"),\\n            app_api_impl=_fake_file_twin(\\\"proj/proj_api_impl.py\\\"),\\n        ),\\n        tools={},\\n    )\\n\\n    # app_types key is intentionally absent from the template.\\n    attrs = {\\n        \\\"result.json\\\": {\\\"value\\\": \\\"{}\\\"},\\n        \\\"proj/proj_api.py\\\": {\\\"value\\\": \\\"api-content\\\"},\\n        \\\"proj/proj_api_impl.py\\\": {\\\"value\\\": \\\"impl-content\\\"},\\n    }\\n\\n    fake_tg = _make_fake_tg(RESULTS_FILENAME=\\\"result.json\\\")\\n    fake_tg[\\\"ToolGuardsCodeGenerationResult\\\"].model_validate_json.return_value = fake_result\\n\\n    mock_component.get_vertex = MagicMock(return_value=SimpleNamespace(data={\\\"node\\\": {\\\"template\\\": attrs}}))\\n\\n    with (\\n        patch.object(PoliciesComponent, \\\"_import_toolguard\\\", return_value=fake_tg),\\n        pytest.raises(ValueError, match=\\\"missing from the component\\\"),\\n    ):\\n        mock_component.make_toolguard_result()\\n\\n\\ndef test_validate_before_generate_allows_empty_api_key(mock_component):\\n    \\\"\\\"\\\"api_key is optional: validation passes when only the model is set.\\n\\n    The field is declared required=False/advanced=True and credentials often come\\n    from the model connection or environment, so requiring api_key here wrongly\\n    blocked valid setups (the \\\"model or api_key cannot be empty!\\\" wart in #13727).\\n    \\\"\\\"\\\"\\n    mock_component.api_key = \\\"\\\"\\n    mock_component.model = [{\\\"name\\\": \\\"gpt-5.1\\\", \\\"provider\\\": \\\"OpenAI\\\"}]\\n    # Should not raise.\\n    mock_component.validate_before_generate()\\n\\n\\ndef test_validate_before_generate_still_requires_model(mock_component):\\n    \\\"\\\"\\\"A missing model is still rejected after relaxing the api_key requirement.\\\"\\\"\\\"\\n    mock_component.api_key = \\\"\\\"\\n    mock_component.model = None\\n    with pytest.raises(ValueError, match=\\\"model cannot be empty\\\"):\\n        mock_component.validate_before_generate()\\n\\n\\n# Made with Bob\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ca60b51d822116e6daa86ef12fe53137afeedeee35eee6672071fc4c7295a77f\",\"content\":\"# lfx-valkey\\n\\nValkey component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-valkey\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `valkey` group with\\nthe namespaced IDs `ext:valkey:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/valkey\\npip install -e .\\nlfx extension validate src/lfx_valkey\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.valkey.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eff1143de0a51e46b70f7ed5c18a8e8ebca3588149c45d5ce0142c1cac6f57a2\",\"content\":\"[project]\\nname = \\\"lfx-valkey\\\"\\nversion = \\\"0.1.3\\\"\\ndescription = \\\"Valkey component(s) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"valkey\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.10.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\n#\\n# * The ``valkey`` extra on ``langchain-aws`` pulls ``valkey-glide`` /\\n#   ``valkey-glide-sync``, which publish no Windows wheels.  On Windows uv\\n#   falls back to a source build that needs ``protoc`` + Rust and fails\\n#   (\\\"Failed to find protoc in PATH\\\"), breaking ``pip install`` and the\\n#   release wheel matrix.  Gate the extra off Windows -- same pattern used\\n#   for ``ibm-db`` in the ibm bundle.  The base ``langchain-aws`` still\\n#   installs on Windows so non-Glide imports resolve; the Valkey Vector\\n#   Store (which imports ``ValkeyVectorStore`` lazily) is the only path that\\n#   requires Glide and is unsupported on Windows.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-aws[valkey]>=1.4.1,<2.0.0; sys_platform != 'win32'\\\",\\n    \\\"langchain-aws>=1.4.1,<2.0.0; sys_platform == 'win32'\\\",\\n    \\\"langchain-community>=0.4.1,<1.0.0\\\",\\n    \\\"redis>=7.4.0,<8.0.0\\\",\\n    \\\"structlog>=25.4.0,<26.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-valkey = \\\"lfx_valkey\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_valkey package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_valkey\\\"]\\ninclude = [\\n    \\\"src/lfx_valkey/extension.json\\\",\\n    \\\"src/lfx_valkey/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_valkey\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"74c2efd7e143f675cdb8599c993d0484cd78e10fa32e29f59623ebeeadd563b2\",\"content\":\"\\\"\\\"\\\"lfx-valkey: Valkey bundle.\\n\\nDistribution unit ``lfx-valkey``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:valkey:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_valkey.components.valkey.valkey import ValkeyVectorStoreComponent\\nfrom lfx_valkey.components.valkey.valkey_chat import ValkeyIndexChatMemory\\n\\n__all__ = [\\n    \\\"ValkeyIndexChatMemory\\\",\\n    \\\"ValkeyVectorStoreComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/components/valkey/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b65bad44fcbc48e2ec88622ae6b3fbec99043b5d8cd554e58504cfae6d7463a1\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``valkey`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.valkey`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.valkey.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_valkey.components.valkey.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from .valkey import ValkeyVectorStoreComponent\\n    from .valkey_chat import ValkeyIndexChatMemory\\n\\n_dynamic_imports = {\\n    \\\"ValkeyIndexChatMemory\\\": \\\"valkey_chat\\\",\\n    \\\"ValkeyVectorStoreComponent\\\": \\\"valkey\\\",\\n}\\n\\n__all__ = [\\n    \\\"ValkeyIndexChatMemory\\\",\\n    \\\"ValkeyVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/components/valkey/valkey.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9100cadc73a82948184f99cd57969b01cd2c175083c41b1c0b9ebbbceb5d4384\",\"content\":\"import structlog\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.io import HandleInput, IntInput, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\nlogger = structlog.get_logger(__name__)\\n\\n\\ndef _patch_check_index_exists():\\n    \\\"\\\"\\\"Patch langchain-aws check_index_exists to handle valkey-glide RequestError.\\n\\n    langchain-aws's check_index_exists only catches KeyError/ValueError/RuntimeError,\\n    but valkey-glide raises glide_shared.exceptions.RequestError when an index doesn't\\n    exist. This patch catches that specific exception so _create_index_if_not_exist\\n    can proceed to create the index.\\n\\n    This is a workaround until langchain-aws handles the GLIDE exception itself.\\n    \\\"\\\"\\\"\\n    try:\\n        import langchain_aws.vectorstores.valkey.base as _valkey_base\\n    except (ImportError, AttributeError):\\n        return\\n\\n    if getattr(_valkey_base, \\\"patched_check_index_exists\\\", False):\\n        return\\n\\n    try:\\n        from glide_shared.exceptions import RequestError as GlideRequestError\\n    except ImportError:\\n        return\\n\\n    _original_check = _valkey_base.check_index_exists\\n\\n    def _patched_check(client, index_name):\\n        try:\\n            return _original_check(client, index_name)\\n        except GlideRequestError:\\n            logger.debug(\\\"Valkey index does not exist yet\\\", index_name=index_name)\\n            return False\\n\\n    _valkey_base.check_index_exists = _patched_check\\n    _valkey_base.patched_check_index_exists = True\\n\\n\\nclass ValkeyVectorStoreComponent(LCVectorStoreComponent):\\n    \\\"\\\"\\\"A custom component for implementing a Vector Store using Valkey.\\\"\\\"\\\"\\n\\n    display_name: str = \\\"Valkey\\\"\\n    description: str = \\\"Implementation of Vector Store using Valkey\\\"\\n    name = \\\"Valkey\\\"\\n    icon = \\\"Valkey\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"valkey_server_url\\\", display_name=\\\"Valkey Server Connection String\\\", required=True),\\n        StrInput(name=\\\"valkey_index_name\\\", display_name=\\\"Valkey Index\\\"),\\n        *LCVectorStoreComponent.inputs,\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            value=4,\\n            advanced=True,\\n        ),\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"]),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self):\\n        import json\\n\\n        # Imported lazily because it pulls valkey-glide, which ships no Windows\\n        # wheels -- the ``valkey`` extra of langchain-aws is gated off Windows\\n        # via the platform marker in this bundle's pyproject.toml.  Keeping the\\n        # import out of module scope lets the bundle load on Windows even though\\n        # this vector store cannot run there; the Valkey Chat Memory component\\n        # (redis-py based) still works.\\n        try:\\n            from langchain_aws.vectorstores import ValkeyVectorStore\\n        except ImportError as e:\\n            msg = (\\n                \\\"Could not import valkey-glide, which backs the Valkey Vector Store. \\\"\\n                \\\"It ships no Windows wheels and is not installed on Windows; run this \\\"\\n                \\\"component on Linux or macOS. Elsewhere, install it with \\\"\\n                \\\"'pip install langchain-aws[valkey]'.\\\"\\n            )\\n            raise ImportError(msg) from e\\n\\n        _patch_check_index_exists()\\n\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        # Filter out documents with empty page_content \u2014 embedding models\\n        # (e.g. Bedrock) reject zero-length input strings.\\n        valid_documents = []\\n        for doc in documents:\\n            content = getattr(doc, \\\"page_content\\\", None) or \\\"\\\"\\n            if content.strip():\\n                valid_documents.append(doc)\\n            elif doc.metadata:\\n                doc.page_content = json.dumps(doc.metadata, default=str)\\n                valid_documents.append(doc)\\n            else:\\n                logger.warning(\\\"Valkey: skipping document with no content and no metadata\\\")\\n        documents = valid_documents\\n\\n        if not documents:\\n            if not self.valkey_index_name:\\n                msg = \\\"If no documents are provided, an index name must be provided.\\\"\\n                raise ValueError(msg)\\n\\n            return ValkeyVectorStore.from_existing_index(\\n                embedding=self.embedding,\\n                valkey_url=self.valkey_server_url,\\n                index_name=self.valkey_index_name,\\n            )\\n\\n        return ValkeyVectorStore.from_documents(\\n            documents=documents,\\n            embedding=self.embedding,\\n            valkey_url=self.valkey_server_url,\\n            index_name=self.valkey_index_name,\\n        )\\n\\n    def search_documents(self) -> list[Data]:\\n        vector_store = self.build_vector_store()\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            docs = vector_store.similarity_search(\\n                query=self.search_query,\\n                k=self.number_of_results,\\n            )\\n            data = docs_to_data(docs)\\n            self.status = data\\n            return data\\n        return []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/components/valkey/valkey_chat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1cef84512f77d38815a6d05917364b7981b63621e1ceb8a7ac3ce7e1e5d0df0d\",\"content\":\"from urllib import parse\\n\\nfrom lfx.base.memory.model import LCChatMemoryComponent\\nfrom lfx.field_typing.constants import Memory\\nfrom lfx.inputs.inputs import IntInput, MessageTextInput, SecretStrInput, StrInput\\n\\n\\nclass ValkeyIndexChatMemory(LCChatMemoryComponent):\\n    display_name = \\\"Valkey Chat Memory\\\"\\n    description = \\\"Retrieves and stores chat messages from Valkey.\\\"\\n    name = \\\"ValkeyChatMemory\\\"\\n    icon = \\\"Valkey\\\"\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"host\\\", display_name=\\\"Hostname\\\", required=True, value=\\\"localhost\\\", info=\\\"IP address or hostname.\\\"\\n        ),\\n        IntInput(name=\\\"port\\\", display_name=\\\"Port\\\", required=True, value=6379, info=\\\"Valkey Port Number.\\\"),\\n        StrInput(name=\\\"database\\\", display_name=\\\"Database\\\", required=True, value=\\\"0\\\", info=\\\"Valkey database.\\\"),\\n        MessageTextInput(\\n            name=\\\"username\\\", display_name=\\\"Username\\\", value=\\\"\\\", info=\\\"The Valkey user name.\\\", advanced=True\\n        ),\\n        SecretStrInput(\\n            name=\\\"password\\\",\\n            display_name=\\\"Valkey Password\\\",\\n            info=\\\"Password for the specified username.\\\",\\n            advanced=True,\\n            load_from_db=False,\\n        ),\\n        StrInput(name=\\\"key_prefix\\\", display_name=\\\"Key prefix\\\", info=\\\"Key prefix.\\\", advanced=True),\\n        MessageTextInput(\\n            name=\\\"session_id\\\", display_name=\\\"Session ID\\\", info=\\\"Session ID for the message.\\\", advanced=True\\n        ),\\n    ]\\n\\n    def build_message_history(self) -> Memory:\\n        from langchain_community.chat_message_histories.redis import RedisChatMessageHistory\\n\\n        kwargs = {}\\n        if self.key_prefix:\\n            kwargs[\\\"key_prefix\\\"] = self.key_prefix\\n\\n        # Build URL, only include auth if credentials are actually provided\\n        password = getattr(self, \\\"password\\\", None)\\n        username = getattr(self, \\\"username\\\", None)\\n        has_password = bool(password) and str(password).strip() not in (\\\"\\\", \\\"None\\\")\\n        has_username = bool(username) and str(username).strip() not in (\\\"\\\", \\\"None\\\")\\n\\n        if has_password:\\n            # Use quote(safe=\\\"\\\") so every reserved char (space, +, /, :, @) is\\n            # percent-encoded. redis-py's from_url parses the URL with urlparse\\n            # and decodes credentials with unquote (not unquote_plus), so\\n            # quote_plus would turn a space into \\\"+\\\" and round-trip to a wrong\\n            # password.\\n            encoded_pw = parse.quote(str(password), safe=\\\"\\\")\\n            encoded_username = parse.quote(str(username), safe=\\\"\\\") if has_username else \\\"\\\"\\n            auth = f\\\"{encoded_username}:{encoded_pw}@\\\"\\n        else:\\n            auth = \\\"\\\"\\n\\n        url = f\\\"redis://{auth}{self.host}:{self.port}/{self.database}\\\"\\n        return RedisChatMessageHistory(session_id=self.session_id, url=url, **kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/src/lfx_valkey/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cce1268ea62eab666fc0980e7c055cdd90b65250d3abb1f2ae19901f3abed16c\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-valkey\\\",\\n  \\\"version\\\": \\\"0.1.3\\\",\\n  \\\"name\\\": \\\"Valkey\\\",\\n  \\\"description\\\": \\\"Valkey component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"valkey\\\",\\n      \\\"path\\\": \\\"components/valkey\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/tests/test_valkey.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"861acb39c1332432096c52385d2595846ccb0a3fd6c05133ace38a00c299656d\",\"content\":\"\\\"\\\"\\\"Unit tests for ValkeyVectorStoreComponent.\\\"\\\"\\\"\\n\\nimport sys\\nfrom types import ModuleType\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent\\nfrom lfx.io import HandleInput, IntInput, SecretStrInput, StrInput\\nfrom lfx_valkey.components.valkey.valkey import ValkeyVectorStoreComponent\\n\\n# Create a mock for langchain_aws.vectorstores\\n_mock_aws_module = ModuleType(\\\"langchain_aws\\\")\\n_mock_vectorstores_module = ModuleType(\\\"langchain_aws.vectorstores\\\")\\n_MockValkeyVectorStore = MagicMock()\\n_mock_vectorstores_module.ValkeyVectorStore = _MockValkeyVectorStore\\n_mock_aws_module.vectorstores = _mock_vectorstores_module\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _mock_langchain_aws():\\n    \\\"\\\"\\\"Mock langchain_aws so tests work without it installed.\\\"\\\"\\\"\\n    modules = {\\n        \\\"langchain_aws\\\": _mock_aws_module,\\n        \\\"langchain_aws.vectorstores\\\": _mock_vectorstores_module,\\n    }\\n    with patch.dict(sys.modules, modules):\\n        yield\\n    _MockValkeyVectorStore.reset_mock()\\n\\n\\nclass TestValkeyVectorStoreComponentMetadata:\\n    def test_display_name(self):\\n        assert ValkeyVectorStoreComponent.display_name == \\\"Valkey\\\"\\n\\n    def test_icon(self):\\n        assert ValkeyVectorStoreComponent.icon == \\\"Valkey\\\"\\n\\n    def test_name(self):\\n        assert ValkeyVectorStoreComponent.name == \\\"Valkey\\\"\\n\\n    def test_description(self):\\n        assert ValkeyVectorStoreComponent.description == \\\"Implementation of Vector Store using Valkey\\\"\\n\\n\\nclass TestValkeyVectorStoreComponentInheritance:\\n    def test_inherits_from_lc_vector_store_component(self):\\n        assert issubclass(ValkeyVectorStoreComponent, LCVectorStoreComponent)\\n\\n\\nclass TestValkeyVectorStoreComponentInputs:\\n    def _get_input(self, name: str):\\n        for inp in ValkeyVectorStoreComponent.inputs:\\n            if inp.name == name:\\n                return inp\\n        msg = f\\\"Input '{name}' not found\\\"\\n        raise AssertionError(msg)\\n\\n    def test_valkey_server_url_input(self):\\n        inp = self._get_input(\\\"valkey_server_url\\\")\\n        assert isinstance(inp, SecretStrInput)\\n        assert inp.required is True\\n\\n    def test_valkey_index_name_input(self):\\n        inp = self._get_input(\\\"valkey_index_name\\\")\\n        assert isinstance(inp, StrInput)\\n\\n    def test_number_of_results_input(self):\\n        inp = self._get_input(\\\"number_of_results\\\")\\n        assert isinstance(inp, IntInput)\\n        assert inp.value == 4\\n        assert inp.advanced is True\\n\\n    def test_embedding_input(self):\\n        inp = self._get_input(\\\"embedding\\\")\\n        assert isinstance(inp, HandleInput)\\n        assert \\\"Embeddings\\\" in inp.input_types\\n\\n    def test_inherited_inputs_present(self):\\n        input_names = [inp.name for inp in ValkeyVectorStoreComponent.inputs]\\n        assert \\\"search_query\\\" in input_names\\n        assert \\\"ingest_data\\\" in input_names\\n\\n    def test_all_expected_input_names(self):\\n        input_names = [inp.name for inp in ValkeyVectorStoreComponent.inputs]\\n        assert \\\"valkey_server_url\\\" in input_names\\n        assert \\\"valkey_index_name\\\" in input_names\\n        assert \\\"number_of_results\\\" in input_names\\n        assert \\\"embedding\\\" in input_names\\n\\n\\nclass TestValkeyVectorStoreComponentDecorator:\\n    def test_build_vector_store_has_cached_decorator(self):\\n        assert hasattr(ValkeyVectorStoreComponent.build_vector_store, \\\"is_cached_vector_store_checked\\\")\\n\\n\\nclass TestValkeyVectorStoreComponentBehavior:\\n    def test_no_data_no_index_raises_value_error(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.ingest_data = []\\n        component.valkey_index_name = \\\"\\\"\\n        component.valkey_server_url = \\\"valkey://localhost:6379\\\"\\n        component.embedding = MagicMock()\\n        component._should_cache_vector_store = False\\n        with pytest.raises(ValueError, match=\\\"index name must be provided\\\"):\\n            component.build_vector_store()\\n\\n    def test_no_data_none_index_raises_value_error(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.ingest_data = []\\n        component.valkey_index_name = None\\n        component.valkey_server_url = \\\"valkey://localhost:6379\\\"\\n        component.embedding = MagicMock()\\n        component._should_cache_vector_store = False\\n        with pytest.raises(ValueError, match=\\\"index name must be provided\\\"):\\n            component.build_vector_store()\\n\\n    def test_no_data_with_index_calls_from_existing_index(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.ingest_data = []\\n        component.valkey_index_name = \\\"my_index\\\"\\n        component.valkey_server_url = \\\"valkey://localhost:6379\\\"\\n        component.embedding = MagicMock()\\n        component._should_cache_vector_store = False\\n        component.build_vector_store()\\n        _MockValkeyVectorStore.from_existing_index.assert_called_once_with(\\n            embedding=component.embedding,\\n            valkey_url=\\\"valkey://localhost:6379\\\",\\n            index_name=\\\"my_index\\\",\\n        )\\n\\n    def test_with_documents_calls_from_documents(self):\\n        from lfx.schema.data import Data\\n\\n        component = ValkeyVectorStoreComponent()\\n        mock_data = MagicMock(spec=Data)\\n        mock_doc = MagicMock()\\n        mock_data.to_lc_document.return_value = mock_doc\\n        component.ingest_data = [mock_data]\\n        component.valkey_index_name = \\\"my_index\\\"\\n        component.valkey_server_url = \\\"valkey://localhost:6379\\\"\\n        component.embedding = MagicMock()\\n        component._should_cache_vector_store = False\\n        component.build_vector_store()\\n        _MockValkeyVectorStore.from_documents.assert_called_once_with(\\n            documents=[mock_doc],\\n            embedding=component.embedding,\\n            valkey_url=\\\"valkey://localhost:6379\\\",\\n            index_name=\\\"my_index\\\",\\n        )\\n\\n    def test_empty_search_query_returns_empty_list(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.search_query = \\\"\\\"\\n        component.number_of_results = 4\\n        component.build_vector_store = MagicMock()\\n        result = component.search_documents()\\n        assert result == []\\n\\n    def test_blank_search_query_returns_empty_list(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.search_query = \\\"   \\\"\\n        component.number_of_results = 4\\n        component.build_vector_store = MagicMock()\\n        result = component.search_documents()\\n        assert result == []\\n\\n    def test_none_search_query_returns_empty_list(self):\\n        component = ValkeyVectorStoreComponent()\\n        component.search_query = None\\n        component.number_of_results = 4\\n        component.build_vector_store = MagicMock()\\n        result = component.search_documents()\\n        assert result == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/valkey/tests/test_valkey_chat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ef8e2016b9d5904381547e3b9c4fe3046b4631409798246edcfcbdf993be22b6\",\"content\":\"\\\"\\\"\\\"Unit tests for ValkeyIndexChatMemory.\\\"\\\"";
